/* GENERATED by tools/content-import.ts. Do not edit. Scripted scenes, band C1. r = scene requirements (focus nodes plus g:/x: nodes in two or more npc lines; nothing from accepts), d = legal day (null = never served), review = needs rewriting. */
window.SCENES_C1 = [
{"id":"sc-u52-a","unit":"u52","band":"C1","title":"El loro de Madrid","brief":"You're Tomás. Since Lucía's visit, Simón squawks her Madrid Spanish all day, and Hernando wants him cured. Hernando is much older, so use usted with him. Give Simón the Colombian way every time.","turns":[{"id":"t1","npc":"Hernando: Oiga a ese pájaro. Desde que vino la española, grita «¡Esta mañana he ido al mercado!». ¿Cómo se dice eso aquí, mijo?","npcEn":"Hernando: Listen to that bird. Since the Spanish woman came, he squawks 'This morning I have gone to the market!'. How do you say that here, son?","intent":"Say it the Colombian way: this morning you went to the market.","accept":["Esta mañana fui al mercado.","Fui al mercado esta mañana.","Aquí decimos: esta mañana fui al mercado."],"require":[{"type":"verbForm","inf":"ir","tense":"preterito","person":"yo","label":"say it with the simple past: fui"},{"type":"avoidsAny","words":["he ido"],"label":"he ido is the Madrid way; here it is fui"}],"focus":"g:spain-pasts","next":"t2"},{"id":"t2","npc":"Hernando: Ahora dice «¡Hoy me he levantado a las seis!». Para que aprenda, cuéntele usted qué hizo hoy antes de abrir el café.","npcEn":"Hernando: Now he says 'Today I have got up at six!'. So he learns, you tell him what you did today before opening the café.","intent":"Tell Simón two things you did today before opening, in the simple past.","accept":["Hoy me levanté a las cinco y preparé el pan.","Esta mañana me bañé, desayuné y bajé a la cocina.","Hoy desayuné temprano y limpié las mesas."],"require":[{"type":"anyVerbInTense","tense":"preterito","label":"use the simple past: me levanté, preparé"},{"type":"regex","pattern":"^(?!.*(?<![\\p{L}])(he|hemos)(?![\\p{L}]))","flags":"isu","label":"simple past, not he levantado"}],"focus":"g:spain-pasts","next":"t3"},{"id":"t3","npc":"Hernando: Y esta otra, que también es de la española: «¡Si hubiese sabido, habría venido antes!». ¿Usted cómo lo diría?","npcEn":"Hernando: And this one, which is also the Spanish woman's: 'If I'd known, I'd have come sooner!'. How would you say it?","intent":"Say the same sentence with your own form, hubiera: if you had known, you would have come sooner.","accept":["Si hubiera sabido, habría venido antes.","Habría venido antes si hubiera sabido.","Yo diría: si lo hubiera sabido, habría venido antes."],"require":[{"type":"regex","pattern":"\\bhubiera\\b","flags":"iu","label":"say it with hubiera (the -ra form)"}],"focus":"g:se-form-recognition","next":"t4"},{"id":"t4","npc":"Hernando: Y cuando ve a Gloria, le grita «¡Si fuese más joven, me casaría con usted!». Dígalo como se dice aquí.","npcEn":"Hernando: And when he sees Gloria, he squawks at her 'If I were younger, I'd marry you!'. Say it the way we say it here.","intent":"Say Simón's line with the -ra form: if I were younger, I'd marry you (usted).","accept":["Si fuera más joven, me casaría con usted.","Me casaría con usted si fuera más joven.","Si yo fuera más joven, me casaría con usted."],"require":[{"type":"regex","pattern":"\\bfuera\\b","flags":"iu","label":"use fuera, the -ra form of ser"}],"focus":"g:se-form-recognition","next":"t5"},{"id":"t5","npc":"Hernando: Vamos a ver si aprende. Mientras tanto, ¿me regala otro tinto?","npcEn":"Hernando: Let's see if he learns. Meanwhile, could I have another black coffee?","intent":"Say of course, and that you'll bring it right away.","accept":["Claro que sí, ya se lo traigo.","Con mucho gusto, don Hernando. Ya se lo traigo.","Claro. Ahora mismo se lo traigo."],"require":[],"focus":"g:spain-pasts","next":null}],"r":["g:commands-usted","g:commands-with-pronouns","g:conditional","g:direct-objects","g:gender-articles","g:indirect-objects","g:indirect-questions","g:perfecto-experience","g:present-er-ir","g:reflexive-routine","g:se-form-recognition","g:se-impersonal","g:ser-identity","g:si-hypothetical","g:spain-pasts"],"d":374},
{"id":"sc-u52-b","unit":"u52","band":"C1","title":"Venía a pedirle un favor","brief":"You're Tomás, visiting Marta, an editor at a small press, to ask about publishing Hernando's memoir. You don't know her, so use usted. Soften your requests, say what you've always believed and keep a few of your plans in the present.","turns":[{"id":"t1","npc":"Marta: Buenas tardes. Dígame, ¿en qué le puedo ayudar?","npcEn":"Marta: Good afternoon. Tell me, how can I help you?","intent":"Say you came to ask whether they publish memoirs, softening it with the imperfect (venía a, quería, pasaba a).","accept":["Buenas tardes. Venía a preguntarle si publican memorias.","Quería saber si ustedes publican memorias.","Pasaba a ver si publican memorias de gente mayor."],"require":[{"type":"regex","pattern":"\\b(venía|quería|pasaba|llamaba|escribía)\\b","flags":"iu","label":"soften it with the imperfect: venía a, quería, pasaba a"}],"focus":"p:imperfecto-cortesia-venia","next":"t2"},{"id":"t2","npc":"Marta: Publicamos muy pocas al año. ¿De quién es la memoria?","npcEn":"Marta: We publish very few a year. Whose memoir is it?","intent":"Say it's Hernando's, a retired taxi driver, and that you've always believed his life makes a book (siempre he creído que).","accept":["Es de Hernando, un taxista retirado. Siempre he creído que su vida da para un libro.","De un taxista retirado, Hernando. Siempre he pensado que su historia merece un libro.","Es de Hernando, un taxista de mi barrio. Siempre he pensado que cuenta su vida mejor que cualquier escritor."],"require":[{"type":"regex","pattern":"\\bhe (creído|pensado|dicho|sabido|querido)\\b","flags":"iu","label":"an opinion that still holds: siempre he creído que"}],"focus":"p:perfecto-still-live","next":"t3"},{"id":"t3","npc":"Marta: Me interesa. ¿Cuándo podría traerme un capítulo?","npcEn":"Marta: I'm interested. When could you bring me a chapter?","intent":"Say you'll bring it on Monday, using the present tense for a near plan (se lo traigo).","accept":["El lunes se lo traigo.","Se lo traigo el lunes, a primera hora.","Mañana lo reviso y el lunes se lo traigo."],"require":[{"type":"verbForm","inf":"traer","tense":"presente","person":"yo","label":"present for a near plan: se lo traigo"},{"type":"avoidsAny","words":["traeré"],"label":"here the present does the job of the future"}],"focus":"g:tense-modal-uses","next":"t4"},{"id":"t4","npc":"Marta: Será muy querido en su barrio, pero el público no lo conoce. ¿Por qué lo leerían?","npcEn":"Marta: He may be very loved in his neighbourhood, but the public doesn't know him. Why would they read him?","intent":"Concede that he may be unknown, but he has seen the city change for fifty years (será ... pero ...).","accept":["Será un desconocido, pero conoce cada calle de la ciudad.","Será desconocido, pero tiene cincuenta años de historias.","Será un desconocido, pero ha visto cambiar a Bogotá durante cincuenta años."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])ser[áa](?![\\p{L}])","flags":"iu","label":"guess with the future: será ..."},{"type":"containsWord","word":"pero","label":"add the but: pero ..."}],"focus":"g:tense-modal-uses","next":"t5"},{"id":"t5","npc":"Marta: Está bien. Tráigame el capítulo y lo leo con tiempo.","npcEn":"Marta: All right. Bring me the chapter and I'll read it when I have time.","intent":"Thank her for her time and say Hernando will be very happy.","accept":["Muchas gracias por su tiempo. Hernando va a estar muy contento.","Gracias por escucharme. Hernando se va a alegrar mucho.","Se lo agradezco mucho. Hernando va a estar feliz."],"require":[{"type":"regex","pattern":"^(?!.*(?<![\\p{L}])(tu|tus|te)(?![\\p{L}]))","flags":"isu","label":"you are on usted terms: su, not tu"}],"focus":"g:tense-modal-uses","next":null}],"r":["g:commands-usted","g:commands-with-pronouns","g:conditional","g:direct-objects","g:gender-articles","g:present-ar","g:present-er-ir","g:ser-identity","g:tense-modal-uses","g:verb-infinitive","p:imperfecto-cortesia-venia","p:perfecto-still-live"],"d":551},
{"id":"sc-u52-c","unit":"u52","band":"C1","title":"El juego de los tiempos","brief":"You're Tomás, at the corner table with Hernando, drafting the taxi chapter. He is much older, so use usted. Choose each tense on purpose: what always happened, what happened once, and a few moods.","turns":[{"id":"t1","npc":"Hernando: Hoy empezamos con el taxi. ¿Con qué comenzamos, con lo que pasaba siempre o con lo que pasó una vez?","npcEn":"Hernando: Today we start with the taxi. What do we start with, with what always happened or with what happened once?","intent":"Choose what always happened and describe his usual morning, using the imperfect.","accept":["Con lo que pasaba siempre. Todas las mañanas usted salía a las cinco y recogía a los primeros clientes.","Con lo que pasaba siempre: usted tomaba un tinto en la esquina y empezaba a manejar.","Empecemos con lo que pasaba siempre. Cada mañana usted lavaba el carro antes de salir."],"require":[{"type":"anyVerbInTense","tense":"imperfecto","label":"what used to happen takes the imperfect: salía, recogía"}],"focus":"g:tense-modal-uses","next":"t2"},{"id":"t2","npc":"Hernando: Bien. Ahora lo que pasó una sola noche, en plena lluvia.","npcEn":"Hernando: Good. Now what happened on one single night, in the middle of the rain.","intent":"Narrate what happened that night, with the simple past.","accept":["Esa noche el carro se paró y usted tuvo que caminar hasta la casa.","Una noche, en plena lluvia, el carro se paró y nadie quiso ayudarlo.","Esa noche usted llamó a un amigo, pero nadie contestó."],"require":[{"type":"anyVerbInTense","tense":"preterito","label":"one night takes the simple past: se paró, tuvo que"}],"focus":"g:tense-modal-uses","next":"t3"},{"id":"t3","npc":"Hernando: El hecho de que no le dijera nada a Rosa todavía me pesa. ¿Usted qué piensa?","npcEn":"Hernando: The fact that I didn't tell Rosa anything still weighs on me. What do you think?","intent":"Answer starting from el hecho de que + subjunctive.","accept":["El hecho de que no se lo dijera no lo hace menos verdad.","Creo que el hecho de que no hablara no significa que no la quisiera.","El hecho de que se lo guardara no lo hace un mal hombre."],"require":[{"type":"regex","pattern":"\\bel hecho de que\\b","flags":"iu","label":"use el hecho de que"},{"type":"subjunctiveAfter","trigger":"el hecho de que","label":"after el hecho de que, a fact you are weighing, use the subjunctive"}],"focus":"g:mood-choice-fine","next":"t4"},{"id":"t4","npc":"Hernando: Mañana le leo el capítulo a mi hija. Seguro que le parece demasiado triste.","npcEn":"Hernando: Tomorrow I'll read the chapter to my daughter. She's sure to find it too sad.","intent":"Tell him to read it to her and to listen to whatever she says (lo que + subjunctive).","accept":["Léaselo y escuche lo que ella diga.","Léaselo. Y lo que ella opine, anótelo.","Léaselo sin miedo y escuche lo que ella piense."],"require":[{"type":"regex","pattern":"\\blo que (ella )?(diga|opine|piense|quiera|sienta|prefiera)\\b","flags":"iu","label":"whatever she says: lo que ella diga"}],"focus":"g:mood-choice-fine","next":"t5"},{"id":"t5","npc":"Hernando: Tiene razón. Lo leeré con valor, aunque me duela. ¿Otro tinto? Invito yo.","npcEn":"Hernando: You're right. I'll read it bravely, even if it hurts. Another black coffee? It's on me.","intent":"Accept the coffee and thank him for letting you help with the book.","accept":["Con gusto. Y gracias por dejarme ayudarle con su libro.","Sí, gracias. Es un honor ayudarle con el libro.","Claro que sí. Gracias por confiarme su historia."],"require":[],"focus":"g:mood-choice-fine","next":null}],"r":["g:gender-articles","g:indirect-objects","g:le-doubling","g:mood-choice-fine","g:present-ar","g:preterite-ar","g:relatives-donde-lo-que","g:stem-boot","g:tense-modal-uses","g:that-clauses"],"d":552},
{"id":"sc-u52-d","unit":"u52","band":"C1","title":"Ya estamos grabando","brief":"You're Tomás, recording an oral-history interview with Hernando for the memoir. He is much older, so use usted. Ask good questions, choosing the tense that fits what you want to know.","turns":[{"id":"t1","npc":"Hernando: Ya estamos grabando. Pregunte lo que quiera.","npcEn":"Hernando: We are already recording. Ask whatever you like.","intent":"Ask what Bogotá was like when he started driving the taxi (imperfect).","accept":["¿Cómo era Bogotá cuando empezó a manejar el taxi?","¿Cómo era la ciudad cuando usted empezó a manejar?","Cuando empezó a manejar, ¿cómo era Bogotá?"],"require":[{"type":"question"},{"type":"anyVerbInTense","tense":"imperfecto","label":"ask about a past scene with the imperfect: cómo era"}],"focus":"g:tense-modal-uses","next":"t2"},{"id":"t2","npc":"Hernando: Era otra ciudad. Casi todos nos conocíamos en las esquinas.","npcEn":"Hernando: It was another city. Almost all of us knew each other on the street corners.","intent":"Ask who his first passenger was (simple past).","accept":["¿Quién fue su primer cliente?","¿Y quién fue su primer pasajero?","¿Quién fue el primero que subió a su taxi?"],"require":[{"type":"question"},{"type":"anyVerbInTense","tense":"preterito","label":"one fixed moment takes the simple past: quién fue"}],"focus":"g:tense-modal-uses","next":"t3"},{"id":"t3","npc":"Hernando: Un señor mayor que quería ir al aeropuerto, y yo no sabía dónde quedaba.","npcEn":"Hernando: An older gentleman who wanted to go to the airport, and I didn't know where it was.","intent":"Politely say you wanted to ask something more personal (quería preguntarle).","accept":["Quería preguntarle algo más personal, si me lo permite.","Quería hacerle una pregunta más personal, si no le molesta.","Quería preguntarle algo íntimo, si me permite."],"require":[{"type":"regex","pattern":"\\bquería\\b","flags":"iu","label":"soften it with the imperfect: quería preguntarle"}],"focus":"p:imperfecto-cortesia-venia","next":"t4"},{"id":"t4","npc":"Hernando: Pregunte, pregunte. A mi edad ya no hay secretos.","npcEn":"Hernando: Ask, ask. At my age there are no more secrets.","intent":"Ask whether he ever thought about quitting the taxi.","accept":["¿Alguna vez pensó en dejar el taxi?","¿Pensó alguna vez en dejar de manejar?","¿Alguna vez quiso dejar el taxi?"],"require":[{"type":"question"},{"type":"anyVerbInTense","tense":"preterito","label":"a single moment in his life: pensó, quiso"}],"focus":"g:tense-modal-uses","next":"t5"},{"id":"t5","npc":"Hernando: Mil veces. Pero siempre me esperaba una carrera más, y esa carrera cambiaba el día.","npcEn":"Hernando: A thousand times. But there was always one more fare waiting for me, and that fare changed the day.","intent":"Thank him and say this goes straight into the book.","accept":["Gracias, don Hernando. Eso va directo al libro.","Muchas gracias. Eso tiene que quedar en el libro.","Gracias por contármelo. Esto va al libro tal cual."],"require":[],"focus":"g:tense-modal-uses","next":null}],"r":["g:commands-usted","g:gender-articles","g:imperfect-habitual","g:tense-modal-uses","p:imperfecto-cortesia-venia"],"d":551,"spare":true},
{"id":"sc-u52-e","unit":"u52","band":"C1","title":"Llamada desde Valencia","brief":"You're Tomás, on a video call with Inés, a festival producer in Valencia. She talks the way people do in Spain, and you're on friendly terms, so use tú. Answer in your own Colombian way: simple past for what's done, the perfect only for experience and not yet.","turns":[{"id":"t1","npc":"Inés: Hola, Tomás. Esta mañana he leído tu mensaje y me ha encantado la idea.","npcEn":"Inés: Hi, Tomás. This morning I have read your message and I have loved the idea.","intent":"Say you're glad, and that you sent it this morning before your coffee (simple past).","accept":["Qué bueno. Esta mañana lo envié antes del café.","Me da mucho gusto. Lo escribí temprano y lo envié antes de desayunar.","Qué alegría. Lo escribí anoche y lo envié esta mañana."],"require":[{"type":"anyVerbInTense","tense":"preterito","label":"for this morning, the simple past: lo envié"},{"type":"regex","pattern":"^(?!.*(?<![\\p{L}])(he|ha|hemos)(?![\\p{L}]))","flags":"isu","label":"here we say lo envié, not lo he enviado"}],"focus":"g:spain-pasts","next":"t2"},{"id":"t2","npc":"Inés: ¿Has estado en Valencia alguna vez?","npcEn":"Inés: Have you ever been to Valencia?","intent":"Say no, you've never been, but you went to Madrid years ago.","accept":["No, nunca he estado. Pero fui a Madrid hace años.","Nunca he estado en Valencia. Estuve en Madrid hace años.","No, nunca. Fui a Madrid hace años, pero a Valencia no."],"require":[{"type":"anyVerbInTense","tense":"preterito","label":"a trip with a date takes the simple past: fui, estuve"}],"focus":"g:spain-pasts","next":"t3"},{"id":"t3","npc":"Inés: Pues este año hemos tenido más de cien lecturas en el festival. ¿Y a ti qué tal te ha ido el año?","npcEn":"Inés: Well, this year we have had more than a hundred readings at the festival. And how has your year gone?","intent":"Tell her your year went well: you inherited a café and started writing a book (simple past).","accept":["Me fue bien: heredé un café y empecé a escribir un libro.","Fue un año intenso. Heredé el café de mi abuela y empecé a escribir.","Me fue muy bien. Llegué a Bogotá, heredé un café y conocí a Hernando."],"require":[{"type":"anyVerbInTense","tense":"preterito","label":"a year you are telling as a story: heredé, empecé"},{"type":"regex","pattern":"^(?!.*(?<![\\p{L}])(he|ha|hemos)(?![\\p{L}]))","flags":"isu","label":"say me fue bien, not me ha ido bien"}],"focus":"g:spain-pasts","next":"t4"},{"id":"t4","npc":"Inés: Mañana mismo te mando el programa. ¿Y el libro? ¿Ya lo tienes listo?","npcEn":"Inés: I'll send you the programme tomorrow. And the book? Do you have it ready yet?","intent":"Say the book isn't finished yet (todavía no he terminado), but you can send three chapters.","accept":["Todavía no he terminado, pero te puedo mandar tres capítulos.","Todavía no lo he terminado. Te mando tres capítulos esta semana.","Todavía no he terminado el libro, pero ya tengo tres capítulos para ti."],"require":[{"type":"regex","pattern":"\\btodavía no (lo )?he\\b","flags":"iu","label":"not yet takes the perfect: todavía no he terminado"}],"focus":"g:spain-pasts","next":"t5"},{"id":"t5","npc":"Inés: Perfecto. Te escribo la semana que viene. ¡Un abrazo desde Valencia!","npcEn":"Inés: Perfect. I'll write to you next week. A hug from Valencia!","intent":"Send a hug back and thank her for the call.","accept":["Un abrazo para ti también. Gracias por la llamada.","Otro abrazo desde Bogotá. Gracias por llamar.","Un abrazo, Inés. Gracias por todo."],"require":[],"focus":"g:spain-pasts","next":null}],"r":["g:gender-articles","g:perfecto-experience","g:spain-pasts","g:stem-boot"],"d":69,"spare":true},
{"id":"sc-u52-f","unit":"u52","band":"C1","title":"Lo que no pasó","brief":"You're Tomás, playing a game Hernando invented for the memoir: write the chapters of what didn't happen. He is much older, so use usted. Answer his what-ifs with hubiera or hubiese and habría.","turns":[{"id":"t1","npc":"Hernando: Juguemos a lo que no pasó. Si yo hubiese comprado el edificio en 1975, ¿qué habría pasado con el café?","npcEn":"Hernando: Let's play at what didn't happen. If I had bought the building in 1975, what would have happened to the café?","intent":"Say that if he had bought the building, the café would be his.","accept":["Si usted hubiera comprado el edificio, el café sería suyo.","Si usted lo hubiera comprado, el café habría sido suyo.","El café habría sido suyo si usted hubiera comprado el edificio."],"require":[{"type":"regex","pattern":"\\bhubiera\\b","flags":"iu","label":"start the if-clause with hubiera"},{"type":"regex","pattern":"\\b(habría|sería|estaría|tendría)\\b","flags":"iu","label":"finish with the would: habría, sería"}],"focus":"g:se-form-recognition","next":"t2"},{"id":"t2","npc":"Hernando: ¿Y si Rosa hubiese dicho que sí? Mi suerte habría sido otra.","npcEn":"Hernando: And if Rosa had said yes? My luck would have been different.","intent":"Point out the funny consequence for you, using hubiese: you wouldn't have been born.","accept":["Si ella hubiese dicho que sí, yo no habría nacido.","Y yo no estaría aquí, si ella hubiese dicho que sí.","Si mi abuela hubiese aceptado, yo no habría nacido."],"require":[{"type":"regex","pattern":"\\bhubiese\\b","flags":"iu","label":"use hubiese, the other if-form"}],"focus":"g:se-form-recognition","next":"t3"},{"id":"t3","npc":"Hernando: Usted es cruel. Bueno, otra: si hubiera sabido desde el principio lo difícil que era el café, ¿lo habría aceptado?","npcEn":"Hernando: You are cruel. Well, another one: if you had known from the start how hard the café was, would you have accepted it?","intent":"Answer honestly with habría: would you have accepted it or not?","accept":["Sí, lo habría aceptado igual, aunque con más miedo.","Lo habría aceptado, pero habría dormido menos.","No sé. Tal vez me habría quedado en Toronto."],"require":[{"type":"regex","pattern":"\\bhabría\\b","flags":"iu","label":"answer with habría: lo habría aceptado"}],"focus":"g:tense-modal-uses","next":"t4"},{"id":"t4","npc":"Hernando: Escribiré ese capítulo. Se llamará Lo que habría podido ser. ¿Le gusta?","npcEn":"Hernando: I'll write that chapter. It will be called What Could Have Been. Do you like it?","intent":"Tell him you love the title and that what didn't happen counts too.","accept":["Me encanta el título. Lo que no fue también cuenta.","Sí, mucho. Lo que no pasó también es parte de la historia.","Me gusta. Lo que no sucedió también cuenta."],"require":[],"focus":"g:se-form-recognition","next":"t5"},{"id":"t5","npc":"Hernando: Entonces a trabajar. Pero primero, el tinto.","npcEn":"Hernando: Then to work. But first, the black coffee.","intent":"Offer to go get it and ask whether he wants it with sugar.","accept":["Yo voy por él. ¿Lo quiere con azúcar?","Ya se lo traigo. ¿Lo prefiere sin azúcar?","Voy yo. ¿Se lo traigo con azúcar?"],"require":[{"type":"question"}],"focus":"g:tense-modal-uses","next":null}],"r":["g:conditional-perfect","g:gender-articles","g:imperfect-states","g:pluperfect-subj","g:relatives-donde-lo-que","g:se-form-recognition","g:ser-identity","g:si-hypothetical","g:si-past-unreal","g:tense-modal-uses"],"d":551,"spare":true},
{"id":"sc-u52-g","unit":"u52","band":"C1","title":"Una llamada a Medellín","brief":"You're Tomás, on the phone with Vale, who is away in Medellín. You're close friends, so use tú. She is quick and dry. Reassure her, hand her the decisions, and pick your moods on purpose.","turns":[{"id":"t1","npc":"Vale: Quiero ver el patio hoy mismo. ¿Me pasas una foto?","npcEn":"Vale: I want to see the patio today. Can you send me a photo?","intent":"Calm her down and say you'll send the photo right now (present tense).","accept":["Tranquila, te la paso ahora mismo.","Ahora mismo te la paso. Tú tranquila.","Ya te la paso, no te preocupes."],"require":[{"type":"verbForm","inf":"pasar","tense":"presente","person":"yo","label":"say you'll send it: te la paso"}],"focus":"g:tense-modal-uses","next":"t2"},{"id":"t2","npc":"Vale: Gracias. Y si no puedo volver el viernes, ¿qué hago con el pedido de panes?","npcEn":"Vale: Thanks. And if I can't come back on Friday, what do I do with the bread order?","intent":"Tell her to do what she thinks is best (haz lo que + subjunctive).","accept":["Haz lo que te parezca mejor.","Haz lo que prefieras, yo me encargo aquí.","Haz lo que puedas y yo me encargo aquí."],"require":[{"type":"regex","pattern":"\\bhaz lo que\\b","flags":"iu","label":"use: haz lo que + subjunctive"},{"type":"subjunctiveAfter","trigger":"lo que","label":"after haz lo que, use the subjunctive"}],"focus":"g:mood-choice-fine","next":"t3"},{"id":"t3","npc":"Vale: Oye, el hecho de que Altamira lleve una semana callado me preocupa.","npcEn":"Vale: Listen, the fact that Altamira has been quiet for a week worries me.","intent":"Say you agree and that the fact that he's quiet doesn't mean he has forgotten about the café (el hecho de que + subjunctive).","accept":["Yo pienso igual. El hecho de que esté callado no significa que haya cambiado de idea.","Tienes razón. El hecho de que no llame no quiere decir que se olvide del café.","Sí, y el hecho de que esté callado no significa que se haya olvidado de nosotros."],"require":[{"type":"regex","pattern":"\\bel hecho de que\\b","flags":"iu","label":"use el hecho de que"},{"type":"subjunctiveAfter","trigger":"el hecho de que","label":"after el hecho de que, use the subjunctive"}],"focus":"g:mood-choice-fine","next":"t4"},{"id":"t4","npc":"Vale: Mañana te llamo otra vez. ¿Quieres que te traiga algo de Medellín?","npcEn":"Vale: I'll call you again tomorrow. Do you want me to bring you something from Medellín?","intent":"Tell her to bring whatever she likes, as long as it's sweet.","accept":["Tráeme lo que quieras, pero que sea dulce.","Lo que tú elijas estará bien, mientras sea dulce.","Tráeme lo que más te guste, pero algo dulce."],"require":[{"type":"regex","pattern":"\\blo que\\b","flags":"iu","label":"use lo que + subjunctive"}],"focus":"g:mood-choice-fine","next":"t5"},{"id":"t5","npc":"Vale: Trato hecho. Vuelvo pronto. Que no se les queme nada.","npcEn":"Vale: Deal. I'll be back soon. Don't let anything burn.","intent":"Reassure her and say Simón is waiting for her too.","accept":["Tranquila. Aquí te esperamos, y Simón también.","Aquí estaremos. Simón ya pregunta por ti.","Tranquila, el café está en buenas manos. Simón te espera."],"require":[],"focus":"g:tense-modal-uses","next":null}],"r":["g:gender-articles","g:mood-choice-fine","g:present-ar","g:stem-boot","g:subj-wanting","g:tense-modal-uses","g:that-clauses","g:verb-infinitive"],"d":552,"spare":true},
{"id":"sc-u52-h","unit":"u52","band":"C1","title":"En el aire","brief":"You're Tomás, a guest on Camila's radio show to talk about the memoir. Radio is informal, so use tú with Camila. Use the phrases from the week: de la noche a la mañana, toda una odisea, nunca en mi vida, no te imaginas lo que.","turns":[{"id":"t1","npc":"Camila: Bienvenido al programa, Tomás. ¿Cómo empezó este proyecto?","npcEn":"Camila: Welcome to the show, Tomás. How did this project start?","intent":"Say it all began overnight (de la noche a la mañana), when Hernando asked for your help.","accept":["De la noche a la mañana, Hernando me pidió que lo ayudara con su libro.","Fue de la noche a la mañana: un día Hernando llegó con su historia.","Todo empezó de la noche a la mañana, cuando Hernando me habló de su libro."],"require":[{"type":"regex","pattern":"de la noche a la mañana","flags":"iu","label":"use: de la noche a la mañana"}],"focus":"c:de-la-noche-a-la-manana","next":"t2"},{"id":"t2","npc":"Camila: ¿Y cómo es trabajar con alguien que lleva cincuenta años manejando un taxi?","npcEn":"Camila: And what is it like working with someone who has been driving a taxi for fifty years?","intent":"Say it's quite an ordeal, but you love it (toda una odisea).","accept":["Es toda una odisea, pero me encanta.","Toda una odisea, pero nunca me canso.","A veces es toda una odisea, pero cada historia lleva a otra."],"require":[{"type":"regex","pattern":"toda una odisea","flags":"iu","label":"use: toda una odisea"}],"focus":"c:toda-una-odisea","next":"t3"},{"id":"t3","npc":"Camila: Dame un secreto del libro.","npcEn":"Camila: Give me a secret from the book.","intent":"Hook the audience: tell Camila she can't imagine how much (no te imaginas lo mucho que).","accept":["No te imaginas lo mucho que me reí anoche con sus historias.","Uf, no te imaginas lo mucho que sufrió con su primer cliente.","No te imaginas lo mucho que cambió la ciudad desde que él manejaba."],"require":[{"type":"regex","pattern":"\\bno te imaginas lo (mucho )?que\\b","flags":"iu","label":"use: no te imaginas lo mucho que"}],"focus":"p:no-te-imaginas-lo-que","next":"t4"},{"id":"t4","npc":"Camila: ¿Crees que la gente querrá leer a un taxista?","npcEn":"Camila: Do you think people will want to read a taxi driver?","intent":"Say you've never in your life read anything like it (nunca en mi vida).","accept":["Nunca en mi vida he leído algo así.","Sí. Nunca en mi vida me reí tanto con un libro.","Claro. Nunca en mi vida había leído una historia tan viva."],"require":[{"type":"regex","pattern":"nunca en mi vida","flags":"iu","label":"use: nunca en mi vida"}],"focus":"c:nunca-en-mi-vida","next":"t5"},{"id":"t5","npc":"Camila: Gracias por venir. ¿Algo más para los oyentes?","npcEn":"Camila: Thanks for coming. Anything else for the listeners?","intent":"Invite listeners to come to the café and tell their own stories (que + subjunctive).","accept":["Que vengan al café y que nos cuenten sus propias historias.","Que vengan al café, que aquí hay tinto y mucho que contar.","Que pasen por el café y que traigan sus historias."],"require":[{"type":"regex","pattern":"\\bque (vengan|pasen|visiten|cuenten)\\b","flags":"iu","label":"invite them with que + subjunctive: que vengan"}],"focus":"g:mood-choice-fine","next":null}],"r":["c:de-la-noche-a-la-manana","c:nunca-en-mi-vida","c:toda-una-odisea","g:gender-articles","g:mood-choice-fine","p:no-te-imaginas-lo-que"],"d":635,"spare":true},
{"id":"sc-u52-i","unit":"u52","band":"C1","title":"Perpetua","brief":"You're Tomás, talking with Gloria, who isn't happy about being in Hernando's memoir. She's older than you and you've always used usted with her. Listen, reassure her and settle on a solution.","turns":[{"id":"t1","npc":"Gloria: Tomás, me enteré de que Hernando habla de mí en su libro. Quería hablar con usted antes.","npcEn":"Gloria: Tomás, I found out that Hernando writes about me in his book. I wanted to talk to you first.","intent":"Invite her to speak and ask what worries her (use usted).","accept":["Claro, dígame. ¿Qué le preocupa?","Con gusto. ¿Qué es lo que no le gusta?","Cuénteme, ¿qué le molesta del libro?"],"require":[{"type":"question"},{"type":"regex","pattern":"^(?!.*(?<![\\p{L}])(tú|tu|tienes|quieres|te)(?![\\p{L}]))","flags":"isu","label":"you are on usted terms with her"}],"focus":"g:tense-modal-uses","next":"t2"},{"id":"t2","npc":"Gloria: Dice que en 1990 casi me choca un taxi. Eso fue por un pelo, pero no quiero que lo cuente con pelos y señales.","npcEn":"Gloria: He says that in 1990 a taxi almost hit me. That was a close shave, but I don't want him to tell it in every detail.","intent":"Say you understand: it was by a hair, and there's no need to tell it with every detail.","accept":["Entiendo. Fue por un pelo, y no es necesario contarlo con pelos y señales.","Lo entiendo. Fue por un pelo, pero no necesita todos los detalles.","Claro. Fue por un pelo, y no hay que contarlo con pelos y señales."],"require":[{"type":"regex","pattern":"por un pelo|con pelos y señales","flags":"iu","label":"use: por un pelo or con pelos y señales"}],"focus":"c:por-un-pelo","next":"t3"},{"id":"t3","npc":"Gloria: Y además lo cuenta como si yo hubiera gritado. Yo nunca grito.","npcEn":"Gloria: And besides, he tells it as if I had shouted. I never shout.","intent":"Offer to write whatever she says it was like (lo que + subjunctive).","accept":["Entonces escribiremos lo que usted diga.","Dígame cómo fue y pondremos lo que usted prefiera.","Le prometo que quedará lo que usted quiera."],"require":[{"type":"regex","pattern":"\\blo que (usted )?(quiera|diga|prefiera|pida|decida)\\b","flags":"iu","label":"whatever she says: lo que usted diga"}],"focus":"g:mood-choice-fine","next":"t4"},{"id":"t4","npc":"Gloria: Está bien. Pero que Hernando no use mi nombre.","npcEn":"Gloria: All right. But Hernando mustn't use my name.","intent":"Agree and ask what name she wants you to use for her in the book (¿... quiere que ...?).","accept":["Hecho. ¿Qué nombre quiere que le pongamos?","De acuerdo. ¿Cómo quiere que la llamemos en el libro?","Cuente con eso. ¿Con qué nombre quiere que aparezca?"],"require":[{"type":"question"},{"type":"regex","pattern":"\\bquiere que\\b","flags":"iu","label":"ask with: quiere que + subjunctive"}],"focus":"g:mood-choice-fine","next":"t5"},{"id":"t5","npc":"Gloria: Pónganme Perpetua. Siempre quise llamarme así.","npcEn":"Gloria: Call me Perpetua. I always wanted to be called that.","intent":"Accept the name and thank her for her patience.","accept":["Será Perpetua, entonces. Gracias por su paciencia.","Gracias por entender. En el libro será Perpetua.","Entonces la llamaremos Perpetua. Se lo agradezco."],"require":[],"focus":"g:tense-modal-uses","next":null}],"r":["c:por-un-pelo","g:direct-objects","g:mood-choice-fine","g:present-ar","g:reflexive-routine","g:stem-boot","g:subj-wanting","g:tense-modal-uses","g:that-clauses","g:verb-infinitive"],"d":621,"spare":true},
{"id":"sc-u53-a","unit":"u53","band":"C1","title":"Lo que dicen en la barra","brief":"You're Tomás, behind the counter. Don Hernando is older than you, so use usted. He has heard rumours about the café, and you want to answer them without repeating them as facts: say what you understand, what you don't claim, and what you'd swear to.","turns":[{"id":"t1","npc":"Hernando: Buenos días, Tomás. Dicen por ahí que el café cierra en diciembre.","npcEn":"Hernando: Good morning, Tomás. They say around here that the café closes in December.","intent":"Say what you understand: Altamira only made an offer (use: Tengo entendido que).","accept":["Tengo entendido que Altamira solo hizo una oferta.","Buenos días, don Hernando. Tengo entendido que solo hubo una oferta.","Tengo entendido que nadie ha firmado nada."],"require":[{"type":"regex","pattern":"\\btengo entendido que\\b","flags":"iu","label":"use: tengo entendido que"}],"focus":"p:tengo-entendido-que","next":"t2"},{"id":"t2","npc":"Hernando: También dicen que usted ya compró el pasaje a Toronto.","npcEn":"Hernando: They also say you've already bought your ticket to Toronto.","intent":"Say you're not claiming people are lying, but you aren't leaving (use: No digo que + subjunctive, pero).","accept":["No digo que la gente mienta, pero yo no me voy.","No digo que sea mentira, pero no he comprado ningún pasaje.","No digo que se lo inventen, pero yo me quedo aquí."],"require":[{"type":"subjunctiveAfter","trigger":"no digo que","label":"after no digo que, use the subjunctive"}],"focus":"p:no-digo-que-pero","next":"t3"},{"id":"t3","npc":"Hernando: Hay quien jura que el concejal tiene al juez en el bolsillo.","npcEn":"Hernando: Some people swear the councilman has the judge in his pocket.","intent":"Politely say you have no wish to offend him, but nobody has proved it (use: Sin ánimo de + infinitive).","accept":["Sin ánimo de ofenderlo, nadie lo ha probado.","Sin ánimo de discutir, hasta ahora no hay ninguna prueba.","Don Hernando, sin ánimo de molestarlo, eso nadie lo ha demostrado."],"require":[{"type":"regex","pattern":"\\bsin ánimo de\\b","flags":"iu","label":"use: sin ánimo de"},{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"focus":"p:sin-animo-de","next":"t4"},{"id":"t4","npc":"Hernando: Yo mismo vi al concejal en la plaza el martes, mirando nuestro local.","npcEn":"Hernando: I myself saw the councilman in the square on Tuesday, looking at our building.","intent":"Say you would swear he came into the café on Tuesday too (use: Juraría que + past).","accept":["Juraría que el martes también entró al café.","Juraría que ese mismo martes estuvo aquí dentro.","Yo juraría que lo vi pidiendo un tinto el martes."],"require":[{"type":"regex","pattern":"\\bjuraría que\\b","flags":"iu","label":"use: juraría que"}],"focus":"p:juraria-que","next":"t5"},{"id":"t5","npc":"Hernando: Entonces, ¿qué piensa usted que va a pasar con el café?","npcEn":"Hernando: So, what do you think is going to happen to the café?","intent":"Say you have no doubt the neighbourhood will support you (use: No me cabe duda de que).","accept":["No me cabe duda de que el barrio nos va a apoyar.","No me cabe ninguna duda de que el barrio va a estar con nosotros.","Para serle sincero, no me cabe duda de que seguimos abiertos."],"require":[{"type":"regex","pattern":"\\bno me cabe (ninguna )?duda de que\\b","flags":"iu","label":"use: no me cabe duda de que"}],"focus":"p:no-me-cabe-duda","next":"t6"},{"id":"t6","npc":"Hernando: Así me gusta. Y ahora dígame, ¿me sirve un tinto?","npcEn":"Hernando: That's what I like to hear. Now tell me, will you pour me a black coffee?","intent":"Offer him the coffee on the house, politely.","accept":["Claro que sí, don Hernando. Este tinto va por la casa.","Con mucho gusto. ¿Se lo sirvo con azúcar?","Ya se lo sirvo, don Hernando. Hoy invita la casa."],"require":[{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"next":null}],"r":["g:gender-articles","g:stem-boot","g:stem-e-i","g:that-clauses","p:juraria-que","p:no-digo-que-pero","p:no-me-cabe-duda","p:sin-animo-de","p:tengo-entendido-que"],"d":522},
{"id":"sc-u53-b","unit":"u53","band":"C1","title":"La nota de Mariana","brief":"You're Tomás, on the phone with Mariana. She is a friend and a journalist closing her story on Altamira, so use tú. She needs what is known, what is only claimed, and what is only rumour, and you must keep the three apart.","turns":[{"id":"t1","npc":"Mariana: Estoy cerrando mi nota sobre Altamira. ¿Qué se sabe, hasta hoy, del concejal?","npcEn":"Mariana: I'm finishing my piece on Altamira. What is known so far about the councilman?","intent":"Say that so far nothing has been proved (use: Hasta la fecha or hasta el momento).","accept":["Hasta la fecha no hay ninguna prueba.","Hasta el momento no se ha probado nada.","Mira, hasta la fecha solo hay rumores."],"require":[{"type":"regex","pattern":"\\bhasta (la fecha|el momento)\\b","flags":"iu","label":"use: hasta la fecha"}],"focus":"p:hasta-la-fecha","next":"t2"},{"id":"t2","npc":"Mariana: Altamira dice que compró el edificio de al lado de forma legal.","npcEn":"Mariana: Altamira says it bought the building next door legally.","intent":"Say that the company maintains it was legal, but you can't confirm it (use: sostiene que).","accept":["Sostiene que fue legal, pero yo no lo puedo confirmar.","La empresa sostiene que todo fue legal, pero no tengo cómo confirmarlo.","Sostiene que lo compró legalmente, pero eso no me consta."],"require":[{"type":"regex","pattern":"\\bsostiene que\\b","flags":"iu","label":"use: sostiene que"}],"focus":"p:sostener-que","next":"t3"},{"id":"t3","npc":"Mariana: ¿Y el rumor de que el juez recibió dinero?","npcEn":"Mariana: And the rumour that the judge received money?","intent":"Say you're not so sure it's true (use: No tengo tan claro que + subjunctive).","accept":["No tengo tan claro que sea verdad.","Sinceramente, no tengo tan claro que el juez haya recibido nada.","No tengo tan claro que eso sea cierto."],"require":[{"type":"subjunctiveAfter","trigger":"no tengo tan claro que","label":"after no tengo tan claro que, use the subjunctive"}],"focus":"p:no-tengo-tan-claro","next":"t4"},{"id":"t4","npc":"Mariana: Me dijeron que el concejal salía hoy para Miami, pero no estoy segura.","npcEn":"Mariana: They told me the councilman was leaving for Miami today, but I'm not sure.","intent":"Check what you heard: was he leaving today? (use the imperfect: salía).","accept":["¿El concejal salía hoy para Miami, entonces?","Entonces el concejal salía hoy para Miami, ¿no?","¿Salía hoy? ¿Quién te lo dijo?"],"require":[{"type":"anyVerbInTense","tense":"imperfecto","label":"use the imperfect: salía"},{"type":"question","label":"ask it as a question"}],"focus":"p:imperfecto-citativo","next":"t5"},{"id":"t5","npc":"Mariana: Cada uno cuenta una versión distinta. ¿Tú qué crees?","npcEn":"Mariana: Everyone tells a different version. What do you think?","intent":"Give your opinion: if you ask me, everyone says what suits them (use: Para mí que and cada quien).","accept":["Para mí que cada quien cuenta lo que le conviene.","Para mí que cada quien tiene su versión, y ninguna es la verdad completa.","Pues, para mí que cada quien dice lo que le conviene."],"require":[{"type":"regex","pattern":"\\bpara mí que\\b","flags":"iu","label":"use: para mí que"},{"type":"regex","pattern":"\\bcada quien\\b","flags":"iu","label":"use: cada quien"}],"focus":"p:para-mi-que","next":"t6"},{"id":"t6","npc":"Mariana: Gracias, Tomás. Te llamo cuando salga la nota.","npcEn":"Mariana: Thanks, Tomás. I'll call you when the piece comes out.","intent":"Thank her and invite her to the café for a tinto.","accept":["Gracias a ti. Cuando vengas, el tinto va por la casa.","Gracias, Mariana. Pásate por el café y te invito un tinto.","Gracias a ti. Ven cuando quieras, que hay tinto."],"require":[{"type":"containsAny","words":["tinto","café"],"label":"mention the café or a tinto"}],"next":null}],"r":["g:adjective-agreement","g:estar-location-states","g:gender-articles","g:present-er-ir","g:questions","g:that-clauses","p:hasta-la-fecha","p:imperfecto-citativo","p:no-tengo-tan-claro","p:para-mi-que","p:sostener-que"],"d":520},
{"id":"sc-u53-c","unit":"u53","band":"C1","title":"El pasaje que no existe","brief":"You're Tomás, at the pastry counter with Vale. She is quick and dry, and a friend, so use tú. A rumour says you're going back to Canada. Deny it, trace where it came from, and answer without making a fight of it.","turns":[{"id":"t1","npc":"Vale: A ver, Tomás. Me soltó la señora de la panadería que te vas a Canadá en diciembre.","npcEn":"Vale: Right, Tomás. The lady from the bakery blurted out to me that you're going to Canada in December.","intent":"Say it isn't true and you're not going anywhere.","accept":["Eso no es verdad. No me voy a ninguna parte.","No, nada de eso. Yo no me voy.","No es cierto, no me voy a Canadá."],"require":[{"type":"negation","label":"say no: it isn't true"}],"focus":"g:hedging-distance","next":"t2"},{"id":"t2","npc":"Vale: ¿Y de dónde sacó eso?","npcEn":"Vale: And where did she get that from?","intent":"Explain that your mother blurted out she wanted to see you at Christmas (use a verb like soltó or aclaró + que).","accept":["Mi mamá me soltó que quería verme en Navidad.","Mi mamá me aclaró que quería verme en diciembre, y alguien lo exageró.","Mi mamá me soltó que me extrañaba mucho."],"require":[{"type":"regex","pattern":"\\b(soltó|aclaró|reprochó|recalcó) que\\b","flags":"iu","label":"use: soltó / aclaró / reprochó + que"}],"focus":"p:verbo-que-interpreta","next":"t3"},{"id":"t3","npc":"Vale: Ya. Seguro que el chismoso de mi primo también lo repitió.","npcEn":"Vale: Right. I bet that gossip of a cousin of mine repeated it too.","intent":"Say that cousin of hers always exaggerates (use: el + adjective + de + person, like el bobo de tu primo).","accept":["El chismoso de tu primo siempre cuenta de más.","El pobre de tu primo no sabe quedarse callado.","Claro, el cuentero de tu primo exagera todo."],"require":[{"type":"regex","pattern":"\\b(el|la)\\s+\\p{L}+\\s+de\\s+(tu|mi|su)\\b","flags":"iu","label":"use: el + adjective + de + tu primo"}],"focus":"p:el-x-de-y","next":"t4"},{"id":"t4","npc":"Vale: Cambiando de tema, la máquina de espresso suena rara. ¿Se dañó?","npcEn":"Vale: Changing the subject, the espresso machine sounds odd. Did it break?","intent":"Say the technician fixed it yesterday (use: reparó or arregló).","accept":["Ayer la reparó el técnico, pero suena raro.","El técnico la arregló ayer.","Ayer vino el técnico y la reparó."],"require":[{"type":"regex","pattern":"\\b(reparó|repararon|arregló|arreglaron)(?!\\p{L})","flags":"iu","label":"say it was fixed: reparó / arregló"},{"type":"anyVerbInTense","tense":"preterito","label":"use the past: yesterday it was fixed"}],"focus":"p:rectificar-reparar","next":"t5"},{"id":"t5","npc":"Vale: Qué alivio. ¿Te quedas a probar el pan nuevo?","npcEn":"Vale: What a relief. Will you stay and try the new bread?","intent":"Say yes, and add, by the way, that you're staying here (use: dicho sea de paso).","accept":["Claro. Y dicho sea de paso, aquí me quedo.","Sí, y dicho sea de paso, no pienso irme a ninguna parte.","Dicho sea de paso, me quedo. Y el pan huele delicioso."],"require":[{"type":"regex","pattern":"\\bdicho sea de paso\\b","flags":"iu","label":"use: dicho sea de paso"}],"focus":"c:dicho-sea-de-paso","next":null}],"r":["c:dicho-sea-de-paso","g:gender-articles","g:hedging-distance","g:preterite-ar","p:el-x-de-y","p:rectificar-reparar","p:verbo-que-interpreta"],"d":520,"spare":true},
{"id":"sc-u53-d","unit":"u53","band":"C1","title":"Titular de portada","brief":"You're Tomás, reading the morning paper with Don Hernando. He is older than you, so use usted. A council official has vanished, and every theory sounds like a fact. React to the news without repeating more than the paper says.","turns":[{"id":"t1","npc":"Hernando: Mire esto, Tomás: el funcionario del concejo se encuentra en paradero desconocido.","npcEn":"Hernando: Look at this, Tomás: the council official's whereabouts are unknown.","intent":"Say it's unprecedented in the barrio (use: sin precedentes).","accept":["Es algo sin precedentes en el barrio.","Don Hernando, es un escándalo sin precedentes.","Un caso sin precedentes en la Candelaria."],"require":[{"type":"regex","pattern":"\\bsin precedentes\\b","flags":"iu","label":"use: sin precedentes"}],"focus":"c:sin-precedentes","next":"t2"},{"id":"t2","npc":"Hernando: Así es. Dicen que lo vieron en el aeropuerto con dos maletas.","npcEn":"Hernando: That's right. They say he was seen at the airport with two suitcases.","intent":"Say that if so, he wasn't going on a holiday (use: De ser así).","accept":["De ser así, no se fue de vacaciones.","De ser así, no se iba de paseo.","De ser así, don Hernando, se iba para no volver."],"require":[{"type":"regex","pattern":"\\bde ser así(?!\\p{L})","flags":"iu","label":"use: de ser así"}],"focus":"c:de-ser-asi","next":"t3"},{"id":"t3","npc":"Hernando: No sé si creerlo. ¿Usted qué haría?","npcEn":"Hernando: I don't know whether to believe it. What would you do?","intent":"Say, with no offence, that you'd wait for the official version (use: No es por nada, pero).","accept":["No es por nada, pero esperaría la versión oficial.","No es por nada, pero yo esperaría a que lo confirmen.","No es por nada, pero por ahora no repetiría nada."],"require":[{"type":"regex","pattern":"\\bno es por nada,? pero\\b","flags":"iu","label":"use: no es por nada, pero"},{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"focus":"c:no-es-por-nada-pero","next":"t4"},{"id":"t4","npc":"Hernando: Tiene razón. El abogado de Altamira, ¿cómo se llamaba? Se me fue el nombre.","npcEn":"Hernando: You're right. Altamira's lawyer, what was he called? The name has slipped my mind.","intent":"Say you have it on the tip of your tongue too, and it starts with an R (use: en la punta de la lengua).","accept":["Yo también lo tengo en la punta de la lengua. Empieza con R.","Lo tengo en la punta de la lengua, don Hernando. Creo que empieza con R.","Ahora mismo lo tengo en la punta de la lengua, empieza con R."],"require":[{"type":"regex","pattern":"\\ben la punta de la lengua\\b","flags":"iu","label":"use: en la punta de la lengua"},{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"focus":"c:punta-de-la-lengua","next":"t5"},{"id":"t5","npc":"Hernando: Cuando me acuerde, se lo digo. Mientras tanto, guarde ese periódico, que Simón se lo come.","npcEn":"Hernando: When I remember, I'll tell you. Meanwhile, put that newspaper away, or Simón will eat it.","intent":"Say you'll put it away, and that in any case you've already read it (use: de todos modos or en cualquier caso).","accept":["Ya lo guardo, don Hernando. De todos modos, ya lo leí.","Lo guardo. En cualquier caso, ya lo leí todo.","Tranquilo, don Hernando, lo guardo. De todos modos ya me lo sé de memoria."],"require":[{"type":"regex","pattern":"\\b(en cualquier caso|en todo caso|de todos modos)\\b","flags":"iu","label":"use: de todos modos / en cualquier caso"},{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"next":null,"focus":"p:en-cualquier-caso"}],"r":["c:de-ser-asi","c:no-es-por-nada-pero","c:punta-de-la-lengua","c:sin-precedentes","g:direct-objects","g:gender-articles","g:questions","g:reflexive-routine","g:stem-boot","g:yo-irregular","p:en-cualquier-caso"],"d":619,"spare":true},
{"id":"sc-u53-e","unit":"u53","band":"C1","title":"Ventanilla de transparencia","brief":"You're Tomás, at the transparency office, asking about a permit. The official is a stranger and formal, so use usted. You only know the permit from hearsay, so say it as hearsay, check what she tells you, and correct yourself cleanly.","turns":[{"id":"t1","npc":"Funcionaria: Pase, pase. ¿Qué se le ofrece?","npcEn":"Official: Come in, come in. What can I do for you?","intent":"Say you're here about the permit for the building next door, and that apparently it was approved without public notice (use: al parecer or supuestamente).","accept":["Vengo por el permiso del edificio vecino. Al parecer, se aprobó sin aviso público.","Buenas tardes. Supuestamente el permiso del edificio de al lado salió sin aviso al público.","Vengo por un permiso. Al parecer, nadie avisó al barrio."],"require":[{"type":"regex","pattern":"\\b(al parecer|supuestamente)\\b","flags":"iu","label":"hedge it: al parecer / supuestamente"},{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"focus":"g:hedging-distance","next":"t2"},{"id":"t2","npc":"Funcionaria: Ese expediente es de una entidad estatal. No está en nuestra oficina.","npcEn":"Official: That file belongs to a state entity. It isn't in our office.","intent":"Check you understood: so (o sea que) she can't give you the file.","accept":["O sea que no puede darme el expediente.","¿O sea que tengo que ir a otra oficina?","O sea que el expediente no está aquí."],"require":[{"type":"regex","pattern":"\\bo sea que\\b","flags":"iu","label":"check with: o sea que"},{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"focus":"p:o-sea-que","next":"t3"},{"id":"t3","npc":"Funcionaria: Correcto. Y las solicitudes de acceso a la información tardan.","npcEn":"Official: Correct. And requests for access to information take a while.","intent":"Say that supposedly the law gives them fifteen days (use: supuestamente or al parecer).","accept":["Supuestamente la ley les da quince días.","Al parecer, la ley da quince días para responder.","Supuestamente tienen quince días, ¿verdad?"],"require":[{"type":"regex","pattern":"\\b(supuestamente|al parecer)\\b","flags":"iu","label":"hedge it: supuestamente / al parecer"}],"focus":"g:hedging-distance","next":"t4"},{"id":"t4","npc":"Funcionaria: Quince días hábiles, es decir, tres semanas.","npcEn":"Official: Fifteen working days, that is, three weeks.","intent":"Say when you'll come back, then correct yourself: next week, or rather in three weeks (use: mejor dicho).","accept":["Vuelvo la próxima semana; mejor dicho, en tres semanas.","Regreso el lunes. Mejor dicho, dentro de tres semanas.","Vuelvo el lunes. Bueno, mejor dicho, en tres semanas."],"require":[{"type":"regex","pattern":"\\bmejor dicho\\b","flags":"iu","label":"correct yourself: mejor dicho"}],"focus":"g:reformulation","next":"t5"},{"id":"t5","npc":"Funcionaria: Déjeme su nombre y su celular, y le avisamos cuando haya respuesta.","npcEn":"Official: Leave me your name and your phone number, and we'll let you know when there is an answer.","intent":"Say that in any case you'll come back to check, and thank her (use: en cualquier caso).","accept":["En cualquier caso, volveré a preguntar. Muchas gracias.","Gracias. En cualquier caso, pasaré la próxima semana.","En cualquier caso, yo vuelvo a revisar. Muchas gracias por su ayuda."],"require":[{"type":"regex","pattern":"\\b(en cualquier caso|en todo caso|de todos modos)\\b","flags":"iu","label":"use: en cualquier caso"}],"focus":"p:en-cualquier-caso","next":null}],"r":["g:hedging-distance","g:present-ar","g:reformulation","g:ser-identity","p:en-cualquier-caso","p:o-sea-que"],"d":520,"spare":true},
{"id":"sc-u53-f","unit":"u53","band":"C1","title":"Después del aeropuerto","brief":"You're Tomás, with Doña Beatriz, who runs the shop next door and has just heard the news from Miami. She is older than you, so use usted. Say what you know, what you only felt, and what you refuse to take for granted.","turns":[{"id":"t1","npc":"Beatriz: ¿Ya se enteró, Tomás? Detuvieron al funcionario en el aeropuerto de Miami.","npcEn":"Beatriz: Have you heard yet, Tomás? They arrested the official at the Miami airport.","intent":"Say you're already up to date, you read it this morning (use: estoy al tanto).","accept":["Sí, ya estoy al tanto. Lo leí esta mañana.","Sí, doña Beatriz, estoy al tanto. Lo vi en el periódico.","Ya estoy al tanto, me lo contó Mariana."],"require":[{"type":"regex","pattern":"\\bal (tanto|corriente|día)\\b","flags":"iu","label":"say you're up to date: estoy al tanto"},{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"focus":"p:ponerse-al-tanto","next":"t2"},{"id":"t2","npc":"Beatriz: Yo no lo habría imaginado. En apariencia era un hombre muy serio.","npcEn":"Beatriz: I'd never have imagined it. On the surface he was a very serious man.","intent":"Say you had the feeling something was off (use: Tenía la sensación de que).","accept":["Yo tenía la sensación de que algo no andaba bien.","Tenía la sensación de que escondía algo.","Pues yo tenía la sensación de que algo raro pasaba."],"require":[{"type":"regex","pattern":"\\bla sensación de que\\b","flags":"iu","label":"use: tenía la sensación de que"}],"focus":"p:tener-la-sensacion","next":"t3"},{"id":"t3","npc":"Beatriz: Y el juez, ¿qué pasa con el juez?","npcEn":"Beatriz: And the judge, what about the judge?","intent":"Say there is a chance more will come to light (use: Cabe la posibilidad de que + subjunctive).","accept":["Cabe la posibilidad de que salgan más cosas a la luz.","Cabe la posibilidad de que todo salga a la luz.","Cabe la posibilidad de que haya más detenidos."],"require":[{"type":"subjunctiveAfter","trigger":"cabe la posibilidad de que","label":"after cabe la posibilidad de que, use the subjunctive"}],"focus":"p:cabe-la-posibilidad","next":"t4"},{"id":"t4","npc":"Beatriz: Dicen que medio barrio hacía la vista gorda.","npcEn":"Beatriz: They say half the barrio turned a blind eye.","intent":"Warn her not to take it for granted that everyone knew (use: dar por sentado).","accept":["No hay que dar por sentado que todos lo sabían.","No demos por sentado que todos lo sabían.","No hay que dar por sentado que la gente miraba para otro lado."],"require":[{"type":"regex","pattern":"\\bpor sentado\\b","flags":"iu","label":"use: dar por sentado"}],"focus":"p:dar-por-sentado","next":"t5"},{"id":"t5","npc":"Beatriz: Tiene razón. Mejor no sembrar dudas sin pruebas. Bueno, lo dejo, que tengo la tienda sola.","npcEn":"Beatriz: You're right. Better not to sow doubts without proof. Well, I'll leave you, I've left the shop on its own.","intent":"Say goodbye politely and ask her to let you know if she hears anything more (formal).","accept":["Hasta luego, doña Beatriz. Si se entera de algo, me mantiene al tanto, por favor.","Que le vaya bien. Si sabe algo más, me avisa, por favor.","Con gusto, doña Beatriz. Cualquier cosa, me cuenta."],"require":[{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"next":null}],"r":["g:adjective-agreement","g:direct-objects","g:gender-articles","g:present-ar","g:that-clauses","p:cabe-la-posibilidad","p:dar-por-sentado","p:ponerse-al-tanto","p:tener-la-sensacion"],"d":532,"spare":true},
{"id":"sc-u54-a","unit":"u54","band":"C1","title":"Música hasta las tres","brief":"You're Tomás, closing up the café with Vale, who is your age and quick and dry, so use tú. The hotel next door has a rooftop bar, and last night it was loud. Be sarcastic about it, admit what you don't know, and say how wrecked you are.","turns":[{"id":"t1","npc":"Vale: Anoche la música de la azotea no paró hasta las tres.","npcEn":"Vale: Last night the music on the rooftop didn't stop until three.","intent":"React with ironic praise: how thoughtful of them to play music so late (use: ¡Qué detalle...!).","accept":["¡Qué detalle tocar música hasta las tres!","¡Qué detalle! Así nadie se duerme temprano en el barrio.","¡Qué detalle de los vecinos, ponernos música gratis toda la noche!"],"require":[{"type":"regex","pattern":"\\bqué detalle\\b","flags":"iu","label":"use: ¡Qué detalle...!"}],"focus":"p:ironic-praise","next":"t2"},{"id":"t2","npc":"Vale: ¿Y sabes cuándo van a abrir el bar de verdad?","npcEn":"Vale: And do you know when they're going to open the bar for real?","intent":"Say you haven't the faintest idea (use: la menor idea).","accept":["No tengo la menor idea.","Ni idea, Vale. No tengo la menor idea de cuándo abren.","No tengo la menor idea, pero seguro que es de noche."],"require":[{"type":"regex","pattern":"\\bla menor idea\\b","flags":"iu","label":"use: la menor idea"}],"focus":"p:la-menor-idea","next":"t3"},{"id":"t3","npc":"Vale: Dicen que los huéspedes van a bajar a desayunar aquí.","npcEn":"Vale: They say the hotel guests are going to come down to have breakfast here.","intent":"Answer with irony: yes, as if they came all the time (use: Sí, como...).","accept":["Sí, como vienen tanto.","Sí, claro, como siempre bajan a vernos.","Sí, como todos los días nos visita alguien del hotel."],"require":[{"type":"regex","pattern":"\\bcomo\\b","flags":"iu","label":"start the sarcasm with: como..."}],"focus":"p:como-viene-tanto","next":"t4"},{"id":"t4","npc":"Vale: Hoy subí a la azotea a mirar y ni siquiera me saludaron.","npcEn":"Vale: Today I went up to the rooftop to look and they didn't even say hello to me.","intent":"Say there's no way you'd go up there (use: ni...).","accept":["Ni hablar, Vale. A esa azotea no subo.","Ni pensarlo, yo no subo a esa azotea.","Yo ni siquiera subo, Vale."],"require":[{"type":"regex","pattern":"\\bni\\b","flags":"iu","label":"use: ni"}],"focus":"p:ni-emphatic","next":"t5"},{"id":"t5","npc":"Vale: Entonces, ¿el hotel te molesta o no?","npcEn":"Vale: So, does the hotel bother you or not?","intent":"Say it bothers you, then correct yourself: it worries you (use: mejor dicho, o sea or es decir).","accept":["Me molesta; mejor dicho, me preocupa.","Me molesta, o sea, me preocupa un poco.","Me molesta, es decir, me quita el sueño."],"require":[{"type":"containsAny","words":["mejor dicho","o sea","es decir"],"label":"correct yourself: mejor dicho, o sea or es decir"}],"focus":"g:reformulation","next":"t6"},{"id":"t6","npc":"Vale: Bueno, ya cierro. Mañana madrugamos.","npcEn":"Vale: Well, I'm closing up. Tomorrow we get up early.","intent":"Tell her she has no idea how tired you are after last night (use: No sabes el... que...).","accept":["No sabes el sueño que tengo, Vale.","Hasta mañana. No sabes el cansancio que tengo.","Menos mal. No sabes el sueño que tengo después de anoche."],"require":[{"type":"regex","pattern":"\\bno sabes (el|la|los|las) [a-záéíóúñ]+ que\\b","flags":"iu","label":"use: No sabes el... que..."}],"focus":"p:el-frio-que-hace","next":null}],"r":["g:gender-articles","g:ir-a-plans","g:present-ar","g:preterite-ar","g:reformulation","p:como-viene-tanto","p:el-frio-que-hace","p:ironic-praise","p:la-menor-idea","p:ni-emphatic"],"d":null},
{"id":"sc-u54-b","unit":"u54","band":"C1","title":"La pizarra de Hernando","brief":"You're Tomás, in the café before opening. Don Hernando is much older than you, so use usted. He has started writing jokes on the chalkboard aimed at the hotel guests. React with surprise, tease him warmly and stand up for the jokes.","turns":[{"id":"t1","npc":"Hernando: Buenos días, Tomás. Anoche escribí mi primer chiste, pero el viento dejó la pizarra hecha un desastre.","npcEn":"Hernando: Good morning, Tomás. Last night I wrote my first joke, but the wind left the chalkboard a total mess.","intent":"Agree that the chalkboard is a mess (use: hecha un desastre).","accept":["Sí, don Hernando, la pizarra está hecha un desastre.","Buenos días. Es verdad, quedó hecha un desastre.","Buenos días, don Hernando. Mire, la pizarra está hecha un desastre."],"require":[{"type":"regex","pattern":"\\bhech[oa] un desastre\\b","flags":"iu","label":"use: hecha un desastre"}],"focus":"p:estar-hecho-un-desastre","next":"t2"},{"id":"t2","npc":"Hernando: No importa. Mañana escribo otro y todos los huéspedes lo van a leer.","npcEn":"Hernando: Never mind. Tomorrow I'll write another and all the guests are going to read it.","intent":"Show disbelief: what do you mean all of them will read it? (use: ¿Cómo que...?).","accept":["¿Cómo que todos lo van a leer?","¿Cómo que todos, don Hernando? Si ni pasan por aquí.","¿Cómo que los huéspedes? Si no bajan del hotel."],"require":[{"type":"regex","pattern":"¿cómo que\\b","flags":"iu","label":"start with: ¿Cómo que...?"}],"focus":"p:como-que-echo","next":"t3"},{"id":"t3","npc":"Hernando: Admita que escribir chistes tiene su gracia.","npcEn":"Hernando: Admit that writing jokes has its charm.","intent":"Agree that it does, in your own words (use: tiene su + noun).","accept":["Sí, don Hernando, escribir chistes tiene su ciencia.","El chiste tiene su gracia, pero los huéspedes no lo van a entender.","Tiene su gracia, sí, y tiene su truco también."],"require":[{"type":"regex","pattern":"\\btiene su\\b","flags":"iu","label":"use: tiene su + noun"}],"focus":"p:tener-su-gracia","next":"t4"},{"id":"t4","npc":"Hernando: Vale dice que mis chistes son pesados. Y yo le dije que sus postres son peores.","npcEn":"Hernando: Vale says my jokes are heavy-handed. And I told her that her desserts are worse.","intent":"Tease him: you really do love to argue (use: ¡Mira que...!).","accept":["¡Mira que le gusta discutir, don Hernando!","¡Mira que es usted bromista!","¡Mira que le gusta llevar la contraria, don Hernando!"],"require":[{"type":"regex","pattern":"^\\W*mira que\\b","flags":"iu","label":"start with: ¡Mira que...!"},{"type":"avoidsAny","words":["eres"],"label":"use usted (es), not tú (eres)"}],"focus":"p:mira-que","next":"t5"},{"id":"t5","npc":"Hernando: ¿Y a usted le preocupa de verdad lo que piense el hotel?","npcEn":"Hernando: And are you really worried about what the hotel thinks?","intent":"Echo his question, then answer it with force: of course it worries you (use: ¿Que si...?).","accept":["¿Que si me preocupa? ¡Pues claro que me preocupa!","¿Que si me preocupa, don Hernando? ¡Muchísimo!","Don Hernando, ¿que si me preocupa? ¡Claro que sí!"],"require":[{"type":"regex","pattern":"¿que si\\b","flags":"iu","label":"use: ¿Que si...?"}],"focus":"g:emphatic-structures","next":"t6"},{"id":"t6","npc":"Hernando: Entonces mañana escribo otro. Venga temprano y le invito un tinto.","npcEn":"Hernando: Then tomorrow I'll write another. Come early and I'll treat you to a black coffee.","intent":"Thank him and say you'll be there early.","accept":["Gracias, don Hernando. Aquí estaré temprano.","Con gusto, don Hernando. Mañana vengo temprano.","Muchas gracias, el tinto lo tomo con mucho gusto."],"require":[],"focus":"g:emphatic-structures","next":null}],"r":["g:emphatic-structures","g:gender-articles","g:indirect-objects","g:present-ar","g:present-er-ir","g:that-clauses","p:como-que-echo","p:estar-hecho-un-desastre","p:mira-que","p:tener-su-gracia"],"d":558},
{"id":"sc-u54-c","unit":"u54","band":"C1","title":"Una entrevista sin filtro","brief":"You're Tomás, being interviewed by Mariana, a journalist and friend, so use tú. The chalkboard jokes have gone round the city, and she wants a quote. Play down your part, understate the hotel's reaction, and finish with a sharp line.","turns":[{"id":"t1","npc":"Mariana: Tomás, la gente dice que las bromas de la pizarra son tuyas. ¿Es verdad?","npcEn":"Mariana: Tomás, people say the chalkboard jokes are yours. Is that true?","intent":"Say that technically they're Hernando's (use: técnicamente).","accept":["Técnicamente no, son de Hernando. Yo solo las copio.","Técnicamente son de don Hernando; yo solo las escribo.","No, técnicamente son de Hernando. Yo solo lo ayudo."],"require":[{"type":"regex","pattern":"\\btécnicamente\\b","flags":"iu","label":"use: técnicamente"}],"focus":"p:personalmente-tecnicamente","next":"t2"},{"id":"t2","npc":"Mariana: ¿Y cómo reaccionó el hotel?","npcEn":"Mariana: And how did the hotel react?","intent":"Understate it: say they weren't exactly happy (use a negative).","accept":["No estaban precisamente felices.","Digamos que no les hizo mucha gracia.","No lo tomaron muy bien, la verdad."],"require":[{"type":"negation","label":"understate with a negative: no..."}],"focus":"g:hedging-distance","next":"t3"},{"id":"t3","npc":"Mariana: Dicen que la gerente llamó a la alcaldía.","npcEn":"Mariana: They say the manager called city hall.","intent":"Say that personally you couldn't care less (use: personalmente and importar un comino).","accept":["Personalmente, me importa un comino.","A mí personalmente me importa un pepino.","Me importa un comino, personalmente."],"require":[{"type":"regex","pattern":"\\bpersonalmente\\b","flags":"iu","label":"use: personalmente"},{"type":"regex","pattern":"\\bimporta un (comino|pepino|pito)\\b","flags":"iu","label":"use: me importa un comino"}],"focus":"p:importar-un-comino","next":"t4"},{"id":"t4","npc":"Mariana: Última pregunta: ¿qué mensaje le mandas al hotel?","npcEn":"Mariana: Last question: what message do you send the hotel?","intent":"Send an ironic message of thanks (use: ¡Qué detalle...! or Gracias por...).","accept":["¡Qué detalle construir un bar justo encima de nuestro patio!","Gracias por la serenata de anoche: nadie en el barrio pudo dormir.","Gracias por la vista, ahora todos nos saludan desde arriba."],"require":[{"type":"regex","pattern":"\\bqué detalle\\b|\\bgracias por\\b","flags":"iu","label":"use: ¡Qué detalle...! or Gracias por..."}],"focus":"p:ironic-praise","next":"t5"},{"id":"t5","npc":"Mariana: Perfecto, eso sale mañana. ¿Te invito un tinto?","npcEn":"Mariana: Perfect, that comes out tomorrow. Shall I treat you to a black coffee?","intent":"Accept, and ask her to quote Hernando, not you.","accept":["Acepto, pero cita a Hernando, no a mí.","Sí, gracias. Y por favor, cita a Hernando.","Con mucho gusto, Mariana. Pon a Hernando primero, no a mí."],"require":[],"focus":"g:hedging-distance","next":null}],"r":["g:gender-articles","g:hedging-distance","g:present-ar","g:preterite-ar","g:questions","g:stem-e-i","g:that-clauses","p:importar-un-comino","p:ironic-praise","p:personalmente-tecnicamente"],"d":595,"spare":true},
{"id":"sc-u54-d","unit":"u54","band":"C1","title":"Cien mil me gusta","brief":"You're Tomás, with Vale, who is your age, so use tú. A photo of the chalkboard has gone viral, and she keeps showing you her phone. Answer with the wishes and exclamations Spanish uses for surprise, hope and regret.","turns":[{"id":"t1","npc":"Vale: Tomás, mira el celular: la foto de la pizarra ya tiene cien mil me gusta.","npcEn":"Vale: Tomás, look at the phone: the photo of the chalkboard already has a hundred thousand likes.","intent":"Say who would have thought it (use: ¡Quién lo hubiera dicho!).","accept":["¡Quién lo hubiera dicho!","¡Cien mil! ¡Quién lo hubiera dicho!","¡Quién lo hubiera dicho, Vale!"],"require":[{"type":"regex","pattern":"\\bquién lo hubiera dicho\\b","flags":"iu","label":"use: ¡Quién lo hubiera dicho!"}],"focus":"g:wish-exclamatives","next":"t2"},{"id":"t2","npc":"Vale: Y el hotel ni contesta.","npcEn":"Vale: And the hotel doesn't even answer.","intent":"Wish they would at least reply (use: ¡Si al menos...! with the past subjunctive).","accept":["¡Si al menos contestaran!","¡Si al menos nos escribieran un mensaje!","¡Si al menos pidieran perdón por la música!"],"require":[{"type":"regex","pattern":"\\bsi al menos\\b","flags":"iu","label":"use: ¡Si al menos...!"}],"focus":"g:wish-exclamatives","next":"t3"},{"id":"t3","npc":"Vale: ¿Sabías que esto iba a pasar?","npcEn":"Vale: Did you know this was going to happen?","intent":"Protest that you already told her so (use: ¡Si ya te lo dije!).","accept":["¡Si ya te lo dije!","¡Pero si ya te lo dije, Vale!","¡Si te lo dije el lunes!"],"require":[{"type":"regex","pattern":"\\bsi (ya )?te lo dije\\b","flags":"iu","label":"use: ¡Si ya te lo dije!"}],"focus":"g:emphatic-structures","next":"t4"},{"id":"t4","npc":"Vale: Hernando quiere que escribas tú el chiste de mañana.","npcEn":"Vale: Hernando wants you to write tomorrow's joke.","intent":"Voice a regret: you wish you had never said yes (use: ¡Ojalá nunca...!).","accept":["¡Ojalá nunca le hubiera dicho que sí!","¡Ojalá nunca hubiera aceptado!","¡Ojalá no hubiera abierto la boca!"],"require":[{"type":"regex","pattern":"\\bojalá (nunca |no )?(le )?hubiera\\b","flags":"iu","label":"use: ¡Ojalá nunca hubiera...!"}],"focus":"g:wish-exclamatives","next":"t5"},{"id":"t5","npc":"Vale: Bueno, famoso. ¿Pan o buñuelo para celebrar?","npcEn":"Vale: Well, famous man. Bread or a fritter to celebrate?","intent":"Choose one and say you'll pay for the coffee.","accept":["Pan, y el café lo pago yo.","Buñuelo, por favor, y hoy invito yo.","Un pan, gracias. El café va por mi cuenta."],"require":[],"focus":"g:emphatic-structures","next":null}],"r":["g:emphatic-structures","g:gender-articles","g:stem-boot","g:that-clauses","g:wish-exclamatives"],"d":428,"spare":true},
{"id":"sc-u54-e","unit":"u54","band":"C1","title":"El gerente de al lado","brief":"You're Tomás, behind the counter. The manager of the hotel next door has come to complain, and she's a stranger, so use usted. Stay polite on the surface, let the irony do the work, and turn down her offer.","turns":[{"id":"t1","npc":"Gerente: Buenas tardes. Soy la gerente del hotel de al lado. ¿Podemos hablar de la pizarra?","npcEn":"Manager: Good afternoon. I'm the manager of the hotel next door. Can we talk about the chalkboard?","intent":"Welcome him, remarking that at last a neighbour has come to say hello (use: para variar).","accept":["Buenas tardes. Qué bien, para variar, alguien del hotel viene a saludar.","Para variar, una visita del hotel. Buenas tardes, pase.","Buenas tardes. Para variar, es usted quien viene a vernos."],"require":[{"type":"regex","pattern":"\\bpara variar\\b","flags":"iu","label":"use: para variar"}],"focus":"c:para-variar","next":"t2"},{"id":"t2","npc":"Gerente: Los chistes de su pizarra afectan la imagen de nuestro hotel.","npcEn":"Manager: The jokes on your chalkboard affect our hotel's image.","intent":"Ask how it is that a big hotel worries about a café with hardly any customers (use: ¿Cómo es que...? and cuatro gatos).","accept":["¿Cómo es que un hotel tan grande se preocupa por un café con cuatro gatos?","¿Cómo es que le molestan cuatro gatos y una pizarra?","¿Cómo es que usted se fija en un café con cuatro gatos?"],"require":[{"type":"regex","pattern":"¿cómo es que\\b","flags":"iu","label":"use: ¿Cómo es que...?"},{"type":"regex","pattern":"\\bcuatro gatos\\b","flags":"iu","label":"use: cuatro gatos"}],"focus":"p:como-es-que","next":"t3"},{"id":"t3","npc":"Gerente: Nuestros huéspedes pagan mucho por una noche tranquila.","npcEn":"Manager: Our guests pay a lot for a quiet night.","intent":"Answer with irony: yes, last night was very quiet (say tranquila).","accept":["Sí, y anoche fue una noche muy tranquila: música hasta las tres.","Claro, anoche la azotea estuvo muy tranquila, ¿verdad?","Qué bien, porque anoche fue una noche muy tranquila para todos."],"require":[{"type":"regex","pattern":"\\btranquil","flags":"iu","label":"include: tranquila"},{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"focus":"p:ironic-praise","next":"t4"},{"id":"t4","npc":"Gerente: Le propongo un trato: ustedes quitan los chistes y yo les regalo una cena.","npcEn":"Manager: I propose a deal: you take down the jokes and I give you a dinner.","intent":"Refuse flatly (use: Ni pensarlo).","accept":["Ni pensarlo, señora. Los chistes se quedan.","Ni pensarlo. Los chistes se quedan donde están.","Señora, ni pensarlo: no voy a quitar los chistes."],"require":[{"type":"regex","pattern":"\\bni pensarlo\\b","flags":"iu","label":"use: Ni pensarlo"}],"focus":"p:ni-emphatic","next":"t5"},{"id":"t5","npc":"Gerente: Veo que no cambia de opinión. Al menos regáleme un tinto.","npcEn":"Manager: I see you won't change your mind. At least give me a black coffee.","intent":"Relent warmly: the coffee is on the house, but he must read today's joke first.","accept":["Con gusto, el tinto va por la casa. Pero primero lea el chiste de hoy.","Claro, señora. El tinto va por la casa, y mire el chiste de hoy.","Siéntese, le preparo un tinto, pero lea el chiste primero."],"require":[],"focus":"g:emphatic-structures","next":null}],"r":["c:para-variar","g:emphatic-structures","g:gender-articles","g:possessives","g:present-ar","g:yo-irregular","p:como-es-que","p:ironic-praise","p:ni-emphatic"],"d":630,"spare":true},
{"id":"sc-u54-f","unit":"u54","band":"C1","title":"El loro tiene ingenio","brief":"You're Tomás, talking with Don Hernando, who is much older than you, so use usted. Simón the parrot has learned one of the jokes and repeated it to a hotel guest. Praise, tease and find the bright side.","turns":[{"id":"t1","npc":"Hernando: Tomás, Simón ya se aprendió el chiste de hoy y se lo dijo a un huésped.","npcEn":"Hernando: Tomás, Simón has already learned today's joke and told it to a guest.","intent":"Say Simón talks nonstop (use: hablar por los codos).","accept":["Simón habla por los codos, don Hernando.","Ese loro habla por los codos, ya lo sabe.","Pues claro, si Simón habla por los codos."],"require":[{"type":"regex","pattern":"\\bpor los codos\\b","flags":"iu","label":"use: hablar por los codos"}],"focus":"c:hablar-por-los-codos","next":"t2"},{"id":"t2","npc":"Hernando: Dicen en el hotel que el loro tiene más ingenio que yo.","npcEn":"Hernando: They say at the hotel that the parrot has more wit than I do.","intent":"Say that if anyone has wit around here, it is him (use: Si alguien...es...).","accept":["Si alguien tiene ingenio aquí, es usted, don Hernando.","Si algo tengo claro es que nadie tiene su ingenio.","Si de algo estoy seguro es de su ingenio, don Hernando."],"require":[{"type":"regex","pattern":"^\\W*si (alguien|algo|de algo)\\b","flags":"iu","label":"start with: Si alguien / Si algo / Si de algo"},{"type":"avoidsAny","words":["tienes","eres"],"label":"use usted, not tú"}],"focus":"p:si-algo-es","next":"t3"},{"id":"t3","npc":"Hernando: Pero el loro no se queda atrás: el huésped se rio y le dio galletas.","npcEn":"Hernando: But the parrot is no slouch either: the guest laughed and gave him cookies.","intent":"Find the bright side: at least a guest laughed (use: que ya es algo).","accept":["Al menos un huésped se rio, que ya es algo.","Simón ya cobra en galletas, que ya es algo.","Alguien del hotel se rio, don Hernando, que ya es algo."],"require":[{"type":"regex","pattern":"\\bque ya es algo\\b","flags":"iu","label":"use: que ya es algo"}],"focus":"c:que-ya-es-algo","next":"t4"},{"id":"t4","npc":"Hernando: Ahora dicen que Simón les mama gallo a los huéspedes a propósito.","npcEn":"Hernando: Now they say Simón teases the guests on purpose.","intent":"Say Simón is not teasing them, he only repeats what he hears.","accept":["Simón no les mama gallo, solo repite lo que oye.","No les está mamando gallo, don Hernando. Solo repite lo que oye.","Él no bromea, don Hernando. Solo repite lo que escucha."],"require":[{"type":"negation","label":"say what Simón is not doing: no..."}],"focus":"c:mamar-gallo","next":"t5"},{"id":"t5","npc":"Hernando: Entonces mañana le enseño uno nuevo. ¿Me acompaña a tomar un tinto?","npcEn":"Hernando: Then tomorrow I'll teach him a new one. Will you join me for a black coffee?","intent":"Accept, and tease him: he really does love that parrot (use: ¡Mire que...!).","accept":["Con gusto. ¡Mire que le gusta enseñarle cosas a ese loro!","Claro que sí. ¡Mire que le encanta ese loro, don Hernando!","Encantado, don Hernando. ¡Mire que es usted terco con ese loro!"],"require":[{"type":"regex","pattern":"\\bmire que\\b","flags":"iu","label":"use: ¡Mire que...!"},{"type":"avoidsAny","words":["eres","te gusta","te encanta"],"label":"use usted (mire, le), not tú"}],"focus":"p:mira-que","next":null}],"r":["c:hablar-por-los-codos","c:mamar-gallo","c:que-ya-es-algo","g:gender-articles","g:indirect-objects","g:present-ar","g:preterite-irregular-strong","g:stem-e-i","p:mira-que","p:si-algo-es"],"d":582,"spare":true},
{"id":"sc-u55-a","unit":"u55","band":"C1","title":"Acta de constitución","brief":"You're Tomás, at the first meeting of the new cooperative. Mariana is taking the minutes and speaks formally, so keep your register measured and use usted with her. Help the group settle costs, record how the statutes were approved and name the neighbours who sign.","turns":[{"id":"t1","npc":"Mariana: Buenas tardes. Hay quórum, así que podemos empezar. ¿Cómo propone usted repartir los gastos del edificio?","npcEn":"Mariana: Good afternoon. We have a quorum, so we can begin. How do you propose to split the building's costs?","intent":"Propose that the costs are split equally among all the members (use: a partes iguales).","accept":["Propongo que los gastos se repartan a partes iguales.","Yo diría que se paguen a partes iguales entre todos los asociados.","Que los gastos se repartan a partes iguales entre todos."],"require":[{"type":"regex","pattern":"\\ba partes iguales\\b","flags":"iu","label":"use: a partes iguales"}],"focus":"p:a-partes-iguales","next":"t2"},{"id":"t2","npc":"Mariana: Anotado. Ahora los estatutos: ¿cómo quedaron aprobados?","npcEn":"Mariana: Noted. Now the statutes: how were they approved?","intent":"Say the statutes were approved by consensus (use: por consenso).","accept":["Quedaron aprobados por consenso.","Los estatutos se aprobaron por consenso, sin votos en contra.","Se aprobaron por consenso."],"require":[{"type":"regex","pattern":"\\bpor consenso\\b","flags":"iu","label":"use: por consenso"}],"focus":"p:por-consenso","next":"t3"},{"id":"t3","npc":"Mariana: Falta una firma. ¿Quién es la señora de la tienda?","npcEn":"Mariana: One signature is missing. Who is the lady from the shop?","intent":"Say it's Doña Fanny, whose shop is on this same block (use: cuya).","accept":["Es doña Fanny, cuya tienda queda en esta cuadra.","Doña Fanny, cuya tienda está en la misma cuadra, es la asociada que falta.","Es doña Fanny, la señora cuya tienda está aquí en la cuadra."],"require":[{"type":"regex","pattern":"\\bcuy[oa]s?\\b","flags":"iu","label":"use: cuyo / cuya"}],"focus":"g:cuyo-relatives","next":"t4"},{"id":"t4","npc":"Mariana: ¿Y cuándo empieza a funcionar la cooperativa, según usted?","npcEn":"Mariana: And when does the cooperative start operating, in your view?","intent":"Say it starts after the signing of the statutes, using a noun rather than a verb (use: tras la firma / después de la firma).","accept":["Empieza tras la firma de los estatutos.","Después de la firma de los estatutos, la cooperativa empieza a funcionar.","Tras la firma de los estatutos, el lunes mismo."],"require":[{"type":"regex","pattern":"\\b(tras|después de) la firma\\b","flags":"iu","label":"use: tras / después de + la firma"}],"focus":"g:nominalisation","next":"t5"},{"id":"t5","npc":"Mariana: Perfecto. Queda cerrada la sesión. ¿Un tinto antes de irnos?","npcEn":"Mariana: Perfect. The session is closed. A coffee before we go?","intent":"Thank her and accept the coffee, politely.","accept":["Con mucho gusto. Muchas gracias por su trabajo, Mariana.","Sí, gracias. Hoy invito yo.","Claro, un tinto me viene bien. Gracias, Mariana."],"require":[{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"next":null}],"r":["g:cuyo-relatives","g:gender-articles","g:nominalisation","g:present-ar","g:questions","g:verb-infinitive","p:a-partes-iguales","p:por-consenso"],"d":null},
{"id":"sc-u55-b","unit":"u55","band":"C1","title":"Ventanilla tres","brief":"You're Tomás at the commercial registry window. The clerk is a stranger and a civil servant, so use usted all the way. You need to register the cooperative: say what is done, in what order, and ask what remains.","turns":[{"id":"t1","npc":"Funcionaria: Buenas. Pase, por favor. ¿Qué trámite viene a hacer hoy?","npcEn":"Clerk: Hello. Come up, please. What procedure are you here to do today?","intent":"Say you come to register a cooperative, and ask what you need (use usted).","accept":["Buenos días. Vengo a registrar una cooperativa. ¿Qué necesito?","Vengo a inscribir una cooperativa. ¿Qué documentos necesito?","Buenos días, señora. Quiero registrar nuestra cooperativa. ¿Qué debo traer?"],"require":[{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"},{"type":"question"}],"focus":"g:questions","next":"t2"},{"id":"t2","npc":"Funcionaria: Primero lo primero: ¿ya tiene los estatutos?","npcEn":"Clerk: First things first: do you already have the statutes?","intent":"Say the statutes are already approved and signed, opening with a participle (like Firmados los estatutos, …).","accept":["Aprobados los estatutos, solo falta el registro.","Firmados los estatutos, vengo a entregarlos.","Una vez aprobados los estatutos, los firmamos todos."],"require":[{"type":"regex","pattern":"\\b(aprobados|firmados|aprobado|firmado)\\b","flags":"iu","label":"open with a participle: aprobados / firmados + noun"}],"focus":"g:absolute-constructions","next":"t3"},{"id":"t3","npc":"Funcionaria: Bien. Hay que entregar la solicitud con antelación, ¿sabe? Se atiende por orden de llegada.","npcEn":"Clerk: Good. The application has to be submitted in advance, you know. People are served in order of arrival.","intent":"Say you knew that beforehand, so you brought everything, and ask if you can leave it today (use: de antemano).","accept":["Lo sabía de antemano, así que traje todo. ¿Puedo dejarlo hoy?","Ya lo sabía de antemano. Aquí tengo todo. ¿Se lo puedo dejar hoy?","Sí, lo sabía de antemano y traje los papeles. ¿Puedo entregarlos hoy?"],"require":[{"type":"regex","pattern":"\\bde antemano\\b","flags":"iu","label":"use: de antemano"},{"type":"question"}],"focus":"x:antemano-antelacion","next":"t4"},{"id":"t4","npc":"Funcionaria: Sí. Tras la revisión de los documentos, le llamamos para la inscripción.","npcEn":"Clerk: Yes. After the review of the documents, we will call you for the registration.","intent":"Ask how long the review takes, using a noun (use: la revisión).","accept":["¿Cuánto tarda la revisión de los documentos?","¿Cuánto demora la revisión?","Perdone, ¿cuánto dura la revisión de los papeles?"],"require":[{"type":"question"},{"type":"regex","pattern":"\\brevisión\\b","flags":"iu","label":"use: la revisión"}],"focus":"g:nominalisation","next":"t5"},{"id":"t5","npc":"Funcionaria: Unos cinco días hábiles. Eso sí, el plazo para el registro vence en octubre.","npcEn":"Clerk: About five working days. Mind you, the deadline for registration runs out in October.","intent":"Thank her and say goodbye, politely.","accept":["Muchas gracias, señora. Que tenga un buen día.","Gracias por su ayuda. Hasta luego.","Se lo agradezco mucho. Buenos días."],"require":[{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"next":null}],"r":["g:absolute-constructions","g:gender-articles","g:nominalisation","g:present-er-ir","g:questions","g:stem-boot","x:antemano-antelacion"],"d":null},
{"id":"sc-u55-c","unit":"u55","band":"C1","title":"Del estatuto a la piscina","brief":"You're Tomás, on the phone with your cousin Yesid, who teases you about sounding like a form. He's family, so use tú. Explain what the cooperative needs in plain words, then wish him luck with his pool lessons.","turns":[{"id":"t1","npc":"Yesid: Primo, me dicen que ahora hablas como un decreto. ¿Qué hicieron esta semana?","npcEn":"Yesid: Cousin, they tell me you now talk like a decree. What did you all do this week?","intent":"Say you all signed the statutes of the cooperative this week.","accept":["Firmamos los estatutos de la cooperativa esta semana.","Esta semana firmamos el estatuto de la cooperativa, primo.","Ya firmamos los estatutos, Yesid."],"require":[{"type":"verbForm","inf":"firmar","tense":"preterito","person":"nosotros","label":"use: firmamos"}],"focus":"g:preterite-ar","next":"t2"},{"id":"t2","npc":"Yesid: ¿Y qué tengo que hacer yo? Dime en cristiano.","npcEn":"Yesid: And what do I have to do? Tell me in plain language.","intent":"Tell him all he has to do is sign here (use: basta con que + subjunctive).","accept":["Basta con que firmes aquí.","Basta con que firmes aquí, primo, nada más.","Tranquilo, basta con que firmes aquí."],"require":[{"type":"regex","pattern":"\\bbasta con que firmes\\b","flags":"iu","label":"use: basta con que firmes"}],"focus":"p:basta-con","next":"t3"},{"id":"t3","npc":"Yesid: ¿Y el edificio? ¿Es de la cooperativa o de la familia?","npcEn":"Yesid: And the building? Is it the cooperative's or the family's?","intent":"Say it now belongs to the cooperative, whose members include the whole family (use: cuyos).","accept":["Es de la cooperativa, cuyos asociados son la familia y los vecinos.","Ahora es de la cooperativa, cuyos socios incluyen a toda la familia.","Es de la cooperativa, cuyos dueños somos todos nosotros, primo."],"require":[{"type":"regex","pattern":"\\bcuyos\\b","flags":"iu","label":"use: cuyos"}],"focus":"g:cuyo-relatives","next":"t4"},{"id":"t4","npc":"Yesid: Pues yo vine a Bogotá a enseñarle a nadar a Jhon Fredy. ¡Y no sabe flotar!","npcEn":"Yesid: Well, I came to Bogotá to teach Jhon Fredy to swim. And he can't float!","intent":"Wish him luck by saying you hope he learns soon (use: ojalá + subjunctive).","accept":["¡Ojalá aprenda pronto!","¡Ojalá aprenda a nadar antes de diciembre!","¡Ojalá no se hunda en la primera clase!"],"require":[{"type":"regex","pattern":"(?<![\\p{L}])ojalá(?![\\p{L}])","flags":"iu","label":"use: ojalá + subjunctive"},{"type":"subjunctiveAfter","trigger":"ojalá","label":"after ojalá, use the subjunctive"}],"focus":"g:wish-exclamatives","next":"t5"},{"id":"t5","npc":"Yesid: Gracias, primo. Mañana te cuento. ¡Un abrazo!","npcEn":"Yesid: Thanks, cousin. Tomorrow I'll tell you. A hug!","intent":"Say goodbye warmly, to a relative (use tú).","accept":["Un abrazo, Yesid. Hablamos mañana.","Chao, primo. Cuídate mucho.","Hasta mañana, Yesid. Un abrazo para Jhon Fredy."],"require":[{"type":"avoidsPerson","person":"ellos","label":"keep it to one person"}],"next":null}],"r":["g:cuyo-relatives","g:gender-articles","g:preterite-ar","g:wish-exclamatives","p:basta-con"],"d":null,"spare":true},
{"id":"sc-u56-a","unit":"u56","band":"C1","title":"La primera frase","brief":"You're Tomás, in the newspaper office with Mariana, who is reading the opening of your essay for the competition. She's a friend your age, so use tú. Defend your thesis in short, clear sentences.","turns":[{"id":"t1","npc":"Mariana: Leí tu primer párrafo. ¿Cuál es tu idea central, dicha en una sola frase?","npcEn":"Mariana: I read your first paragraph. What is your central idea, said in a single sentence?","intent":"State your thesis: a city that forgets pays for it (use: tarde o temprano).","accept":["Una ciudad que olvida su pasado lo paga tarde o temprano.","Tarde o temprano, la ciudad paga lo que olvida.","Mi idea es que, tarde o temprano, el olvido se paga."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])(?:tarde o temprano)(?![\\p{L}])","flags":"iu","label":"use: tarde o temprano"}],"focus":"c:tarde-o-temprano","next":"t2"},{"id":"t2","npc":"Mariana: Mucha gente cree que para avanzar hay que olvidar. ¿Qué piensas de eso?","npcEn":"Mariana: Many people think that to move forward you have to forget. What do you think about that?","intent":"Say you agree with them that the city has to grow, but not that it has to forget (use: coincidir en).","accept":["Coincido con ellos en que la ciudad tiene que crecer, pero no en que deba olvidar.","Coincido en que hay que construir, pero no en que haya que olvidar.","Coincido con esa gente en que hay que avanzar, pero no en que haya que olvidar."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])(?:coincido)(?![\\p{L}])","flags":"iu","label":"use: coincido ... en"}],"focus":"p:coincidir-en","next":"t3"},{"id":"t3","npc":"Mariana: Bien. Ahora separa dos ideas: ¿es lo mismo conservar un edificio que recordar a quienes vivieron en él?","npcEn":"Mariana: Good. Now separate two ideas: is keeping a building the same as remembering the people who lived in it?","intent":"Say it is one thing to keep a building and quite another to remember its people (use: una cosa es ... y otra).","accept":["Una cosa es conservar un edificio y otra muy distinta recordar a su gente.","Una cosa es guardar las paredes y otra recordar a quienes vivieron en ellas.","No es lo mismo: una cosa es conservar un edificio y otra recordar a su gente."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])(?:una cosa es)(?![\\p{L}])","flags":"iu","label":"use: una cosa es ... y otra"}],"focus":"p:una-cosa-es-otra","next":"t4"},{"id":"t4","npc":"Mariana: Muy bien. ¿Qué pregunta debe quedarle al lector cuando termine tu ensayo?","npcEn":"Mariana: Very good. What question should the reader be left with when your essay ends?","intent":"Pose the question: can a city move forward without remembering? (use: cabe preguntarse si).","accept":["Cabe preguntarse si una ciudad puede avanzar sin recordar.","Cabe preguntarse si el progreso es posible sin memoria.","Al final, cabe preguntarse si una ciudad avanza sin recordar su pasado."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])(?:cabe preguntarse)(?![\\p{L}])","flags":"iu","label":"use: cabe preguntarse si"}],"focus":"p:cabe-preguntarse","next":"t5"},{"id":"t5","npc":"Mariana: Perfecto. Mientras leo tu ensayo, ¿te traigo un tinto?","npcEn":"Mariana: Perfect. While I read your essay, shall I bring you a coffee?","intent":"Accept and thank her, as a friend.","accept":["Sí, gracias, Mariana. Un tinto me viene muy bien.","Claro, gracias. Yo espero aquí.","Con mucho gusto, y gracias por la ayuda."],"require":[{"type":"avoidsAny","words":["usted","ustedes"],"label":"use tú with a friend, not usted"}],"next":null}],"r":["c:tarde-o-temprano","g:gender-articles","g:present-er-ir","g:preterite-er-ir","g:questions","p:cabe-preguntarse","p:coincidir-en","p:una-cosa-es-otra"],"d":46},
{"id":"sc-u56-b","unit":"u56","band":"C1","title":"De quién es la calle","brief":"You're Tomás, at the café with Don Hernando, who loves a good argument and speaks courtly Spanish. He's much older, so use usted. Defend your idea that a street belongs to everyone and meet his objections.","turns":[{"id":"t1","npc":"Hernando: Joven, usted escribe que la calle es de todos. ¿Qué se entiende por eso, exactamente?","npcEn":"Hernando: Young man, you write that the street belongs to everyone. What is understood by that, exactly?","intent":"Define it: a public street is understood to be a space nobody can close (use: se entiende por).","accept":["Se entiende por calle pública un espacio que nadie puede cerrar.","Se entiende por calle de todos un lugar que nadie puede cerrar, don Hernando.","Por calle pública se entiende un espacio que nadie puede cerrar."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])(?:se entiende por|por [^.]{1,30} se entiende)(?![\\p{L}])","flags":"iu","label":"use: se entiende por"}],"focus":"p:se-entiende-por","next":"t2"},{"id":"t2","npc":"Hernando: Pero los vecinos pagan impuestos, y eso les da derechos sobre la calle.","npcEn":"Hernando: But the neighbours pay taxes, and that gives them rights over the street.","intent":"Concede it, then answer: although they pay taxes, the street is not for sale (use: si bien, por mucho que or aun cuando).","accept":["Si bien los vecinos pagan impuestos, la calle no se vende.","Por mucho que paguen impuestos, nadie puede comprar la calle.","Aun cuando paguen impuestos, la calle sigue siendo de todos."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])(?:si bien|por mucho que|aun cuando|por muy \\p{L}+ que)(?![\\p{L}])","flags":"iu","label":"use: si bien, por mucho que or aun cuando"}],"focus":"g:concessive-advanced","next":"t3"},{"id":"t3","npc":"Hernando: Altamira dice que sus obras traen progreso. ¿Usted qué responde?","npcEn":"Hernando: Altamira says its works bring progress. What do you answer?","intent":"Say that we cannot overlook what is lost (use: pasar por alto).","accept":["No podemos pasar por alto lo que se pierde.","Nadie debería pasar por alto lo que se pierde con esas obras.","Si pasamos por alto lo que se pierde, el progreso sale muy caro."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])(?:pasar por alto|pasamos por alto|pasan por alto|pasa por alto|pasó por alto|pasaron por alto)(?![\\p{L}])","flags":"iu","label":"use: pasar por alto"}],"focus":"p:pasar-por-alto","next":"t4"},{"id":"t4","npc":"Hernando: Entonces, ¿qué debe hacer el barrio con una empresa tan grande?","npcEn":"Hernando: So what should the neighbourhood do about such a big company?","intent":"Say the neighbourhood has to face the company together (use: hacer frente a).","accept":["El barrio tiene que hacerle frente unido.","Hay que hacer frente a Altamira entre todos los vecinos.","Los vecinos debemos hacer frente a la empresa juntos."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])(?:hacer frente|hacerle frente|hacerles frente|hacemos frente|hace frente|hacen frente|haremos frente)(?![\\p{L}])","flags":"iu","label":"use: hacer frente a"}],"focus":"p:hacer-frente-a","next":"t5"},{"id":"t5","npc":"Hernando: Me convenció a medias, pero hablaré bien de su ensayo en la mesa de dominó. ¿Le sirvo otro tinto?","npcEn":"Hernando: You half convinced me, but I will speak well of your essay at the domino table. Shall I pour you another coffee?","intent":"Thank him and accept, politely.","accept":["Sí, gracias, don Hernando. Esta vez invito yo.","Con mucho gusto, y gracias por escucharme.","Claro que sí, muchas gracias."],"require":[{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"next":null}],"r":["g:concessive-advanced","g:gender-articles","g:indirect-objects","g:present-er-ir","g:questions","g:stem-e-i","g:that-clauses","p:hacer-frente-a","p:pasar-por-alto","p:se-entiende-por"],"d":595},
{"id":"sc-u56-c","unit":"u56","band":"C1","title":"Ante el jurado","brief":"You're Tomás, reading your essay in public at the library. A member of the jury asks the questions and speaks formally, so use usted. Defend your argument with concessions and consequences.","turns":[{"id":"t1","npc":"Buenas noches y bienvenido. ¿Qué defiende su ensayo, en pocas palabras?","npcEn":"Good evening and welcome. What does your essay defend, in a few words?","intent":"Say that a city forgets quickly, so it repeats its mistakes (use: de ahí que, de manera que or por consiguiente).","accept":["Una ciudad olvida muy rápido, de manera que repite sus errores.","La ciudad olvida con rapidez; de ahí que repita sus errores.","Las ciudades olvidan pronto; por consiguiente, repiten sus errores."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])(?:de ahí que|de manera que|de modo que|por consiguiente|así pues)(?![\\p{L}])","flags":"iu","label":"use: de ahí que, de manera que or por consiguiente"}],"focus":"g:consecutive-advanced","next":"t2"},{"id":"t2","npc":"Algunos dirán que usted es un nostálgico. ¿Qué responde?","npcEn":"Some will say you are a nostalgic. What do you answer?","intent":"Say that however nostalgic they call you, you defend the future of the neighbourhood (use: por muy ... que or por mucho que).","accept":["Por muy nostálgico que me llamen, defiendo el futuro del barrio.","Por mucho que me llamen nostálgico, lo que defiendo es el futuro del barrio.","Por muy nostálgico que parezca, defiendo el futuro de este barrio."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])(?:por muy \\p{L}+ que|por mucho que)(?![\\p{L}])","flags":"iu","label":"use: por muy ... que or por mucho que"}],"focus":"g:concessive-advanced","next":"t3"},{"id":"t3","npc":"Los vecinos de la calle protestaron esta semana. ¿Por qué lo hicieron?","npcEn":"The neighbours on the street protested this week. Why did they do it?","intent":"Say nobody asked them, hence the protest (use: de ahí que + subjunctive).","accept":["Nadie les preguntó; de ahí que protestaran.","Nadie preguntó a los vecinos, de ahí que hayan protestado.","No los escucharon, de ahí que protestaran con tanta fuerza."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])(?:de ahí que)(?![\\p{L}])","flags":"iu","label":"use: de ahí que"}],"focus":"g:consecutive-advanced","next":"t4"},{"id":"t4","npc":"Su abuela dejó cartas sin enviar. ¿Las leyó antes de escribir el ensayo?","npcEn":"Your grandmother left unsent letters. Did you read them before writing the essay?","intent":"Say that even though it was hard, you read them all (use: si bien or aun cuando).","accept":["Si bien fue difícil, las leí todas.","Aun cuando me dolió, las leí todas antes de escribir.","Las leí todas, si bien me costó mucho."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])(?:si bien|aun cuando|por mucho que)(?![\\p{L}])","flags":"iu","label":"use: si bien or aun cuando"}],"focus":"g:concessive-advanced","next":"t5"},{"id":"t5","npc":"Gracias, el jurado decidirá ahora. ¿Quiere decir algo más?","npcEn":"Thank you, the jury will now decide. Do you want to say anything else?","intent":"Thank the jury politely and say you are glad to be here.","accept":["Solo darles las gracias. Me alegra mucho estar aquí.","Muchas gracias por escucharme. Estoy muy contento de estar aquí.","Gracias a todos ustedes. Para mí ha sido un honor."],"require":[{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"next":null}],"r":["g:concessive-advanced","g:consecutive-advanced","g:direct-objects","g:future-promises","g:gender-articles","g:preterite-ar","g:questions","g:stem-boot"],"d":null},
{"id":"sc-u56-d","unit":"u56","band":"C1","title":"Entre dos hornadas","brief":"You're Tomás, on the phone with Vale, who has just read your draft between two batches of bread. She's quick and dry, and she's your friend, so use tú. Answer her questions about the draft.","turns":[{"id":"t1","npc":"Vale: Leí tu borrador entre dos hornadas. Dices que los arriendos del barrio suben. ¿Qué tanto?","npcEn":"Vale: I read your draft between two batches. You say the rents in the neighbourhood are going up. How much?","intent":"Say that the rents have been on the rise since Altamira arrived (use: ir en aumento).","accept":["Los arriendos van en aumento desde que llegó Altamira.","Desde que llegó Altamira, el precio de los arriendos va en aumento.","Van en aumento, Vale, y cada mes más."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])(?:van en aumento|va en aumento|vamos en aumento|iban en aumento|iba en aumento)(?![\\p{L}])","flags":"iu","label":"use: ir en aumento"}],"focus":"p:ir-en-aumento","next":"t2"},{"id":"t2","npc":"Vale: Y tu tesis sobre el progreso. ¿No suena a nostalgia disfrazada?","npcEn":"Vale: And your thesis about progress. Does it not sound like disguised nostalgia?","intent":"Say she has a point, but nostalgia is not your argument (use: no te falta razón).","accept":["No te falta razón, pero la nostalgia no es mi argumento.","No te falta razón, Vale; aun así, mi argumento es otro.","Algo de razón tienes, pero la nostalgia no es mi argumento."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])(?:no te falta razón|algo de razón tienes)(?![\\p{L}])","flags":"iu","label":"use: no te falta razón"}],"focus":"p:no-te-falta-razon","next":"t3"},{"id":"t3","npc":"Vale: En mi cocina se prevé lo que va a pasar y se previene lo que sale mal. ¿Y en tu ensayo?","npcEn":"Vale: In my kitchen you foresee what is going to happen and you prevent what goes wrong. And in your essay?","intent":"Say that nobody foresaw the sale of the block, but the loss can still be prevented (use: prever and prevenir).","accept":["Nadie previó la venta de la cuadra, pero todavía se puede prevenir la pérdida.","Nadie previó la venta, pero aún podemos prevenir lo peor.","Nadie lo previó, pero todavía podemos prevenir más daños."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])(?:previó|previeron|preví|previmos|prevé|prevén)(?![\\p{L}])","flags":"iu","label":"use: prever (previó)"},{"type":"regex","pattern":"(?<![\\p{L}])(?:prevenir|previene|previenen|prevenimos|prevengamos)(?![\\p{L}])","flags":"iu","label":"use: prevenir"}],"focus":"p:prever-prevenir","next":"t4"},{"id":"t4","npc":"Vale: Oye, ¿y no te da miedo leerlo en voz alta delante de tanta gente?","npcEn":"Vale: Listen, are you not afraid of reading it aloud in front of so many people?","intent":"Say it scares you a little, and at the same time it excites you (use: al tiempo que or a la vez que).","accept":["Me da miedo, al tiempo que me emociona.","Un poco, sí. Tengo miedo a la vez que tengo muchas ganas.","Me asusta un poco, a la vez que me da mucha emoción."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])(?:al tiempo que|a la vez que)(?![\\p{L}])","flags":"iu","label":"use: al tiempo que or a la vez que"}],"focus":"p:al-tiempo-que","next":"t5"},{"id":"t5","npc":"Vale: Ven mañana temprano y te guardo una empanada. ¿Te animas?","npcEn":"Vale: Come early tomorrow and I'll save you an empanada. Are you in?","intent":"Say yes and thank her, as a friend.","accept":["Claro que me animo, gracias, Vale.","Sí, gracias. Llego a las siete.","Con mucho gusto. Gracias, Vale."],"require":[{"type":"avoidsAny","words":["usted","ustedes"],"label":"use tú with a friend, not usted"}],"next":null}],"r":["g:gender-articles","g:present-ar","g:present-er-ir","g:stem-boot","p:al-tiempo-que","p:ir-en-aumento","p:no-te-falta-razon","p:prever-prevenir"],"d":622,"spare":true},
{"id":"sc-u56-e","unit":"u56","band":"C1","title":"Mesa redonda","brief":"You're Tomás, at a radio round table. Across from you sits a manager from Altamira, polite and polished. You've never met, so use usted. Disagree with him respectfully and keep your points clear.","turns":[{"id":"t1","npc":"Buenas noches. Para Altamira, el progreso se mide en viviendas nuevas y empleos. ¿Está usted de acuerdo?","npcEn":"Good evening. For Altamira, progress is measured in new homes and jobs. Do you agree?","intent":"Say you agree insofar as that progress does not erase the neighbourhood (use: en la medida en que).","accept":["Estoy de acuerdo en la medida en que ese progreso no borre el barrio.","Sí, en la medida en que no se pierda la memoria de la calle.","En la medida en que respete a los vecinos, estoy de acuerdo."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])(?:en la medida en que)(?![\\p{L}])","flags":"iu","label":"use: en la medida en que"}],"focus":"p:en-la-medida-en-que","next":"t2"},{"id":"t2","npc":"¿Y qué propone usted en concreto para el barrio?","npcEn":"And what do you propose in concrete terms for the neighbourhood?","intent":"Say that, broadly speaking, the new building should keep the old façade (use: a grandes rasgos).","accept":["A grandes rasgos, el edificio nuevo debe conservar la fachada vieja.","Mi propuesta, a grandes rasgos, es que se conserve la fachada.","A grandes rasgos, propongo que la fachada antigua se conserve."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])(?:a grandes rasgos)(?![\\p{L}])","flags":"iu","label":"use: a grandes rasgos"}],"focus":"p:a-grandes-rasgos","next":"t3"},{"id":"t3","npc":"El progreso depende de las inversiones. Eso es evidente.","npcEn":"Progress depends on investment. That is obvious.","intent":"Say that it also depends to a large extent on whether people trust the plans (use: en gran medida).","accept":["También depende, en gran medida, de que la gente confíe en los planes.","Depende en gran medida de la confianza de la gente en los planes.","En gran medida depende de que los vecinos confíen en el plan."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])(?:en gran medida|en buena medida)(?![\\p{L}])","flags":"iu","label":"use: en gran medida"}],"focus":"p:en-gran-medida","next":"t4"},{"id":"t4","npc":"Entonces, ¿qué queda por resolver, a su juicio?","npcEn":"So what remains to be settled, in your view?","intent":"Say it remains to be settled who decides what is kept (use: queda por resolver).","accept":["Queda por resolver quién decide qué se conserva.","Lo que queda por resolver es quién decide qué se guarda.","Queda por resolver quién tiene la última palabra sobre la calle."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])(?:queda por resolver|quedan por resolver)(?![\\p{L}])","flags":"iu","label":"use: queda por resolver"}],"focus":"p:queda-por-resolver","next":"t5"},{"id":"t5","npc":"Respetuoso desacuerdo, entonces. Le dejo mi tarjeta.","npcEn":"A respectful disagreement, then. I will leave you my card.","intent":"Take it politely and say you will call after the competition.","accept":["Gracias. Lo llamo cuando termine el concurso.","Muchas gracias; después del concurso lo llamaré.","Se lo agradezco. Lo llamaré en cuanto termine el concurso."],"require":[{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"next":null}],"r":["g:gender-articles","g:present-ar","g:questions","p:a-grandes-rasgos","p:en-gran-medida","p:en-la-medida-en-que","p:queda-por-resolver"],"d":600,"spare":true},
{"id":"sc-u56-f","unit":"u56","band":"C1","title":"Ventanilla de inscripción","brief":"You're Tomás, at the desk of the newspaper, registering your essay for the competition. The clerk is brisk and formal, so use usted. Give the details she asks for, one by one.","turns":[{"id":"t1","npc":"Buenas tardes. Para inscribir el ensayo necesito el título. ¿Cómo se llama?","npcEn":"Good afternoon. To register the essay I need the title. What is it called?","intent":"Say the essay is called \"La calle que recuerda\".","accept":["Se llama La calle que recuerda.","El título es La calle que recuerda.","La calle que recuerda, señora."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])(?:la calle que recuerda)(?![\\p{L}])","flags":"iu","label":"the title is: La calle que recuerda"}],"next":"t2"},{"id":"t2","npc":"Muy bien. Ahora el resumen: empiécelo como se hace en un trabajo serio. ¿Cómo lo empieza?","npcEn":"Very good. Now the summary: begin it the way it is done in a serious paper. How do you begin it?","intent":"Begin the summary with \"El presente trabajo\" and say it focuses on memory in La Candelaria.","accept":["El presente trabajo se centra en la memoria de La Candelaria.","El presente trabajo trata de la memoria en La Candelaria.","El presente trabajo analiza la memoria del barrio de La Candelaria."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])(?:el presente trabajo)(?![\\p{L}])","flags":"iu","label":"begin with: El presente trabajo"}],"focus":"p:el-presente-trabajo","next":"t3"},{"id":"t3","npc":"Perfecto. El reglamento limita el texto a tres mil palabras. ¿Tiene alguna duda sobre eso?","npcEn":"Perfect. The rules limit the text to three thousand words. Do you have any doubt about that?","intent":"Ask whether the notes count in the word limit.","accept":["¿Las notas cuentan en el límite de palabras?","¿El límite incluye también las notas?","Sí, una duda: ¿se cuentan las notas dentro del límite?"],"require":[{"type":"question","label":"ask a question"},{"type":"regex","pattern":"(?<![\\p{L}])(?:notas)(?![\\p{L}])","flags":"iu","label":"ask about the notes"}],"focus":"g:questions","next":"t4"},{"id":"t4","npc":"Cuentan, sí. Y dígame, ¿qué planes tiene para el texto después del concurso?","npcEn":"They count, yes. And tell me, what plans do you have for the text after the competition?","intent":"Say that in the short term you want to read it aloud, but in the long run you want to publish it (use: a corto plazo and a largo plazo).","accept":["A corto plazo quiero leerlo en voz alta, y a largo plazo publicarlo.","A corto plazo, leerlo en público; a largo plazo, convertirlo en libro.","Quiero leerlo a corto plazo y, a largo plazo, publicarlo."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])(?:a corto plazo)(?![\\p{L}])","flags":"iu","label":"use: a corto plazo"},{"type":"regex","pattern":"(?<![\\p{L}])(?:a largo plazo|a la larga)(?![\\p{L}])","flags":"iu","label":"use: a largo plazo"}],"focus":"p:plazos","next":"t5"},{"id":"t5","npc":"Aquí tiene su comprobante. Mucha suerte, joven.","npcEn":"Here is your receipt. Good luck, young man.","intent":"Thank her and say goodbye, politely.","accept":["Muchas gracias, señora. Que tenga buena tarde.","Gracias por su ayuda. Hasta luego.","Se lo agradezco mucho. Hasta pronto."],"require":[{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"next":null}],"r":["g:commands-usted","g:commands-with-pronouns","g:gender-articles","g:present-ar","g:questions","g:stem-boot","p:el-presente-trabajo","p:plazos"],"d":126,"spare":true},
{"id":"sc-u56-g","unit":"u56","band":"C1","title":"La caja del baúl","brief":"You're Tomás, in the attic of the café with your cousin Yesid, who has found a box of Rosa's letters, none of them posted. He's family, so use tú. Tell him what you think, and why it matters to your essay.","turns":[{"id":"t1","npc":"Yesid: Primo, encontré una caja con cartas de la abuela. Ninguna tiene sello. ¿Por qué crees que nunca las envió?","npcEn":"Yesid: Cousin, I found a box of Grandma's letters. None of them has a stamp. Why do you think she never sent them?","intent":"Say that her silence has its roots in fear (use: tener su raíz en).","accept":["Creo que ese silencio tiene su raíz en el miedo.","Su silencio tiene su raíz en el miedo a que la leyeran.","Para mí, todo tiene su raíz en el miedo."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])(?:tiene su raíz en|tienen su raíz en|tenía su raíz en)(?![\\p{L}])","flags":"iu","label":"use: tener su raíz en"}],"focus":"p:tener-su-raiz-en","next":"t2"},{"id":"t2","npc":"Yesid: ¿Y tu ensayo? ¿De dónde salió la idea?","npcEn":"Yesid: And your essay? Where did the idea come from?","intent":"Say the essay came out of these letters (use: surgir de).","accept":["El ensayo surgió de estas cartas.","La idea surgió de las cartas que escribió la abuela.","Todo surgió de esta caja, primo."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])(?:surgió de|surgieron de|surge de|surgen de)(?![\\p{L}])","flags":"iu","label":"use: surgir de"}],"focus":"p:surgir-de","next":"t3"},{"id":"t3","npc":"Yesid: Mira esta: dice que la calle es suya porque la recuerda. ¡Qué atrevida!","npcEn":"Yesid: Look at this one: it says the street is hers because she remembers it. How bold!","intent":"Say that is so typical of Grandma (use: propio de).","accept":["Eso es muy propio de la abuela.","Es muy propio de ella decir algo así.","Qué cosa tan propia de la abuela, ¿no?"],"require":[{"type":"regex","pattern":"(?<![\\p{L}])(?:propio de|propia de)(?![\\p{L}])","flags":"iu","label":"use: propio de"}],"focus":"p:propio-de","next":"t4"},{"id":"t4","npc":"Yesid: ¿Tú crees que a la abuela le habría gustado ganar un premio?","npcEn":"Yesid: Do you think Grandma would have liked to win a prize?","intent":"Say without a doubt she would have liked it (use: sin lugar a dudas).","accept":["Sin lugar a dudas, le habría gustado.","Sin lugar a dudas, se habría reído de orgullo.","Le habría gustado, sin lugar a dudas."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])(?:sin lugar a dudas)(?![\\p{L}])","flags":"iu","label":"use: sin lugar a dudas"}],"focus":"c:sin-lugar-a-dudas","next":"t5"},{"id":"t5","npc":"Yesid: Entonces lee una de estas cartas en voz alta el día del concurso. ¿Trato?","npcEn":"Yesid: Then read one of these letters aloud on the day of the competition. Deal?","intent":"Agree to the deal, as a family member.","accept":["Trato hecho, primo.","Trato. La leo al final del ensayo.","Sí, trato hecho. Gracias, Yesid."],"require":[{"type":"avoidsAny","words":["usted","ustedes"],"label":"use tú with a friend, not usted"}],"next":null}],"r":["c:sin-lugar-a-dudas","g:direct-objects","g:gender-articles","g:present-er-ir","g:stem-boot","g:that-clauses","p:propio-de","p:surgir-de","p:tener-su-raiz-en"],"d":652,"spare":true},
{"id":"sc-u56-h","unit":"u56","band":"C1","title":"La placa de Lucía","brief":"You're Tomás, at the door of Doña Lucía's bakery. She is an older neighbour who wants a plaque for the street, and she speaks warmly but firmly. Use usted. Help her think through what the plaque would mean.","turns":[{"id":"t1","npc":"Mijo, quiero una placa en la esquina que diga: «Aquí vivió la memoria del barrio». Pero me dicen que una placa no cambia nada. ¿Usted qué opina?","npcEn":"Dear, I want a plaque on the corner that says: \"The memory of the neighbourhood lived here\". But they tell me a plaque changes nothing. What do you think?","intent":"Say she has a point, but a plaque starts the conversation (use: no le falta razón).","accept":["No le falta razón, doña Lucía, pero una placa empieza la conversación.","No le falta razón; aun así, la placa abre la conversación.","Algo de razón tiene, pero una placa es un comienzo."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])(?:no le falta razón|algo de razón tiene)(?![\\p{L}])","flags":"iu","label":"use: no le falta razón"},{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"focus":"p:no-te-falta-razon","next":"t2"},{"id":"t2","npc":"Una placa es solo un pedazo de metal. ¿Qué puede lograr?","npcEn":"A plaque is only a piece of metal. What can it achieve?","intent":"Say that a plaque can give rise to conversations (use: dar lugar a).","accept":["Puede dar lugar a muchas conversaciones entre los vecinos.","Una placa da lugar a preguntas, y las preguntas dan lugar a recuerdos.","Puede dar lugar a una buena discusión en el barrio."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])(?:dar lugar a|da lugar a|dan lugar a|dará lugar a|darán lugar a|daría lugar a)(?![\\p{L}])","flags":"iu","label":"use: dar lugar a"}],"focus":"p:dar-lugar-a","next":"t3"},{"id":"t3","npc":"Hecha la placa, ¿quién paga la instalación?","npcEn":"Once the plaque is made, who pays for the installation?","intent":"Say that once the budget is approved, the cooperative will pay (use: una vez + participle).","accept":["Una vez aprobado el presupuesto, la cooperativa la paga.","Una vez aprobado el gasto, pagará la cooperativa.","Aprobado el presupuesto, la cooperativa se encarga de pagarla."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])(?:una vez \\p{L}+(?:ado|ada|ido|ida|to|ta|so|sa|cho|cha)|aprobad[oa]|terminad[oa])(?![\\p{L}])","flags":"iu","label":"use a participle clause: una vez aprobado"}],"focus":"g:absolute-constructions","next":"t4"},{"id":"t4","npc":"Dicen que la gente valora tarde lo que tiene. ¿Es cierto?","npcEn":"They say people value late what they have. Is it true?","intent":"Say that, as a rule, people value what they have lost (use: por lo general).","accept":["Por lo general, la gente valora lo que ya ha perdido.","Por lo general sí, doña Lucía, solo valoramos lo que perdimos.","En general, valoramos las cosas cuando ya no están."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])(?:por lo general|por regla general|en general)(?![\\p{L}])","flags":"iu","label":"use: por lo general"}],"focus":"p:por-lo-general","next":"t5"},{"id":"t5","npc":"Pues pase mañana por la panadería. Le regalo un pan de yuca para el camino.","npcEn":"Well, drop by the bakery tomorrow. I will give you a cheese bread for the road.","intent":"Thank her warmly and say you will go, politely.","accept":["Muchas gracias, doña Lucía. Mañana paso sin falta.","Con mucho gusto, señora. Muchas gracias.","Qué amable. Mañana voy a verla."],"require":[{"type":"avoidsPerson","person":"tú","label":"use usted, not tú"}],"next":null}],"r":["g:absolute-constructions","g:gender-articles","g:present-ar","g:questions","g:ser-identity","g:stem-boot","g:stem-e-i","g:that-clauses","p:dar-lugar-a","p:no-te-falta-razon","p:por-lo-general"],"d":632,"spare":true},
{"id":"sc-u56-i","unit":"u56","band":"C1","title":"En vivo desde la radio","brief":"You're Tomás, live on a morning radio show after winning second prize. The host is warm and informal, so use tú. Answer in clear spoken sentences and keep your answers short.","turns":[{"id":"t1","npc":"Estamos en vivo con Tomás, segundo premio del concurso. Tomás, ¿qué sentiste cuando te dieron la noticia?","npcEn":"We are live with Tomás, second prize in the competition. Tomás, what did you feel when they gave you the news?","intent":"Say that you did not expect it, in the past.","accept":["No lo esperaba. Casi no voy a la lectura.","No esperaba nada, de verdad. Me quedé sin palabras.","No me lo esperaba para nada, fue una sorpresa enorme."],"require":[{"type":"negation","label":"say you did not expect it"},{"type":"anyVerbInTense","tense":"imperfecto","label":"use the past: esperaba"}],"focus":"g:imperfect-forms","next":"t2"},{"id":"t2","npc":"Tu ensayo habla de progreso y olvido. Dime, ¿qué es una pesadilla urbana para ti?","npcEn":"Your essay talks about progress and forgetting. Tell me, what is an urban nightmare for you?","intent":"Say that an urban nightmare is a city where nobody remembers who lived there (use: pesadilla).","accept":["Una pesadilla urbana es una ciudad donde nadie recuerda quién vivió allí.","Para mí, la pesadilla es una ciudad sin memoria.","Mi pesadilla es una calle donde nadie sabe quién vivía allí."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])(?:pesadilla)(?![\\p{L}])","flags":"iu","label":"use: pesadilla"}],"focus":"l:pesadilla","next":"t3"},{"id":"t3","npc":"Un oyente dice que tu ensayo es demasiado pesimista. ¿Qué le contestas?","npcEn":"A listener says your essay is too pessimistic. What do you answer?","intent":"Answer him: although it is true that things are bad, we must not forget that there is hope (use: si bien es cierto que ... no olvidemos que).","accept":["Si bien es cierto que hay problemas, no olvidemos que el barrio también tiene esperanza.","Si bien es cierto que el panorama es difícil, no olvidemos que todavía hay tiempo.","Si bien es cierto que perdimos mucho, no olvidemos que aún podemos cuidar lo que queda."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])(?:si bien es cierto que)(?![\\p{L}])","flags":"iu","label":"use: si bien es cierto que"},{"type":"regex","pattern":"(?<![\\p{L}])(?:no olvidemos que|no hay que olvidar que)(?![\\p{L}])","flags":"iu","label":"use: no olvidemos que"}],"focus":"p:si-bien-no-olvidemos","next":"t4"},{"id":"t4","npc":"Última pregunta: ¿qué consejo le das a quien quiere escribir sobre su ciudad?","npcEn":"Last question: what advice do you give to someone who wants to write about their city?","intent":"Give your advice, starting with \"a mi juicio\" and saying to begin with one street.","accept":["A mi juicio, hay que empezar por una sola calle.","A mi juicio, lo mejor es empezar por una calle que uno conozca bien.","A mi juicio, se empieza con una calle y se termina con la ciudad."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])(?:a mi juicio|a mi entender)(?![\\p{L}])","flags":"iu","label":"start with: a mi juicio"}],"focus":"p:a-mi-juicio","next":"t5"},{"id":"t5","npc":"Gracias, Tomás, y felicidades. Saluda a Hernando de nuestra parte.","npcEn":"Thank you, Tomás, and congratulations. Say hello to Hernando on our behalf.","intent":"Thank her and promise to pass on the greeting, as a friend.","accept":["Gracias a ti. Le doy tu saludo a Hernando hoy mismo.","Muchas gracias. Yo le doy el saludo.","Gracias por invitarme, yo le paso el saludo."],"require":[{"type":"avoidsAny","words":["usted","ustedes"],"label":"use tú with a friend, not usted"}],"next":null}],"r":["g:gender-articles","g:indirect-objects","g:present-ar","g:questions","g:ser-identity","l:pesadilla","p:a-mi-juicio","p:si-bien-no-olvidemos"],"d":119,"spare":true},
{"id":"sc-u57-a","unit":"u57","band":"C1","title":"Madrugada con Vale","brief":"You're Tomás. Vale has just heard about Hernando and phones you from Medellín in the middle of the night. She's your friend, so use tú. Say how you feel, own up to a regret and tell her what happens next at the café.","turns":[{"id":"t1","npc":"Vale: Tomás, soy yo. Me acabo de enterar de lo que pasó con Hernando. ¿Cómo estás?","npcEn":"Vale: Tomás, it's me. I just heard what happened to Hernando. How are you?","intent":"Say that it hurts you deep inside (use: se me parte el alma or se me hizo un nudo en la garganta).","accept":["Se me hizo un nudo en la garganta, Vale.","Gracias por llamar. Se me parte el alma, Vale.","Mal. Se me hizo un nudo en la garganta cuando me contaron."],"require":[{"type":"regex","pattern":"\\bse me (parte|partió|hizo|hace)\\b","flags":"iu","label":"use: se me parte / se me hizo"}],"focus":"p:se-me-body","next":"t2"},{"id":"t2","npc":"Vale: Y el libro sale esta semana. Parece mentira, ¿no?","npcEn":"Vale: And the book comes out this week. Hard to believe, isn't it?","intent":"Say it surprises you that he managed to finish it (use: me sorprende que + subjunctive).","accept":["Me sorprende que lo terminara antes de morir.","A mí me sorprende que alcanzara a terminarlo.","Sí, me sorprende que Hernando lo acabara a tiempo."],"require":[{"type":"regex","pattern":"\\bme sorprende que\\b","flags":"iu","label":"use: me sorprende que"},{"type":"subjunctiveAfter","trigger":"me sorprende que","within":8}],"focus":"p:me-sorprende-me-sorprendo","next":"t3"},{"id":"t3","npc":"Vale: Yo ni siquiera me despedí de él. ¿Y tú?","npcEn":"Vale: I didn't even say goodbye to him. And you?","intent":"Say that you regret something you did or didn't do (use: me arrepiento de + haber + participle).","accept":["Me arrepiento de haberle dejado ganar tantas partidas.","Yo me arrepiento de no haberlo visitado más el último mes.","Me arrepiento de no haberle dicho cuánto lo quería."],"require":[{"type":"regex","pattern":"\\bme arrepiento de (no )?haber\\w*\\b","flags":"iu","label":"use: me arrepiento de (no) haber..."}],"focus":"p:arrepentirse-de-haber","next":"t4"},{"id":"t4","npc":"Vale: ¿Vamos a tener que cerrar el café mañana?","npcEn":"Vale: Are we going to have to close the café tomorrow?","intent":"Say yes: there is no choice but to close for a day (use: toca + infinitive).","accept":["Toca cerrar mañana y abrir el jueves.","Sí, toca cerrar un solo día.","Pues toca cerrar, Vale."],"require":[{"type":"regex","pattern":"\\btoca \\w+","flags":"iu","label":"use: toca + infinitive"}],"focus":"p:no-queda-de-otra","next":"t5"},{"id":"t5","npc":"Vale: Ya compré el tiquete. Llego mañana por la noche, con pandebonos.","npcEn":"Vale: I've already bought the ticket. I get in tomorrow night, with pandebonos.","intent":"Tell her it was about time she came back (use: ya era hora de que + imperfect subjunctive).","accept":["Ya era hora de que volvieras, Vale.","¡Ya era hora de que vinieras a visitarnos!","Ya era hora de que regresaras a casa."],"require":[{"type":"regex","pattern":"\\bya era hora de que\\b","flags":"iu","label":"use: ya era hora de que"},{"type":"subjunctiveAfter","trigger":"ya era hora de que","within":8}],"focus":"p:ya-era-hora-de-que","next":"t6"},{"id":"t6","npc":"Vale: Intenta dormir un poco esta noche, ¿de acuerdo?","npcEn":"Vale: Try to sleep a little tonight, all right?","intent":"Say that however hard you try, you won't sleep (use: por mucho que + subjunctive), and say goodbye.","accept":["Por mucho que lo intente, no voy a dormir. Hasta mañana, Vale.","Por mucho que me acueste temprano, hoy no duermo. Buenas noches.","Por mucho que quiera dormir, no puedo. Nos vemos mañana."],"require":[{"type":"regex","pattern":"\\bpor mucho que\\b","flags":"iu","label":"use: por mucho que"},{"type":"subjunctiveAfter","trigger":"por mucho que","within":8}],"focus":"g:concessive-advanced","next":null}],"r":["g:concessive-advanced","g:gender-articles","g:present-ar","g:preterite-ar","p:arrepentirse-de-haber","p:me-sorprende-me-sorprendo","p:no-queda-de-otra","p:se-me-body","p:ya-era-hora-de-que"],"d":585},
{"id":"sc-u57-b","unit":"u57","band":"C1","title":"Una nota para el periódico","brief":"You're Tomás, in the café with Mariana the journalist. She's your age and a friend, so use tú. She is writing Hernando's obituary and needs your help with the details, a few honest answers and a way to finish.","turns":[{"id":"t1","npc":"Mariana: Llevo una hora sin saber cómo empezar la nota sobre Hernando. ¿Tú pudiste escribir algo para el funeral?","npcEn":"Mariana: I've spent an hour not knowing how to start the piece on Hernando. Were you able to write something for the funeral?","intent":"Say you racked your brains over it (use: me rompí la cabeza).","accept":["Me rompí la cabeza toda la noche y solo salieron tres líneas.","Me rompí la cabeza, pero no logré escribir nada bueno.","Sí, me rompí la cabeza tres horas para escribir una página."],"require":[{"type":"regex","pattern":"\\bme (rompí|quebré) la cabeza\\b","flags":"iu","label":"use: me rompí la cabeza"}],"focus":"p:romperse-la-cabeza","next":"t2"},{"id":"t2","npc":"Mariana: En su último cuaderno, Hernando cuenta que tú perdías a propósito. ¿Él lo sabía?","npcEn":"Mariana: In his last notebook, Hernando says you lost on purpose. Did he know?","intent":"Say you only realised when you read his notebook that he had always known (use: caí en cuenta de que).","accept":["Hasta que leí esa página no caí en cuenta de que él lo sabía.","Caí en cuenta de que lo sabía desde el principio cuando leí el cuaderno.","Ayer caí en cuenta de que él siempre lo supo."],"require":[{"type":"regex","pattern":"\\bca[ií] en (la )?cuenta\\b","flags":"iu","label":"use: caí en cuenta"}],"focus":"p:caer-en-cuenta","next":"t3"},{"id":"t3","npc":"Mariana: Todos nos preguntamos qué habría pasado si hubiéramos hecho algo distinto.","npcEn":"Mariana: We all wonder what would have happened if we had done something different.","intent":"Wonder aloud, as a question, what if you had done something that night (use: ¿Y si + hubiera or hubiéramos + participle?).","accept":["¿Y si lo hubiera llamado esa noche?","¿Y si hubiéramos jugado una última partida?","¿Y si lo hubiéramos acompañado hasta su casa?"],"require":[{"type":"regex","pattern":"\\by si (lo |le |nos |me )?hub(iera|iéramos|ieramos)\\b","flags":"iu","label":"use: ¿y si hubiera / hubiéramos...?"},{"type":"question"}],"focus":"p:y-si-hubieramos","next":"t4"},{"id":"t4","npc":"Mariana: No sé si poner la anécdota de las partidas en la nota. ¿Tú qué prefieres?","npcEn":"Mariana: I don't know whether to put the story about the games in the piece. What do you prefer?","intent":"Tell her that if she wants it in, she should put it in; it doesn't bother you (use: si quieres...).","accept":["Si quieres incluir la anécdota, inclúyela. A mí no me molesta.","Si quieres que salgan las partidas, que salgan; él lo habría querido.","Si quieres ponerla, ponla. Por mí no hay problema."],"require":[{"type":"regex","pattern":"\\bsi quieres\\b","flags":"iu","label":"use: si quieres..."}],"focus":"p:si-quieres-que","next":"t5"},{"id":"t5","npc":"Mariana: Última pregunta, para cerrar la nota: ¿qué le dirías a Hernando si lo tuvieras delante?","npcEn":"Mariana: Last question, to close the piece: what would you say to Hernando if you had him in front of you?","intent":"Say what you would tell or ask him if he were here (use: si + imperfect subjunctive, then the conditional).","accept":["Si lo tuviera delante, le diría que el libro quedó muy bueno.","Si pudiera hablar con él, le pediría una última partida.","Si estuviera aquí, le daría las gracias por todo."],"require":[{"type":"subjunctiveAfter","trigger":"si","within":8},{"type":"anyVerbInTense","tense":"condicional","label":"use the conditional (diría, pediría, daría)"}],"focus":"g:conditional-advanced","next":"t6"},{"id":"t6","npc":"Mariana: Gracias, Tomás. Con esto la nota queda completa. ¿Te traigo un tinto?","npcEn":"Mariana: Thanks, Tomás. With this the piece is complete. Shall I bring you a black coffee?","intent":"Thank her, say yes to the coffee and say you're worn out (use: estoy molido).","accept":["Gracias, Mariana. Un tinto me vendría bien, que estoy molido.","Sí, gracias. Un tinto, por favor. Estoy molido.","Gracias a ti. Sí, tráeme un tinto, que estoy molido."],"require":[{"type":"containsAny","words":["gracias"],"label":"say thanks"},{"type":"regex","pattern":"\\bmolid[oa]\\b","flags":"iu","label":"use: estoy molido"}],"focus":"c:estoy-molido","next":null}],"r":["c:estoy-molido","g:conditional-advanced","g:direct-objects","g:gender-articles","g:indirect-questions","g:present-ar","g:questions","g:si-hypothetical","g:stem-boot","g:yo-irregular","p:caer-en-cuenta","p:romperse-la-cabeza","p:si-quieres-que","p:y-si-hubieramos"],"d":581},
{"id":"sc-u57-c","unit":"u57","band":"C1","title":"Los trescientos carros","brief":"You're Tomás, behind the counter the morning after the funeral. An old taxi driver who worked beside Hernando for thirty years comes in. He's much older than you, so use usted. Talk about the noise, the crowd, the phone that won't stop and why you're staying.","turns":[{"id":"t1","npc":"Un taxista: Perdone, joven. Yo manejé al lado de Hernando treinta años. ¿Cómo lleva usted lo de ayer?","npcEn":"A taxi driver: Excuse me, young man. I drove beside Hernando for thirty years. How are you taking what happened yesterday?","intent":"Say the noise of the cars stayed engraved in your memory (use: se me quedó grabado).","accept":["Ese sonido se me quedó grabado para siempre.","Se me quedó grabado el ruido de todos esos carros.","Le confieso que se me quedó grabado el ruido de los carros."],"require":[{"type":"regex","pattern":"\\bse me (ha )?qued[oó] grabad[oa]s?\\b","flags":"iu","label":"use: se me quedó grabado"}],"focus":"p:quedar-grabado","next":"t2"},{"id":"t2","npc":"Un taxista: Éramos trescientos carros. Él nunca quiso tanto ruido, pero ya ve.","npcEn":"A taxi driver: There were three hundred cars. He never wanted that much noise, but there you are.","intent":"Say you're not surprised that so many came (use: no me extraña que + subjunctive).","accept":["No me extraña que hayan venido tantos. Él ayudaba a todos.","No me extraña que vinieran trescientos. Lo querían muchísimo.","No me extraña que todo el barrio saliera a verlos pasar."],"require":[{"type":"regex","pattern":"\\bno me extra[ñn]a que\\b","flags":"iu","label":"use: no me extraña que"},{"type":"subjunctiveAfter","trigger":"no me extraña que","within":8}],"focus":"p:no-me-extrana-que","next":"t3"},{"id":"t3","npc":"Un taxista: Y ese hotel de Altamira mandó flores otra vez. Yo ya estoy hasta la coronilla de esa gente.","npcEn":"A taxi driver: And that Altamira hotel sent flowers again. I'm sick to death of those people.","intent":"Say you are fed up too (use: estoy hasta la coronilla de).","accept":["Yo también estoy hasta la coronilla de sus flores.","Estoy hasta la coronilla de que me llamen a toda hora.","Pues yo estoy hasta la coronilla de sus regalos."],"require":[{"type":"regex","pattern":"\\bestoy hasta la coronilla de\\b","flags":"iu","label":"use: estoy hasta la coronilla de"}],"focus":"p:hasta-la-coronilla","next":"t4"},{"id":"t4","npc":"Un taxista: ¿Y usted por qué sigue aquí, joven? ¿Por la plata del café?","npcEn":"A taxi driver: And why are you still here, young man? For the money from the café?","intent":"Say you're not staying for one reason but for another (use: no ... porque ..., sino porque ...).","accept":["No me quedo porque el café dé plata, sino porque aquí está mi familia.","No me quedo porque sea fácil, sino porque se lo prometí a Hernando.","No sigo aquí porque necesite la plata, sino porque este café es de todos."],"require":[{"type":"regex","pattern":"\\bno\\b.*\\bporque\\b.*\\bsino porque\\b","flags":"iu","label":"use: no ... porque ..., sino porque ..."},{"type":"subjunctiveAfter","trigger":"porque","within":3}],"focus":"p:no-porque-sino-porque","next":"t5"},{"id":"t5","npc":"Un taxista: Y ese teléfono no para de sonar. Periodistas, la editorial, el hotel. ¿Qué les digo si vuelven a llamar?","npcEn":"A taxi driver: And that phone won't stop ringing. Journalists, the publisher, the hotel. What do I tell them if they call again?","intent":"Tell him (formally) to say you're in no mood for anyone today (use: no estoy para).","accept":["Dígales que hoy no estoy para nadie.","Dígales que no estoy para negociaciones.","Mejor dígales que hoy no estoy para llamadas."],"require":[{"type":"regex","pattern":"\\bno estoy para\\b","flags":"iu","label":"use: no estoy para"}],"focus":"p:no-estar-para","next":"t6"},{"id":"t6","npc":"Un taxista: Su abuela Rosa estaría orgullosa. Bueno, me voy; mi carro no se maneja solo.","npcEn":"A taxi driver: Your grandmother Rosa would be proud. Well, I'm off; my car won't drive itself.","intent":"Thank him and offer condolences for his friend (use the chunk: mi más sentido pésame).","accept":["Gracias por venir. Mi más sentido pésame por su amigo.","Muchas gracias, de verdad. Le doy mi más sentido pésame.","Gracias a usted. Mi más sentido pésame, y vuelva cuando quiera."],"require":[{"type":"regex","pattern":"\\bsentido p[eé]same\\b","flags":"iu","label":"use: mi más sentido pésame"}],"focus":"c:mi-mas-sentido-pesame","next":null}],"r":["c:mi-mas-sentido-pesame","g:demonstratives","g:estar-location-states","g:gender-articles","g:present-ar","g:preterite-ar","g:questions","p:hasta-la-coronilla","p:no-estar-para","p:no-me-extrana-que","p:no-porque-sino-porque","p:quedar-grabado"],"d":634,"spare":true},
{"id":"sc-u57-d","unit":"u57","band":"C1","title":"El tablero","brief":"You're Tomás, closing the café with Vale after the longest day. She's your friend, so use tú. She has found Hernando's chess board with the last game still on it, and Simón keeps squawking. Say what you feel, honestly and with some humour.","turns":[{"id":"t1","npc":"Vale: Encontré el tablero en el estante. Las fichas siguen en la posición de la última partida.","npcEn":"Vale: I found the board on the shelf. The pieces are still in the position of the last game.","intent":"Say you feel like packing it all away (use: estoy por + infinitive).","accept":["Estoy por guardarlo todo en una caja y no verlo más.","Estoy por dejarlo así, tal cual lo dejó él.","Estoy por llorar otra vez, la verdad."],"require":[{"type":"regex","pattern":"\\bestoy por \\w+","flags":"iu","label":"use: estoy por + infinitive"}],"focus":"p:estar-por","next":"t2"},{"id":"t2","npc":"Vale: Tú perdías a propósito, ¿verdad? Él lo sabía desde la primera partida.","npcEn":"Vale: You lost on purpose, didn't you? He knew from the first game.","intent":"Admit it, and say that if you had known, you would have played seriously (use: de haber + participle, then habría + participle).","accept":["De haberlo sabido, habría jugado en serio desde la primera partida.","De haber sabido que lo notaba, le habría ganado al menos una vez.","De haberlo sabido, no habría perdido a propósito ni una sola vez."],"require":[{"type":"regex","pattern":"\\bde haber(lo|le|me)? \\w+","flags":"iu","label":"use: de haber + participle"},{"type":"regex","pattern":"\\bhabr[ií]a\\w* \\w+","flags":"iu","label":"use: habría + participle"}],"focus":"g:conditional-advanced","next":"t3"},{"id":"t3","npc":"Vale: Cuanto más lo pienso, menos entiendo cómo se fue así, sin avisar.","npcEn":"Vale: The more I think about it, the less I understand how he left like that, without warning.","intent":"Answer with your own sentence of the type: the more ..., the more / less ... (use: cuanto más).","accept":["Cuanto más lo pienso, más rabia me da.","Cuanto más lo recuerdo, menos quiero guardar el tablero.","Cuanto más tiempo pasa, más falta me hace."],"require":[{"type":"regex","pattern":"\\bcuanto m[aá]s\\b.*\\b(m[aá]s|menos)\\b","flags":"iu","label":"use: cuanto más ..., más / menos ..."}],"focus":"g:comparative-advanced-c1","next":"t4"},{"id":"t4","npc":"Vale: Mañana a las siete llegan los obreros. Dime que no tengo que madrugar a recibirlos.","npcEn":"Vale: The builders arrive tomorrow at seven. Tell me I don't have to get up early to let them in.","intent":"Tell her she'd better rest and you'll deal with them (use: más vale que + subjunctive).","accept":["Más vale que descanses; yo los recibo.","Más vale que duermas hasta tarde. Yo me ocupo de ellos.","Más vale que no madrugues. Yo les abro."],"require":[{"type":"regex","pattern":"\\bm[aá]s vale que\\b","flags":"iu","label":"use: más vale que"},{"type":"subjunctiveAfter","trigger":"más vale que","within":8}],"focus":"g:comparative-advanced-c1","next":"t5"},{"id":"t5","npc":"Vale: Mira a Simón. Desde ayer no para de gritar: «¡Eso sí que no!».","npcEn":"Vale: Look at Simón. Since yesterday he hasn't stopped shouting: \"Absolutely not!\".","intent":"Joke that he acts as if he understood what he says (use: ni que + imperfect subjunctive).","accept":["¡Ni que entendiera lo que dice!","Ni que fuera un filósofo, el loro.","¡Ni que Simón supiera lo que dice!"],"require":[{"type":"regex","pattern":"\\bni que\\b","flags":"iu","label":"use: ni que + imperfect subjunctive"}],"focus":"g:comparative-advanced-c1","next":"t6"},{"id":"t6","npc":"Vale: ¿Con qué te quedas de todo esto?","npcEn":"Vale: What do you keep from all of this?","intent":"Say you settle for one good thing (use: me conformo con).","accept":["Me conformo con saber que el libro llegó a tiempo.","Me conformo con haberlo conocido, aunque fuera poco tiempo.","Me conformo con que haya visto la primera página impresa."],"require":[{"type":"regex","pattern":"\\bme conformo con\\b","flags":"iu","label":"use: me conformo con"}],"focus":"p:conformarse-con","next":null}],"r":["g:comparative-advanced-c1","g:conditional-advanced","g:direct-objects","g:gender-articles","g:present-ar","p:conformarse-con","p:estar-por"],"d":575,"spare":true},
{"id":"sc-u57-e","unit":"u57","band":"C1","title":"La maleta de Vale","brief":"You're Tomás. At dawn Vale turns up at the café door with her suitcase and says she isn't going back to Medellín. She's your friend, so use tú. Marvel at it, share what hit you, ask for time on her request and finish with a toast to luck.","turns":[{"id":"t1","npc":"Vale: No pongas esa cara. Traje mi maleta y no pienso llevármela de vuelta.","npcEn":"Vale: Don't make that face. I brought my suitcase and I don't plan to take it back.","intent":"Say it seems unbelievable that she is staying after so many years (use: parece mentira que + subjunctive).","accept":["Parece mentira que te quedes después de tantos años en Medellín.","Parece mentira que por fin vayas a quedarte.","Parece mentira que vuelvas justo ahora."],"require":[{"type":"regex","pattern":"\\bparece mentira que\\b","flags":"iu","label":"use: parece mentira que"},{"type":"subjunctiveAfter","trigger":"parece mentira que","within":8}],"focus":"p:parece-mentira-que","next":"t2"},{"id":"t2","npc":"Vale: Allá tengo un trabajo, un apartamento y un gato. Pero aquí tengo esto.","npcEn":"Vale: Over there I have a job, an apartment and a cat. But here I have this.","intent":"Say how you envy her courage to start over (use: ¡Quién tuviera / pudiera ...!).","accept":["¡Quién tuviera tu valor para empezar de cero!","¡Quién pudiera dejarlo todo como tú!","¡Quién tuviera tu valentía para decidir tan rápido!"],"require":[{"type":"regex","pattern":"\\bqui[eé]n (tuviera|pudiera)\\b","flags":"iu","label":"use: ¡quién tuviera / pudiera...!"}],"focus":"p:quien-tuviera","next":"t3"},{"id":"t3","npc":"Vale: ¿Y si no sale bien? ¿Y si el café no da para los dos?","npcEn":"Vale: And what if it doesn't work out? What if the café doesn't earn enough for both of us?","intent":"Reassure her: say you are crossing your fingers (use: cruzo los dedos para que + subjunctive).","accept":["Cruzo los dedos para que todo salga bien.","Cruzo los dedos para que el café funcione.","Yo cruzo los dedos para que nos vaya bien."],"require":[{"type":"regex","pattern":"\\bcruzo los dedos\\b","flags":"iu","label":"use: cruzo los dedos"},{"type":"subjunctiveAfter","trigger":"para que","within":3}],"focus":"c:cruzo-los-dedos","next":"t4"},{"id":"t4","npc":"Vale: Anoche me entró un miedo horrible. Pensé: ¿y si me arrepiento?","npcEn":"Vale: Last night a horrible fear came over me. I thought: what if I regret it?","intent":"Say that a wave of sadness or an urge to cry hit you too (use: me entró / me entraron).","accept":["A mí me entraron ganas de llorar en el entierro.","A mí también me entró una pena enorme cuando pasaron los carros.","A mí me entró una tristeza enorme al ver el tablero."],"require":[{"type":"regex","pattern":"\\bme entr(ó|o|aron)","flags":"iu","label":"use: me entró / me entraron"}],"focus":"p:entrarle-algo","next":"t5"},{"id":"t5","npc":"Vale: ¿Me dejas vivir en el cuarto de arriba mientras busco apartamento?","npcEn":"Vale: Will you let me live in the room upstairs while I look for an apartment?","intent":"Say you need to sleep on it (use: Déjame consultarlo con la almohada).","accept":["Déjame consultarlo con la almohada, pero creo que sí.","Claro que sí, pero déjame consultarlo con la almohada primero.","Déjame consultarlo con la almohada, aunque ya sabes mi respuesta."],"require":[{"type":"regex","pattern":"\\bconsultarlo con la almohada\\b","flags":"iu","label":"use: consultarlo con la almohada"}],"focus":"c:consultarlo-con-la-almohada","next":"t6"},{"id":"t6","npc":"Vale: Entonces abramos. Para la gente del barrio, este café es el pan de cada día.","npcEn":"Vale: Then let's open. For the people of the neighbourhood, this café is part of everyday life.","intent":"Say let's go for it, and that whatever happens, happens (use: Hágale and que sea lo que Dios quiera).","accept":["¡Hágale, pues! Y que sea lo que Dios quiera.","Hágale. Ya hicimos todo lo que pudimos; que sea lo que Dios quiera.","¡Hágale! Que sea lo que Dios quiera."],"require":[{"type":"regex","pattern":"\\bh[aá]gale\\b","flags":"iu","label":"use: hágale"},{"type":"regex","pattern":"\\bque sea lo que dios quiera\\b","flags":"iu","label":"use: que sea lo que Dios quiera"}],"focus":"c:hagale","next":null}],"r":["c:consultarlo-con-la-almohada","c:cruzo-los-dedos","c:hagale","g:gender-articles","g:present-ar","g:reflexive-routine","g:si-present","g:stem-boot","p:entrarle-algo","p:parece-mentira-que","p:quien-tuviera"],"d":581,"spare":true},
{"id":"sc-u57-f","unit":"u57","band":"C1","title":"Treinta cajas de memorias","brief":"You're Tomás, at the print shop to collect the books of Hernando's memoir. The clerk is a polite stranger and older than you, so use usted. Sort out a printing error, a bill and the heavy boxes, with some grace.","turns":[{"id":"t1","npc":"El empleado: Buenos días. Aquí tiene el pedido de las memorias de don Hernando. Lamento mucho su pérdida.","npcEn":"The clerk: Good morning. Here is the order of Don Hernando's memoirs. I'm very sorry for your loss.","intent":"Thank him and say that although it's a sad day, it's a relief to have the books on time (use: si bien).","accept":["Gracias. Si bien es un día triste, es un alivio tener los libros a tiempo.","Si bien me duele que no esté, me alegra que los libros lleguen hoy.","Gracias, de verdad. Si bien no es fácil, hoy es un buen día para el libro."],"require":[{"type":"regex","pattern":"\\bsi bien\\b","flags":"iu","label":"use: si bien"}],"focus":"g:concessive-advanced","next":"t2"},{"id":"t2","npc":"El empleado: La portada quedó con un error: la fecha es del año pasado. Reimprimirla cuesta el doble y tarda una semana.","npcEn":"The clerk: The cover has a mistake: the date is from last year. Reprinting it costs double and takes a week.","intent":"Say you can't wait a week, so you'll take them as they are (use: de manera que, por consiguiente or así pues).","accept":["No puedo esperar una semana, de manera que me los llevo así.","El libro tiene que salir hoy; por consiguiente, me los llevo con ese error.","No hay tiempo. Así pues, me llevo los libros tal como están."],"require":[{"type":"regex","pattern":"\\b(de manera que|de modo que|así pues|por consiguiente|de ahí que)\\b","flags":"iu","label":"use: de manera que / por consiguiente / así pues"}],"focus":"g:consecutive-advanced","next":"t3"},{"id":"t3","npc":"El empleado: Si me permite una pregunta: con todo esto, ¿el café va a salir adelante?","npcEn":"The clerk: If you'll allow me a question: with all this, will the café pull through?","intent":"Say that with a lot of effort it will pull through (use: salir adelante).","accept":["Con mucho esfuerzo, el café va a salir adelante.","Entre todos vamos a salir adelante, como siempre.","Vamos a salir adelante, aunque cueste."],"require":[{"type":"regex","pattern":"\\bsal(ir|imos|dr[aá]|dremos|ió|ieron|ga|gamos)\\w* adelante\\b","flags":"iu","label":"use: salir adelante"}],"focus":"p:salir-adelante","next":"t4"},{"id":"t4","npc":"El empleado: Mire, me da cargo de conciencia cobrarle hoy, justo ahora.","npcEn":"The clerk: Look, I feel guilty charging you today, right now.","intent":"Tell him not to feel bad: if he doesn't charge you, Hernando will scold you (use: como no + subjunctive).","accept":["No se sienta mal. Como no le pague hoy, Hernando me regaña.","Cóbreme sin pena. Como no lo haga, Hernando me regaña desde donde esté.","Cóbreme, por favor. Como no pague hoy, don Hernando me regaña."],"require":[{"type":"regex","pattern":"\\bcomo no\\b","flags":"iu","label":"use: como no + subjunctive"},{"type":"subjunctiveAfter","trigger":"como no","within":8}],"focus":"g:conditional-advanced","next":"t5"},{"id":"t5","npc":"El empleado: Una pregunta más: ¿podrá usted leer el primer capítulo mañana sin quebrarse?","npcEn":"The clerk: One more question: will you be able to read the first chapter tomorrow without breaking down?","intent":"Say you'll try to stay calm (use: conservar la calma, mantener la calma or aguantar).","accept":["Voy a intentar conservar la calma, pero no prometo nada.","Voy a aguantar hasta el final, aunque me cueste.","Voy a mantener la calma lo mejor que pueda."],"require":[{"type":"regex","pattern":"\\b(calma|aguant\\w+)\\b","flags":"iu","label":"use: calma / aguantar"}],"focus":"p:aguantar-conservar-la-calma","next":"t6"},{"id":"t6","npc":"El empleado: Son treinta cajas. ¿Se las cargo yo solo hasta el taxi?","npcEn":"The clerk: It's thirty boxes. Shall I carry them all by myself to the taxi?","intent":"Refuse with the chunk ¡Eso sí que no! and offer to help.","accept":["¡Eso sí que no! Las cargamos entre los dos.","Eso sí que no, déjeme ayudarle. Y gracias por todo.","¡Eso sí que no! Yo llevo la mitad."],"require":[{"type":"regex","pattern":"\\beso s[ií] que no\\b","flags":"iu","label":"use: ¡eso sí que no!"}],"focus":"c:eso-si-que-no","next":null}],"r":["c:eso-si-que-no","g:concessive-advanced","g:conditional-advanced","g:consecutive-advanced","g:gender-articles","g:object-pronoun-position","g:present-ar","g:ser-identity","g:stem-boot","p:aguantar-conservar-la-calma","p:salir-adelante"],"d":null,"spare":true},
{"id":"sc-u58-a","unit":"u58","band":"C1","title":"El fotógrafo perdido","brief":"You're Tomás. The photographer hired for the cooperative's newsletter is lost near the café and phones you. He's about your age, so use tú. Guide him in, then tell him how the restoration will go.","turns":[{"id":"t1","npc":"Fotógrafo: ¿Aló, Tomás? Estoy en la carrera séptima y no veo el café por ningún lado. ¿Dónde queda exactamente?","npcEn":"Photographer: Hello, Tomás? I'm on Seventh Avenue and I can't see the café anywhere. Where exactly is it?","intent":"Tell him you're two blocks from where he is, level with 12th Street (use: a ... cuadras de, a la altura de).","accept":["Estamos a dos cuadras de donde estás, a la altura de la calle 12.","El café queda a dos cuadras, a la altura de la calle 12.","Sigue derecho: el café está a la altura de la calle 12, a dos cuadras de la carrera séptima."],"require":[{"type":"regex","pattern":"\\ba (\\S+ ){1,2}cuadras?\\b","flags":"iu","label":"use: a ... cuadras"},{"type":"regex","pattern":"\\ba la altura de\\b","flags":"iu","label":"use: a la altura de"}],"focus":"p:a-cuadras-de","next":"t2"},{"id":"t2","npc":"Fotógrafo: Ya lo veo. ¡Qué fachada! Oye, ¿qué fue lo primero que hicieron cuando empezó la obra?","npcEn":"Photographer: I can see it now. What a facade! Tell me, what was the first thing you did when the work started?","intent":"Say that as soon as the workers arrived, they took down the old beam (use: nada más llegar).","accept":["Nada más llegar los obreros, bajaron la viga vieja.","Los obreros bajaron la viga vieja nada más llegar, el lunes.","Nada más llegar, los obreros empezaron a bajar la viga vieja."],"require":[{"type":"regex","pattern":"\\b(nada más|apenas|en cuanto|tan pronto como)\\b","flags":"iu","label":"use: nada más + infinitive"}],"focus":"g:temporal-advanced","next":"t3"},{"id":"t3","npc":"Fotógrafo: Perfecto. Y los vecinos, ¿qué opinan de tanta obra?","npcEn":"Photographer: Perfect. And the neighbours, what do they think of so much building work?","intent":"Say that most of the neighbours support the work (use: la mayoría de los vecinos).","accept":["La mayoría de los vecinos apoya la obra.","La mayoría de los vecinos está de acuerdo, aunque algunos dudan.","La mayoría de los vecinos nos apoyan, sobre todo los mayores."],"require":[{"type":"regex","pattern":"\\bla mayoría de (los|las) \\S+","flags":"iu","label":"use: la mayoría de los vecinos"}],"focus":"g:agreement-tricky","next":"t4"},{"id":"t4","npc":"Fotógrafo: Me alegro. ¿Y cómo va a cambiar el café? Para la foto de portada necesito una idea.","npcEn":"Photographer: Glad to hear it. And how will the café change? I need an idea for the cover photo.","intent":"Say the café will look more like Rosa's as the work advances (use: a medida que).","accept":["A medida que avance la obra, el café se parecerá más al de Rosa.","El café recuperará su aspecto de antes a medida que avancen las obras.","Se irá pareciendo al café de Rosa a medida que quiten el polvo."],"require":[{"type":"regex","pattern":"\\ba medida que\\b","flags":"iu","label":"use: a medida que"}],"focus":"g:temporal-advanced","next":"t5"},{"id":"t5","npc":"Fotógrafo: Genial, ya tengo mi imagen. Muchas gracias por la ayuda con la dirección.","npcEn":"Photographer: Great, I've got my picture. Thank you for the help with the directions.","intent":"Say it was nothing and offer him a black coffee before he leaves (a question).","accept":["No hay de qué. ¿Quieres un tinto antes de irte?","Gracias a ti. ¿Te sirvo un tinto antes de que te vayas?","Con gusto. ¿Por qué no te quedas a tomar un tinto?"],"require":[{"type":"question"}],"focus":"g:temporal-advanced","next":null}],"r":["g:agreement-tricky","g:gender-articles","g:present-ar","g:questions","g:temporal-advanced","g:yo-irregular","p:a-cuadras-de"],"d":null},
{"id":"sc-u58-b","unit":"u58","band":"C1","title":"Un banco con placa","brief":"You're Tomás, sitting with doña Gloria on the new bench outside the café. She's the cooperative's president and much older than you, so use usted throughout. Answer her questions about the bench, Jhon Fredy and the weather, then offer her a coffee.","turns":[{"id":"t1","npc":"Gloria: Buenos días, Tomás. Un turista me preguntó de qué es este banco y no supe qué decirle. ¿De qué es?","npcEn":"Gloria: Good morning, Tomás. A tourist asked me what this bench is made of and I didn't know what to tell him. What is it made of?","intent":"Say it is made of comino, the wood of the old beam (use: es de).","accept":["Es de comino, doña Gloria, la madera de la viga vieja.","El banco es de comino. Es la madera de la viga vieja.","Es de comino, la misma madera que tuvo la casa durante cien años."],"require":[{"type":"regex","pattern":"\\bes de\\b","flags":"iu","label":"use: es de + material"}],"focus":"g:ser-estar-c1","next":"t2"},{"id":"t2","npc":"Gloria: ¿Y Jhon Fredy? Hoy no lo vi en la cocina. ¿Ya no trabaja aquí?","npcEn":"Gloria: And Jhon Fredy? I didn't see him in the kitchen today. Doesn't he work here any more?","intent":"Say he does: this week he's working as a waiter in the dining room (use: está de).","accept":["Claro que sí, doña Gloria. Esta semana está de mesero en el salón.","Sigue con nosotros: esta semana está de mesero.","Sí, trabaja aquí. Ahora está de mesero, por eso no está en la cocina."],"require":[{"type":"regex","pattern":"\\bestá de\\b","flags":"iu","label":"use: está de + job"}],"focus":"g:ser-estar-c1","next":"t3"},{"id":"t3","npc":"Gloria: Ay, el cielo está muy oscuro. ¿Usted cree que llueva?","npcEn":"Gloria: Oh, the sky is very dark. Do you think it'll rain?","intent":"Say yes, it's about to rain (use: está por llover).","accept":["Creo que sí, doña Gloria. Está por llover.","Sí, está por llover desde hace rato.","Está por llover. Mejor entre y siéntese adentro."],"require":[{"type":"regex","pattern":"\\b(por|para) llover\\b","flags":"iu","label":"use: está por llover"}],"focus":"g:ser-estar-c1","next":"t4"},{"id":"t4","npc":"Gloria: ¿Y Altamira? ¿Usted cree que ahora sí nos deje en paz?","npcEn":"Gloria: And Altamira? Do you think they'll leave us alone now?","intent":"Say that remains to be seen (use: está por verse).","accept":["Eso está por verse, doña Gloria.","Está por verse si nos dejan en paz.","Todavía está por verse, pero no vamos a ceder."],"require":[{"type":"regex","pattern":"\\bpor verse\\b","flags":"iu","label":"use: está por verse"}],"focus":"g:ser-estar-c1","next":"t5"},{"id":"t5","npc":"Gloria: Bueno, hoy estoy un poco cansada. ¿Me puedo quedar un rato en el banco de Hernando?","npcEn":"Gloria: Well, I'm a little tired today. Can I stay a while on Hernando's bench?","intent":"Tell her of course, the bench is for everyone, and offer her a black coffee (a question, in usted).","accept":["Claro que sí, el banco es de todos. ¿Le sirvo un tinto?","Por supuesto, doña Gloria. ¿Quiere un tinto mientras tanto?","Quédese tranquila, que para eso está. ¿Le traigo un tinto?"],"require":[{"type":"question"},{"type":"avoidsAny","words":["eres","tienes","quieres"],"label":"use usted, not tú"}],"focus":"g:ser-estar-c1","next":null}],"r":["g:estar-location-states","g:gender-articles","g:present-er-ir","g:ser-estar-c1","g:subj-opinion-negated","g:subj-wanting","g:that-clauses"],"d":556},
{"id":"sc-u58-c","unit":"u58","band":"C1","title":"Detrás de la rocola","brief":"You're Tomás, with Vale in the kitchen the day before the newsletter goes out. She's quick and dry, and you're friends, so use tú. Describe the restoration for the newsletter, then deal with a surprise.","turns":[{"id":"t1","npc":"Vale: Oye, el informe sale el viernes. ¿Cómo describes el piso original?","npcEn":"Vale: Hey, the report goes out on Friday. How do you describe the original floor?","intent":"Describe how the tiles feel (use: al tacto).","accept":["Las baldosas son frías al tacto, y las flores tienen relieve.","Al tacto son lisas donde están gastadas.","Son ásperas al tacto, como una moneda vieja."],"require":[{"type":"regex","pattern":"\\bal tacto\\b","flags":"iu","label":"use: al tacto"}],"focus":"p:al-tacto","next":"t2"},{"id":"t2","npc":"Vale: ¿Y cuánto mide el salón? Dame un cálculo, no hace falta una cinta.","npcEn":"Vale: And how big is the room? Give me an estimate, no tape measure needed.","intent":"Say that by eye it's about ten metres long (use: al ojo).","accept":["Al ojo, mide unos diez metros de largo.","Medido al ojo, tendrá diez metros, más o menos.","Yo diría que al ojo son diez metros."],"require":[{"type":"regex","pattern":"\\bal ojo\\b","flags":"iu","label":"use: al ojo"}],"focus":"p:a-ojo","next":"t3"},{"id":"t3","npc":"Vale: ¿A qué hora empiezan los obreros mañana?","npcEn":"Vale: What time do the workers start tomorrow?","intent":"Say they arrive at about seven (use: a eso de).","accept":["Llegan a eso de las siete.","Empiezan a eso de las siete, antes del calor.","A eso de las siete, según el ingeniero."],"require":[{"type":"regex","pattern":"\\ba eso de\\b","flags":"iu","label":"use: a eso de + hora"}],"focus":"p:a-eso-de","next":"t4"},{"id":"t4","npc":"Vale: ¿Y la ventana de la cocina? ¿Da a la calle o al patio?","npcEn":"Vale: And the kitchen window? Does it look onto the street or the courtyard?","intent":"Say it looks onto the courtyard (use: da a / da al).","accept":["Da al patio interior.","La ventana de la cocina da al patio, no a la calle.","Da al patio, donde está el árbol de Simón."],"require":[{"type":"regex","pattern":"\\bda (a|al)\\b","flags":"iu","label":"use: da a / da al"}],"focus":"p:dar-a","next":"t5"},{"id":"t5","npc":"Vale: ¿Y los vecinos? ¿Qué dijeron de los planos?","npcEn":"Vale: And the neighbours? What did they say about the plans?","intent":"Say most of the neighbours signed as soon as they saw the plans (use: la mayoría de, nada más ver).","accept":["La mayoría de los vecinos firmó nada más ver los planos.","La mayoría de los vecinos dijo que sí; nada más verlos, firmaron.","La mayoría de los vecinos firmaron nada más ver los planos."],"require":[{"type":"regex","pattern":"\\bla mayoría de (los|las) \\S+","flags":"iu","label":"use: la mayoría de los vecinos"},{"type":"regex","pattern":"\\bnada más\\b","flags":"iu","label":"use: nada más + infinitive"}],"focus":"g:agreement-tricky","next":"t6"},{"id":"t6","npc":"Vale: Mira lo que encontré detrás de la rocola: una caja con los discos que Rosa escondió. ¡Hay como cincuenta!","npcEn":"Vale: Look what I found behind the jukebox: a box with the records Rosa hid. There are about fifty!","intent":"React: say that now her music is within everyone's reach (use: al alcance de).","accept":["¡Qué maravilla! Ahora esa música está al alcance de todos.","Ahora los discos de Rosa están al alcance de cualquiera.","Ponlos en la barra, al alcance de la mano."],"require":[{"type":"regex","pattern":"\\bal alcance de\\b","flags":"iu","label":"use: al alcance de"}],"focus":"p:al-alcance-de","next":null}],"r":["g:agreement-tricky","g:gender-articles","g:present-er-ir","g:questions","p:a-eso-de","p:a-ojo","p:al-alcance-de","p:al-tacto","p:dar-a"],"d":null,"spare":true},
{"id":"sc-u59-a","unit":"u59","band":"C1","title":"Ruta al Carnaval","brief":"You're Tomás on the phone with Vale, who is planning the trip to Barranquilla for Carnaval. She's a close friend your age, so use tú. React to the plan, haggle a little, and say thank you.","turns":[{"id":"t1","npc":"Vale: Tomás, ¿supiste lo de Barranquilla? La familia de Yesid nos espera para el Carnaval.","npcEn":"Vale: Tomás, did you hear about Barranquilla? Yesid's family is expecting us for Carnaval.","intent":"Say yes, you heard about the Barranquilla trip, and ask what the plan is (use: lo de).","accept":["Sí, supe lo de Barranquilla. ¿Cuál es el plan?","Claro, me contó Yesid lo de la invitación. ¿Cómo lo organizamos?","Sí, ya supe lo de Barranquilla. ¿Qué vamos a hacer?"],"require":[{"type":"regex","pattern":"(?<![\\p{L}])lo de(?![\\p{L}])","flags":"iu","label":"use: lo de + noun"}],"focus":"p:lo-de-noun","next":"t2"},{"id":"t2","npc":"Vale: Salimos el viernes. Lo más recomendable es volar, aunque en Carnaval eso cuesta un platal.","npcEn":"Vale: We leave on Friday. The best thing is to fly, although during Carnaval that costs a fortune.","intent":"Agree to fly, as long as you buy the tickets today (use: sí, pero que... or siempre que...).","accept":["Sí, pero que compremos los tiquetes hoy mismo.","Está bien, volamos, siempre que los compremos hoy.","De acuerdo, pero que los tiquetes los compremos hoy, por favor."],"require":[{"type":"avoidsAny","words":["pero porque"],"label":"after pero, que opens the condition"},{"type":"regex","pattern":"(?<![\\p{L}])(pero que|siempre que)(?![\\p{L}])","flags":"iu","label":"use: pero que / siempre que"}],"focus":"p:si-pero-que","next":"t3"},{"id":"t3","npc":"Vale: Gloria dice que viene, y la mayoría de la cuadra también. ¿Quién va a llevar las maletas?","npcEn":"Vale: Gloria says she's coming, and so is most of the block. Who is going to carry the suitcases?","intent":"Say that the majority of the group is bringing their own, and you'll help whoever needs it (use: la mayoría de ... + singular verb).","accept":["La mayoría del grupo lleva sus maletas, y yo ayudo a quien lo necesite.","La mayoría de los vecinos trae su maleta. Yo llevo la mía y la de Gloria.","Creo que la mayoría de la gente lleva la suya. Yo ayudo con lo que haga falta."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])la mayor[ií]a del?(?![\\p{L}])","flags":"iu","label":"use: la mayoría de ... + verb"}],"focus":"g:agreement-tricky","next":"t4"},{"id":"t4","npc":"Vale: Qué bueno. Ah, y disculpa que te lo diga tan tarde: Yesid dice que su mamá cocina para veinte. ¿Tú eres bueno para comer?","npcEn":"Vale: Great. Oh, and sorry to tell you so late: Yesid says his mother cooks for twenty. Are you a big eater?","intent":"Say you're not a big eater, but you're ready to try everything (use ser or estar).","accept":["Todavía no soy muy bueno para comer, pero estoy listo para probarlo todo.","No soy tan bueno para comer, pero ese día voy a estar con mucha hambre.","Ni idea, pero estoy listo y con mucha hambre."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])(soy|estoy)(?![\\p{L}])","flags":"iu","label":"use ser or estar"}],"focus":"g:ser-estar-c1","next":"t5"},{"id":"t5","npc":"Vale: Ja, ja. Entonces nos vemos el viernes en el aeropuerto. Y no llegues a la hora colombiana.","npcEn":"Vale: Ha ha. Then we'll see each other Friday at the airport. And don't show up on Colombian time.","intent":"Promise you'll be on time and say thanks for organizing everything.","accept":["Prometido, llego temprano. Gracias por organizarlo todo.","Ahí estaré a tiempo. Mil gracias por todo, Vale.","Sin falta, a las siete. Gracias por encargarte de todo."],"require":[{"type":"containsAny","words":["gracias"],"label":"say thanks"}],"focus":"c:la-hora-colombiana","next":null}],"r":["c:la-hora-colombiana","g:agreement-tricky","g:gender-articles","g:present-ar","g:ser-estar-c1","g:ser-identity","g:stem-e-i","g:that-clauses","p:lo-de-noun","p:si-pero-que"],"d":null},
{"id":"sc-u59-b","unit":"u59","band":"C1","title":"Una invitación a Boyacá","brief":"You're Tomás at the café with doña Gloria, who is courtly and much older than you, so use usted throughout. She asks about Medellín, then invites you to her cousin's ninetieth birthday lunch. Decline politely and stay warm.","turns":[{"id":"t1","npc":"Gloria: Buenos días, Tomás. Lo extrañamos por aquí. ¿Cómo le fue en Medellín?","npcEn":"Gloria: Good morning, Tomás. We missed you here. How did it go for you in Medellín?","intent":"Say it went very well, and that people there use the voseo (use: voseo).","accept":["Muy bien, doña Gloria. Allá se usa mucho el voseo.","Me fue muy bien. Lo curioso es que en Medellín todos usan el voseo.","Bien, gracias. Aprendí a reconocer el voseo de la gente de allá."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])voseo(?![\\p{L}])","flags":"iu","label":"mention the voseo"}],"focus":"g:voseo-recognition","next":"t2"},{"id":"t2","npc":"Gloria: Ah, el voseo. Dígame una cosa: ¿el voseo es lo mismo que el tuteo, o cambia el significado?","npcEn":"Gloria: Ah, the voseo. Tell me something: is the voseo the same as the tuteo, or does the meaning change?","intent":"Say it's the same thing, only the pronoun and the verb endings change (use: es lo mismo).","accept":["Es lo mismo, doña Gloria. Solo cambian el pronombre y las terminaciones.","No cambia el significado, es lo mismo. Solo cambia la forma del verbo.","Sí, quiere decir lo mismo. Solo cambia la manera de decir los verbos."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])(lo mismo|no cambia el significado)(?![\\p{L}])","flags":"iu","label":"say it is the same"}],"focus":"g:voseo-recognition","next":"t3"},{"id":"t3","npc":"Gloria: Bueno, le tengo una propuesta. Un primo mío cumple noventa años el domingo y hace un almuerzo en Chía. ¿Nos acompaña?","npcEn":"Gloria: Well, I have a proposal for you. A cousin of mine turns ninety on Sunday and is having a lunch in Chía. Will you come with us?","intent":"Decline politely: you're sorry, but you can't that day (use: sintiéndolo mucho or me temo que).","accept":["Sintiéndolo mucho, no puedo ese día, doña Gloria.","Me temo que no voy a poder el domingo. Tengo que abrir el café.","Sintiéndolo mucho, no va a ser posible ir el domingo."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])(sinti[eé]ndolo mucho|me temo que)(?![\\p{L}])","flags":"iu","label":"use: sintiéndolo mucho / me temo que"}],"focus":"p:sintiendolo-mucho","next":"t4"},{"id":"t4","npc":"Gloria: No me diga que no, mijo. Verá que la pasa bien, y mi primo cocina muy rico.","npcEn":"Gloria: Don't tell me no, son. You'll see you have a good time, and my cousin cooks very well.","intent":"Insist politely: whatever he says, you have to open the café that day (use: diga lo que diga).","accept":["Diga lo que diga, doña Gloria, ese día tengo que abrir el café.","Haga lo que haga, no puedo dejar el café solo el domingo.","Diga lo que diga, no voy a poder, pero gracias por pensar en mí."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])(diga lo que diga|haga lo que haga|se ponga como se ponga)(?![\\p{L}])","flags":"iu","label":"use: diga lo que diga"}],"focus":"p:digas-lo-que-digas","next":"t5"},{"id":"t5","npc":"Gloria: Bueno, allá usted. Pero que conste que hay ajiaco.","npcEn":"Gloria: Well, that's up to you. But for the record, there's ajiaco.","intent":"Thank her, and ask her to give your best wishes to her cousin (use: ¿me hace el favor...?).","accept":["Gracias, doña Gloria. ¿Me hace el favor y le manda un saludo a su primo?","Se lo agradezco mucho. ¿Me hace el favor de saludar a su primo de mi parte?","Qué pena con usted. ¿Me hace el favor y le dice feliz cumpleaños de mi parte?"],"require":[{"type":"regex","pattern":"(?<![\\p{L}])me hace el favor(?![\\p{L}])","flags":"iu","label":"use: ¿me hace el favor...?"},{"type":"avoidsAny","words":["haces","tu primo"],"label":"use usted, not tú"}],"focus":"p:me-hace-el-favor","next":null}],"r":["g:direct-objects","g:gender-articles","g:indirect-objects","g:present-ar","g:that-clauses","g:voseo-recognition","p:digas-lo-que-digas","p:me-hace-el-favor","p:sintiendolo-mucho"],"d":null},
{"id":"sc-u59-c","unit":"u59","band":"C1","title":"La nota de Mariana","brief":"You're Tomás, and your friend Mariana, a journalist, is interviewing you for a piece on the voices of Colombia. She's your age, so use tú. Describe what you've noticed, talk about how you change your register, and have a laugh.","turns":[{"id":"t1","npc":"Mariana: Para mi nota sobre las voces de Colombia: ¿qué notaste primero cuando llegaste a Bogotá?","npcEn":"Mariana: For my piece on the voices of Colombia: what did you notice first when you arrived in Bogotá?","intent":"Say the rolos speak calmly and politely (use: son or hablan).","accept":["Los rolos hablan con calma y son muy amables.","Me pareció que los rolos son tranquilos y muy educados al hablar.","Lo primero fue que los rolos hablan despacio y con mucha cortesía."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])rolos?(?![\\p{L}])","flags":"iu","label":"mention los rolos"}],"focus":"g:ser-estar-c1","next":"t2"},{"id":"t2","npc":"Mariana: ¿Y los costeños? En el Carnaval vas a conocer a la familia de Yesid.","npcEn":"Mariana: And the costeños? At Carnaval you'll meet Yesid's family.","intent":"Say they speak fast, they are very cheerful, and you hope to understand them.","accept":["Dicen que los costeños hablan rápido y son muy alegres. Espero entenderlos.","Los costeños hablan rápido y son muy alegres, según Yesid. Ojalá los entienda.","Los costeños hablan rápido y son alegres. Espero entenderlos bien."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])coste[ñn]os?(?![\\p{L}])","flags":"iu","label":"mention los costeños"}],"focus":"g:agreement-tricky","next":"t3"},{"id":"t3","npc":"Mariana: ¿Y cómo cambias tu forma de hablar según con quién estás?","npcEn":"Mariana: And how do you change the way you speak depending on who you're with?","intent":"Explain that you say usted to older people and tú to friends.","accept":["Con los mayores uso usted, y con mis amigos uso tú.","A doña Gloria le digo usted, pero a ti te digo tú.","Les digo usted a los mayores y tú a los amigos."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])usted(?![\\p{L}])","flags":"iu","label":"mention usted"},{"type":"regex","pattern":"(?<![\\p{L}])t[uú](?![\\p{L}])","flags":"iu","label":"mention tú"}],"focus":"g:ser-estar-c1","next":"t4"},{"id":"t4","npc":"Mariana: Gloria dice que eres todero. Pero también dijo que tienes manos de mantequilla, ¿o fue Vale?","npcEn":"Mariana: Gloria says you're a jack of all trades. But she also said you have butterfingers, or was it Vale?","intent":"Laugh and say you are no jack of all trades: you drop everything, so it was probably both of them.","accept":["Ja, ja. Yo no soy todero, se me cae todo. Seguro dijeron los dos.","No soy todero, tengo manos de mantequilla. Seguramente fueron los dos.","Ja, ja. Todero, no. Se me cae todo, así que fueron Vale y Gloria."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])(no soy todero|todero, no|manos de mantequilla|se me cae)(?![\\p{L}])","flags":"iu","label":"say you are no todero"}],"focus":"c:manos-de-mantequilla","next":"t5"},{"id":"t5","npc":"Mariana: Perfecto, ya tengo mi nota. ¿Te invito un tinto para celebrar?","npcEn":"Mariana: Perfect, I have my piece. Shall I buy you a tinto to celebrate?","intent":"Accept warmly and thank her (try: no te voy a decir que no).","accept":["No te voy a decir que no. Gracias por invitarme.","Claro que sí, gracias. Pero la próxima vez invito yo.","Me animo, gracias. Con mucho gusto."],"require":[{"type":"containsAny","words":["gracias"],"label":"say thanks"}],"focus":"c:no-te-voy-a-decir-que-no","next":null}],"r":["c:manos-de-mantequilla","c:no-te-voy-a-decir-que-no","g:agreement-tricky","g:gender-articles","g:present-ar","g:questions","g:ser-estar-c1"],"d":null,"spare":true},
{"id":"sc-u59-d","unit":"u59","band":"C1","title":"La casa de doña Beatriz","brief":"You're Tomás arriving at Vale's family home in Medellín. Her mother, doña Beatriz, is warm but older than you, so use usted with her. Greet her, say how long you're staying, and charm her over a meal.","turns":[{"id":"t1","npc":"Doña Beatriz: Pase, pase, mijo, que está en su casa. Usted debe de ser Tomás.","npcEn":"Doña Beatriz: Come in, come in, son, make yourself at home. You must be Tomás.","intent":"Say yes, it's a pleasure, and apologise for arriving late (use: mil disculpas).","accept":["Sí, mucho gusto, doña Beatriz. Mil disculpas por llegar tarde.","Con mucho gusto. Mil disculpas por la demora, el vuelo se atrasó.","Tomás, para servirle. Mil disculpas por llegar tan tarde."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])mil disculpas(?![\\p{L}])","flags":"iu","label":"use: mil disculpas"}],"focus":"c:mil-disculpas","next":"t2"},{"id":"t2","npc":"Doña Beatriz: Vale me llama a cada rato para hablarme de usted. ¿Cuánto tiempo se queda?","npcEn":"Doña Beatriz: Vale calls me all the time to tell me about you. How long are you staying?","intent":"Say you're staying one week, and Vale also talks about her mother all the time (use: a cada rato).","accept":["Una semana. Vale también habla de usted a cada rato.","Me quedo una semana. Y Vale también me habla de usted a cada rato.","Una semana, si usted me aguanta. Vale habla de usted a cada rato."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])a cada rato(?![\\p{L}])","flags":"iu","label":"use: a cada rato"},{"type":"avoidsAny","words":["eres","tu mamá"],"label":"use usted"}],"focus":"c:a-cada-rato","next":"t3"},{"id":"t3","npc":"Doña Beatriz: Le preparé una bandeja grande. Coma, coma, que lo veo flaco.","npcEn":"Doña Beatriz: I made you a big platter. Eat, eat, because you look thin to me.","intent":"Say she shouldn't have gone to the trouble (use: no se hubiera molestado).","accept":["No se hubiera molestado, doña Beatriz. Todo se ve delicioso.","Ay, no se hubiera molestado tanto. Huele muy rico.","No se hubiera molestado, pero se lo agradezco mucho."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])no se hubiera molestado(?![\\p{L}])","flags":"iu","label":"use: no se hubiera molestado"}],"focus":"c:no-te-hubieras-molestado","next":"t4"},{"id":"t4","npc":"Doña Beatriz: ¿Le sirvo más? Allá en Bogotá nadie come así, ¿verdad?","npcEn":"Doña Beatriz: Shall I serve you more? Nobody eats like this in Bogotá, right?","intent":"Say yes please, you won't say no to a second helping, and it's better than at the café.","accept":["No le voy a decir que no. Está mejor que en el café.","Sí, por favor. Esto está mejor que lo que hacemos en el café.","Claro que sí, doña Beatriz, no le voy a decir que no."],"require":[{"type":"avoidsAny","words":["quieres","eres"],"label":"use usted"}],"focus":"c:no-te-voy-a-decir-que-no","next":"t5"},{"id":"t5","npc":"Doña Beatriz: Qué bueno. Esta noche Vale y sus primos lo llevan a bailar. ¿Se anima?","npcEn":"Doña Beatriz: Wonderful. Tonight Vale and her cousins are taking you out dancing. Are you up for it?","intent":"Say yes, you're up for it, though you're not a good dancer.","accept":["Me animo, aunque no soy buen bailarín.","Sí, claro. Eso sí, bailo muy mal.","Con mucho gusto, doña Beatriz, pero no sé bailar bien."],"require":[{"type":"containsAny","words":["animo","claro","gusto","sí"],"label":"say yes"}],"focus":"c:te-animas","next":null}],"r":["c:a-cada-rato","c:mil-disculpas","c:no-te-hubieras-molestado","c:no-te-voy-a-decir-que-no","c:te-animas","g:direct-objects","g:indirect-objects","g:present-ar","g:present-er-ir"],"d":625,"spare":true},
{"id":"sc-u59-e","unit":"u59","band":"C1","title":"Sumercé en la posada","brief":"You're Tomás in a village in Boyacá, at a small guesthouse. The owner, doña Etelvina, says sumercé to everyone and you're a stranger much younger than she is, so use usted. Ask for a room, ask about the word sumercé, and ask the way.","turns":[{"id":"t1","npc":"Doña Etelvina: Buenas tardes, sumercé. ¿En qué le puedo ayudar?","npcEn":"Doña Etelvina: Good afternoon, sumercé. How can I help you?","intent":"Greet her and ask whether she has a room for one night.","accept":["Buenas tardes. ¿Tiene una habitación para una noche?","Buenas tardes, señora. ¿Le queda una pieza libre para esta noche?","Buenas. ¿Tendrá una habitación para una noche, por favor?"],"require":[{"type":"question","label":"ask a question"},{"type":"avoidsAny","words":["tienes","eres"],"label":"use usted"}],"focus":"x:ser-estar-adj","next":"t2"},{"id":"t2","npc":"Doña Etelvina: Claro que sí. Son treinta mil pesos, pero para sumercé está regalado.","npcEn":"Doña Etelvina: Of course. It's thirty thousand pesos, but for you it's practically free.","intent":"Say thanks, that is very cheap, you'll take it (use: está regalado).","accept":["Gracias, señora. Está regalado, la tomo.","Qué amable. Eso está regalado, me la quedo.","Está regalado, doña Etelvina. Se la agradezco mucho."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])regalad[oa](?![\\p{L}])","flags":"iu","label":"use: está regalado"}],"focus":"p:estar-regalado","next":"t3"},{"id":"t3","npc":"Doña Etelvina: Y dígame, sumercé, ¿usted de dónde es?","npcEn":"Doña Etelvina: And tell me, sumercé, where are you from?","intent":"Say you're from Toronto but you live in Bogotá now (use: soy de and vivo en).","accept":["Soy de Toronto, pero ahora vivo en Bogotá.","Nací en Toronto, pero vivo en Bogotá desde hace un tiempo.","Soy canadiense, de Toronto. Ahora vivo en La Candelaria."],"require":[{"type":"regex","pattern":"(?<![\\p{L}])(soy|nac[ií])(?![\\p{L}])","flags":"iu","label":"say where you are from"}],"focus":"g:ser-estar-c1","next":"t4"},{"id":"t4","npc":"Doña Etelvina: Ah, de Canadá. Aquí todos decimos sumercé, no usted.","npcEn":"Doña Etelvina: Ah, from Canada. Here we all say sumercé, not usted.","intent":"Ask her what sumercé means exactly, and whether it's like usted. You can open with *disculpe que le pregunte*.","accept":["Disculpe que le pregunte, ¿qué quiere decir sumercé? ¿Es como usted?","Disculpe que le pregunte: ¿sumercé significa lo mismo que usted?","¿Sumercé es una forma de decir usted?"],"require":[{"type":"question","label":"ask a question"},{"type":"regex","pattern":"(?<![\\p{L}])sumerc[eé](?![\\p{L}])","flags":"iu","label":"mention sumercé"}],"focus":"p:disculpa-que","next":"t5"},{"id":"t5","npc":"Doña Etelvina: Más o menos, mijo. Es más cariñoso. Ahora descanse, que mañana madruga.","npcEn":"Doña Etelvina: More or less, son. It's warmer. Now rest, because tomorrow you get up early.","intent":"Thank her and say good night, and that you'll see her tomorrow.","accept":["Muchas gracias, doña Etelvina. Buenas noches y hasta mañana.","Gracias por todo. Que pase buenas noches, nos vemos mañana.","Se lo agradezco. Buenas noches, hasta mañana."],"require":[{"type":"containsAny","words":["gracias","agradezco"],"label":"say thanks"}],"next":null}],"r":["g:commands-usted","g:ser-estar-c1","g:ser-identity","p:disculpa-que","p:estar-regalado","x:ser-estar-adj"],"d":556,"spare":true},
{"id":"sc-u59-f","unit":"u59","band":"C1","title":"Versos y vallenatos","brief":"You're Tomás in a little shop in Barranquilla that sells poetry books and vallenato records. The owner is a costeño about your age and relaxed, so tú is fine. Ask for a recommendation, choose, and pay.","turns":[{"id":"t1","npc":"Dueño: ¿Qué más, mi llave? ¿Buscas algo en especial? Tengo poesía y discos de vallenato.","npcEn":"Owner: What's up, buddy? Are you looking for something in particular? I have poetry and vallenato records.","intent":"Say you'd like a book of poems by a Colombian poet, and ask what he recommends (use: lo más recomendable).","accept":["Quiero un libro de un poeta colombiano. ¿Qué es lo más recomendable?","Busco poesía colombiana. ¿Cuál es lo más recomendable para empezar?","Me gustaría un poemario. ¿Qué me recomiendas?"],"require":[{"type":"question","label":"ask what he recommends"}],"focus":"p:lo-mas-recomendable","next":"t2"},{"id":"t2","npc":"Dueño: Lo más recomendable es empezar por este. La literatura de aquí es emocionante, y la poesía más todavía.","npcEn":"Owner: The best thing is to start with this one. The literature from here is exciting, and the poetry even more so.","intent":"Say it looks great, and ask how much it costs.","accept":["Se ve genial. ¿Cuánto cuesta?","Qué bueno. ¿Cuánto vale este libro?","Me parece perfecto. ¿Cuánto es?"],"require":[{"type":"question","label":"ask the price"}],"focus":"g:agreement-tricky","next":"t3"},{"id":"t3","npc":"Dueño: Para ti, quince mil. Y si llevas el disco de cumbia, te lo dejo regalado.","npcEn":"Owner: For you, fifteen thousand. And if you take the cumbia record, I'll let you have it for nothing.","intent":"Say yes to both, but ask if it's better to start with cumbia or with vallenato.","accept":["Listo, llevo los dos. ¿Es mejor empezar con cumbia o con vallenato?","Sí, me animo. Pero ¿cuál es mejor para empezar, la cumbia o el vallenato?","De acuerdo. Dime, ¿empiezo por la cumbia o por el vallenato?"],"require":[{"type":"question","label":"ask a question"},{"type":"regex","pattern":"(?<![\\p{L}])(cumbia|vallenato)(?![\\p{L}])","flags":"iu","label":"mention the music"}],"focus":"p:si-pero-que","next":"t4"},{"id":"t4","npc":"Dueño: Si me hubieras dicho antes, te regalaba el bambuco también. Pero no importa, llévate esto.","npcEn":"Owner: If you had told me before, I'd have given you the bambuco as well. But never mind, take this.","intent":"Admit you should have told him earlier, and say that next time you will.","accept":["Tenía que haberte dicho antes. La próxima vez te aviso.","Es verdad, hubiera sido mejor decírtelo antes. La próxima vez vengo más temprano.","Qué pena, debí avisarte. Mil gracias por el regalo."],"require":[{"type":"containsAny","words":["próxima","antes","pena","gracias"],"label":"react warmly"}],"focus":"p:me-hubieras-dicho","next":"t5"},{"id":"t5","npc":"Dueño: Todo bien. Que disfrutes el Carnaval y que la poesía te acompañe.","npcEn":"Owner: All good. Enjoy the Carnaval and may the poetry keep you company.","intent":"Say thanks and goodbye, and that you'll come back.","accept":["Gracias por todo. Vuelvo pronto, hasta luego.","Mil gracias, hermano. Volveré antes de irme, hasta luego.","Muchas gracias. Nos vemos pronto, que te vaya bien."],"require":[{"type":"containsAny","words":["gracias"],"label":"say thanks"}],"next":null}],"r":["g:agreement-tricky","g:gender-articles","g:present-ar","p:lo-mas-recomendable","p:me-hubieras-dicho","p:si-pero-que"],"d":null,"spare":true},
{"id":"sc-u60-a","unit":"u60","band":"C1","title":"Un martes cualquiera","brief":"You're Tomás, on the morning the café reopens. Jaime, who has delivered the beans from Medellín for years, drops by. Use tú with him. Say what makes today different and invite him back.","turns":[{"id":"t1","npc":"Jaime: Buenas, Tomás. ¿Eres el nuevo dueño? Ojo, que este café era de doña Rosa.","npcEn":"Jaime: Morning, Tomás. Are you the new owner? Careful, this café was doña Rosa's.","intent":"Say yes, and that for you this is not just any café (use: un café cualquiera).","accept":["Sí, soy yo, y para mí este no es un café cualquiera.","Soy yo, sí. Pero no es un café cualquiera, era de mi abuela.","Sí, el dueño soy yo. Para mí no es un café cualquiera."],"require":[{"type":"regex","pattern":"\\bno es un caf[eé] cualquiera\\b","flags":"iu","label":"say it is not just any café: no es un café cualquiera"}],"focus":"p:un-x-cualquiera","next":"t2"},{"id":"t2","npc":"Jaime: Yo traigo el grano todos los martes y nunca pasa nada. Hoy parece un martes cualquiera.","npcEn":"Jaime: I bring the beans every Tuesday and nothing ever happens. Today looks like just any Tuesday.","intent":"Tell him that today is not an ordinary Tuesday, because the café reopens (use: un martes cualquiera).","accept":["Hoy no es un martes cualquiera: reabrimos el café.","Para nosotros no es un martes cualquiera, hoy abrimos otra vez.","No lo es, Jaime. Hoy no es un martes cualquiera, es el día de la reapertura."],"require":[{"type":"regex","pattern":"\\bun martes cualquiera\\b","flags":"iu","label":"use: un martes cualquiera"}],"focus":"p:un-x-cualquiera","next":"t3"},{"id":"t3","npc":"Jaime: Tienes razón. Yo paso por el barrio toda la semana. ¿Cuándo quieres que pase a probar el tinto?","npcEn":"Jaime: You're right. I pass through the neighbourhood all week. When do you want me to come by and try the black coffee?","intent":"Tell him to come by any day this week and that the coffee is on you (use: cualquier día).","accept":["Pasa cualquier día de esta semana, el tinto corre por mi cuenta.","Ven cualquier día y te invito un tinto.","Cualquier día me parece bien, Jaime. El tinto lo pago yo."],"require":[{"type":"regex","pattern":"\\bcualquier d[ií]a\\b","flags":"iu","label":"use: cualquier día (any day)"}],"focus":"x:cualquier-dia-un-dia-cualquiera","next":"t4"},{"id":"t4","npc":"Jaime: Como dicen los abogados: quien lo probare, volverá. ¡Hasta pronto, Tomás!","npcEn":"Jaime: As the lawyers say: whoever shall taste it will return. See you soon, Tomás!","intent":"Say goodbye and tell him you'll be waiting for him here.","accept":["Aquí te espero, Jaime. Hasta pronto.","Te esperamos aquí, Jaime. Que te vaya bien.","Hasta pronto, Jaime. Aquí estaré esperándote."],"require":[{"type":"regex","pattern":"\\b(esper)","flags":"iu","label":"say you will wait for him"}],"focus":"g:future-subj-recognition","next":null}],"r":["g:future-subj-recognition","g:gender-articles","g:present-ar","p:un-x-cualquiera","x:cualquier-dia-un-dia-cualquiera"],"d":null},
{"id":"sc-u60-b","unit":"u60","band":"C1","title":"La crítica del periódico","brief":"You're Tomás. A newspaper critic has reviewed the café with mixed words, and Vale reads you the worst lines. She is quick and dry; you're friends, so use tú. React, defend the café, and decide who writes the answer.","turns":[{"id":"t1","npc":"Vale: Salió la crítica en el periódico. Dice que el servicio deja mucho que desear. ¿Qué opinas?","npcEn":"Vale: The review came out in the paper. It says the service leaves a lot to be desired. What do you think?","intent":"Say the critic hit the nail on the head about the service (use: dar en el clavo).","accept":["Creo que la crítica dio en el clavo con lo del servicio.","Dio en el clavo, Vale: el sábado tardamos una hora.","Pues en esto la crítica dio en el clavo."],"require":[{"type":"regex","pattern":"\\bdi(o|eron) en el clavo\\b","flags":"iu","label":"use: dio en el clavo"}],"focus":"p:dar-en-el-clavo","next":"t2"},{"id":"t2","npc":"Vale: También escribe que la máquina de espresso no sirve para nada. ¡Mi máquina!","npcEn":"Vale: She also writes that the espresso machine is no use at all. My machine!","intent":"Defend the machine: say it works, and that the useless thing is the old fridge (use: no sirve para nada).","accept":["La máquina funciona bien. La que no sirve para nada es la nevera vieja.","Tu máquina es genial; la nevera es la que no sirve para nada.","Esa máquina funciona; lo que no sirve para nada es la nevera vieja."],"require":[{"type":"regex","pattern":"\\bno (sirve|valen?|sirven) para nada\\b","flags":"iu","label":"use: no sirve para nada"}],"focus":"p:no-servir-para-nada","next":"t3"},{"id":"t3","npc":"Vale: Y la última frase: «Un café con carácter, pero sin planificación». Dice que le gustó y que no le gustó.","npcEn":"Vale: And the last line: \"A café with character, but without planning.\" She says she liked it and she didn't.","intent":"Give your opinion of that, starting with resulta + adjective + que (for example: resulta absurdo que…).","accept":["Resulta curioso que le guste y no le guste a la vez.","Resulta injusto que hable de planificación sin conocer el barrio.","Resulta raro que una crítica tan famosa no sepa lo que piensa."],"require":[{"type":"regex","pattern":"\\bresulta (\\S+ ){1,2}que\\b","flags":"iu","label":"use: resulta + adjective + que"}],"focus":"p:resulta-adj-que","next":"t4"},{"id":"t4","npc":"Vale: Entonces, ¿qué le contestamos?","npcEn":"Vale: So what do we reply to him?","intent":"Answer with the emphasised word first, as in 'Poco importa el tono' (start with mucho, poco, difícil or fácil).","accept":["Poco importa el tono: lo que cuenta es mejorar.","Mucho hemos aprendido de esa crítica, y no nos molestamos.","Difícil es contestar sin perder la calma, pero lo intentaré."],"require":[{"type":"regex","pattern":"^\\W*(mucho|poco|dif[ií]cil|f[aá]cil)\\b","flags":"iu","label":"start with the emphasised word: mucho, poco, difícil or fácil"}],"focus":"g:word-order-style","next":"t5"},{"id":"t5","npc":"Vale: Listo, escríbela tú. Yo te traigo un tinto y me quedo a leerla, para que no escribas nada en caliente.","npcEn":"Vale: Fine, you write it. I'll bring you a black coffee and stay to read it, so you don't write anything in the heat of the moment.","intent":"Thank her, and tell her she's right to stay (use: haces bien en…).","accept":["Gracias, Vale. Haces bien en quedarte, yo solo me pongo dramático.","Haces bien en quedarte a leerla. Gracias por el tinto.","Gracias. Haces muy bien en quedarte, porque estoy de mal genio."],"require":[{"type":"regex","pattern":"\\bhaces (muy )?bien en\\b","flags":"iu","label":"use: haces bien en + infinitive"}],"focus":"p:haces-bien-en","next":null}],"r":["g:gender-articles","g:negation-words","g:present-ar","g:questions","g:stem-e-i","g:that-clauses","g:word-order-style","p:dar-en-el-clavo","p:haces-bien-en","p:no-servir-para-nada","p:resulta-adj-que"],"d":null},
{"id":"sc-u60-c","unit":"u60","band":"C1","title":"Lo que dice el loro","brief":"You're Tomás, late after closing. Mariana has read your draft reply to the critic and talks it over with you, then Vale asks the question you've been avoiding. Be honest in your own voice; Mariana and Vale are friends, so use tú.","turns":[{"id":"t1","npc":"Mariana: Leí tu respuesta al crítico. Es larga. ¿Cuál es la idea principal?","npcEn":"Mariana: I read your reply to the critic. It's long. What's the main idea?","intent":"Say the main idea, with an adverb that comments on your own sentence (use: sinceramente, francamente, sencillamente...).","accept":["Sinceramente, la idea es que el café es del barrio, no de un crítico.","La idea es, francamente, que este café pertenece al barrio.","Lo que digo, sencillamente, es que el café es de todos."],"require":[{"type":"regex","pattern":"\\b(sinceramente|francamente|sencillamente|lamentablemente|afortunadamente|honestamente|claramente)\\b","flags":"iu","label":"use an adverb like sinceramente or francamente"}],"focus":"g:evaluative-adverbs","next":"t2"},{"id":"t2","npc":"Mariana: ¿No te parece un poco duro el tono con el crítico?","npcEn":"Mariana: Don't you think the tone is a bit harsh on the critic?","intent":"Say no: you simply say what you think (use: sencillamente).","accept":["No, sencillamente digo lo que pienso.","Para nada, Mariana. Sencillamente escribo lo que pienso.","No es duro, es sencillamente sincero."],"require":[{"type":"regex","pattern":"\\bsencillamente\\b","flags":"iu","label":"use: sencillamente"}],"focus":"p:sencillamente","next":"t3"},{"id":"t3","npc":"Mariana: Bien. Y para terminar, ¿qué es lo mejor de tu café?","npcEn":"Mariana: Good. And to finish, what is the best thing about your café?","intent":"Say what the best thing is, using the verdict line (use: lo mejor de... es...).","accept":["Lo mejor del café es la gente que viene.","Lo mejor de este lugar es que todos se conocen.","Lo mejor de La Esquina de Rosa es el olor del pan por la mañana."],"require":[{"type":"regex","pattern":"\\blo mejor de(l| la| los| las| este| esta| mi| tu)? \\S+","flags":"iu","label":"use: lo mejor de... es..."}],"focus":"p:lo-mejor-de","next":"t4"},{"id":"t4","npc":"Vale: Tomás, ¿sigues aquí solo por unos meses?\nSimón: ¡Qué pena con usted!","npcEn":"Vale: Tomás, are you still only here for a few months?\nSimón: I'm so sorry!","intent":"Laugh and answer Vale with the emphasised word first, as in 'Difícil es decirlo'.","accept":["Difícil es decirlo, Vale. Hasta el loro lo sabe mejor que yo.","Poco sé todavía, la verdad. Mucho ha cambiado todo.","Difícil es contestar con el loro mirándome."],"require":[{"type":"regex","pattern":"^\\W*(mucho|poco|dif[ií]cil|f[aá]cil)\\b","flags":"iu","label":"start with the emphasised word: mucho, poco, difícil or fácil"}],"focus":"g:word-order-style","next":"t5"},{"id":"t5","npc":"Vale: Bueno, de momento sigues aquí. ¿Un tinto para celebrar la respuesta?","npcEn":"Vale: Well, for now you're still here. A black coffee to celebrate the reply?","intent":"Accept warmly and say, with an adverb, that you're happy to stay a while.","accept":["Claro que sí. Sinceramente, me alegra seguir aquí.","Con gusto. Por suerte, todavía no me voy.","Sí, por favor. Afortunadamente, me quedo un rato."],"require":[{"type":"regex","pattern":"\\b(sinceramente|francamente|por suerte|afortunadamente|felizmente|honestamente)\\b","flags":"iu","label":"use an adverb like sinceramente or por suerte"}],"focus":"g:evaluative-adverbs","next":null}],"r":["g:evaluative-adverbs","g:gender-articles","g:questions","g:ser-identity","g:stem-e-i","g:word-order-style","p:lo-mejor-de","p:sencillamente"],"d":null},
{"id":"sc-u60-d","unit":"u60","band":"C1","title":"Los versos de doña Cecilia","brief":"You're Tomás. Doña Cecilia, a retired teacher from the block, has put her poetry book on the counter next to Hernando's and asks for your honest opinion. She is courtly and much older, so use usted. Praise what works, name what doesn't, and thank her.","turns":[{"id":"t1","npc":"Doña Cecilia: Buenos días, Tomás. Quiero su opinión sincera sobre mi libro. ¿Qué es lo mejor?","npcEn":"Doña Cecilia: Good morning, Tomás. I want your honest opinion of my book. What is the best thing about it?","intent":"Say the best thing about the book is the poem about the market, speaking to her as usted (use: lo mejor del libro es…).","accept":["Lo mejor del libro es el poema del mercado, doña Cecilia.","Lo mejor de su libro es el poema sobre el mercado.","Para mí, lo mejor del libro es el poema del mercado."],"require":[{"type":"regex","pattern":"\\blo mejor del? \\S+","flags":"iu","label":"use: lo mejor del libro es..."},{"type":"avoidsAny","words":["tu libro","eres"],"label":"use usted, not tú"}],"focus":"p:lo-mejor-de","next":"t2"},{"id":"t2","npc":"Doña Cecilia: Me alegra. Hay versos, sin embargo, que usted encontrará pesados. Sea franco.","npcEn":"Doña Cecilia: I'm glad. There are lines, however, that you will find heavy going. Be frank.","intent":"Say that the last part is a bit heavy going, but that the first part is very engaging (use: pesado, ameno).","accept":["La última parte es un poco pesada, pero la primera es muy amena.","Francamente, el final resulta pesado, aunque el comienzo es amenísimo.","Hay una parte pesada al final, pero el resto es muy ameno."],"require":[{"type":"regex","pattern":"\\b(pesad[oa]s?|pesad[ií]sim[oa]s?)\\b","flags":"iu","label":"say something is heavy going: pesado"},{"type":"regex","pattern":"\\bamen[oa]s?\\b|\\bamen[ií]sim[oa]s?\\b","flags":"iu","label":"say something is engaging: ameno"}],"focus":"p:ameno-pesado","next":"t3"},{"id":"t3","npc":"Doña Cecilia: Se lo agradezco. Dígame, ¿hice bien en leerlo aquí, delante de los vecinos?","npcEn":"Doña Cecilia: Thank you. Tell me, was I right to read it here, in front of the neighbours?","intent":"Reassure her: tell her she was right to read it here (use: hizo bien en…).","accept":["Hizo bien en leerlo aquí, doña Cecilia.","Claro que hizo bien en leerlo aquí. La gente la escuchó con atención.","Hizo muy bien en leerlo delante de todos."],"require":[{"type":"regex","pattern":"\\bhizo (muy )?bien en\\b","flags":"iu","label":"use: hizo bien en + infinitive"},{"type":"avoidsAny","words":["hiciste"],"label":"use usted (hizo), not tú (hiciste)"}],"focus":"p:haces-bien-en","next":"t4"},{"id":"t4","npc":"Doña Cecilia: Entonces dejaré el libro sobre el mostrador, al lado del de Hernando. Una poeta nunca se va sin un café.","npcEn":"Doña Cecilia: Then I'll leave the book on the counter, next to Hernando's. A poet never leaves without a coffee.","intent":"Thank her and offer her a coffee on the house, as a question with usted.","accept":["Gracias, doña Cecilia. ¿Le sirvo un tinto?","Muchas gracias. ¿Le provoca un tinto? Invita la casa.","Con mucho gusto. ¿Le preparo un café?"],"require":[{"type":"question"},{"type":"avoidsAny","words":["te sirvo","quieres"],"label":"use usted (le), not tú (te)"}],"focus":"p:haces-bien-en","next":null}],"r":["g:commands-usted","g:future-promises","g:gender-articles","g:ser-identity","p:ameno-pesado","p:haces-bien-en","p:lo-mejor-de"],"d":517,"spare":true},
{"id":"sc-u60-e","unit":"u60","band":"C1","title":"Para chuparse los dedos","brief":"You're Tomás. Vale has made a new dessert for the reopening and wants your verdict before it goes on the menu. She is quick and dry, and you're friends, so use tú. Judge it, ask a fair question, and say what the café needs next.","turns":[{"id":"t1","npc":"Vale: Prueba esto. Es mi pastel de chocolate nuevo. Y no me mientas.","npcEn":"Vale: Try this. It's my new chocolate cake. And don't lie to me.","intent":"Say it is finger-licking good (use: para chuparse los dedos).","accept":["Está para chuparse los dedos, Vale.","Es un pastel para chuparse los dedos.","Te quedó para chuparse los dedos."],"require":[{"type":"regex","pattern":"\\bpara chuparse los dedos\\b","flags":"iu","label":"use: para chuparse los dedos"}],"focus":"c:para-chuparse-los-dedos","next":"t2"},{"id":"t2","npc":"Vale: ¿En serio? ¿Y la masa? La probé veinte veces hasta dar con el punto.","npcEn":"Vale: Really? And the dough? I tried it twenty times until I got it just right.","intent":"Say the dough is done to perfection (use: a la perfección).","accept":["La masa está hecha a la perfección.","Está a la perfección, se nota que la probaste mucho.","Sí, la masa te salió a la perfección."],"require":[{"type":"regex","pattern":"\\ba la perfecci[oó]n\\b","flags":"iu","label":"use: a la perfección"}],"focus":"c:a-la-perfeccion","next":"t3"},{"id":"t3","npc":"Vale: Mariana dice que los postres están en pleno auge en Bogotá. ¿Crees que nos conviene vender más?","npcEn":"Vale: Mariana says desserts are booming in Bogotá. Do you think it makes sense for us to sell more?","intent":"Say that, with desserts booming, it makes sense (use: en pleno auge).","accept":["Sí, con los postres en pleno auge nos conviene vender más.","Creo que sí, el negocio de los postres está en pleno auge.","Claro, ahora que todo está en pleno auge, hay que aprovechar."],"require":[{"type":"regex","pattern":"\\ben pleno auge\\b","flags":"iu","label":"use: en pleno auge"}],"focus":"c:en-pleno-auge","next":"t4"},{"id":"t4","npc":"Vale: Lo mejor de este pastel es el precio, ¿no?","npcEn":"Vale: The best thing about this cake is the price, isn't it?","intent":"Disagree playfully: the best thing is the taste, and then say where it falls down (use: lo mejor de… es… / donde falla es…).","accept":["No, lo mejor del pastel es el sabor; donde falla es en el precio.","Lo mejor de tu pastel es el sabor. Donde falla es en el tamaño, es pequeño.","Lo mejor del pastel es el chocolate, y donde falla es en el precio."],"require":[{"type":"regex","pattern":"\\blo mejor de(l| la| tu| este| esta)? \\S+","flags":"iu","label":"use: lo mejor de... es..."},{"type":"regex","pattern":"\\bdonde falla es\\b","flags":"iu","label":"use: donde falla es..."}],"focus":"p:lo-mejor-de","next":null}],"r":["c:a-la-perfeccion","c:en-pleno-auge","c:para-chuparse-los-dedos","g:gender-articles","g:ser-identity","g:stem-boot","p:lo-mejor-de"],"d":655,"spare":true},
{"id":"sc-u60-f","unit":"u60","band":"C1","title":"Ensayo con goteras","brief":"You're Tomás, watching the neighbourhood theatre group rehearse in the café. Mariana is writing about it and asks you for quotable lines. She is a friend, so use tú. Be funny and fair.","turns":[{"id":"t1","npc":"Mariana: Llevan dos horas ensayando la obra y no se ha caído nadie. ¿Qué te parece la coreografía?","npcEn":"Mariana: They've been rehearsing the play for two hours and nobody has fallen over. What do you think of the choreography?","intent":"Say, politely, that it leaves a lot to be desired (use: deja mucho que desear).","accept":["Con cariño, la coreografía deja mucho que desear.","La verdad es que la coreografía deja mucho que desear.","Es linda, pero deja bastante que desear."],"require":[{"type":"regex","pattern":"\\bdeja(ba)? (mucho|bastante) que desear\\b","flags":"iu","label":"use: deja mucho que desear"}],"focus":"p:dejar-mucho-que-desear","next":"t2"},{"id":"t2","npc":"Mariana: Y el final, cuando el actor llora con el sombrero en la mano.","npcEn":"Mariana: And the ending, when the actor cries with his hat in his hand.","intent":"Say the ending borders on the ridiculous (use: roza el ridículo).","accept":["El final roza el ridículo, pero es tierno.","Ese llanto con el sombrero roza el ridículo.","Para mí, esa escena roza el ridículo."],"require":[{"type":"regex","pattern":"\\broza(ba)? el rid[ií]culo\\b","flags":"iu","label":"use: roza el ridículo"}],"focus":"p:rozar-el-ridiculo","next":"t3"},{"id":"t3","npc":"Mariana: Salta a la vista que ensayaron poco. ¿Tú lo notaste?","npcEn":"Mariana: It's glaringly obvious they rehearsed little. Did you notice it?","intent":"Say yes, it's obvious, but add something good about the text (use: salta a la vista).","accept":["Sí, salta a la vista, pero el guionista dio en el clavo con el texto.","Claro que salta a la vista. Aun así, el texto es un acierto.","Salta a la vista, sí. Aunque el guionista escribió un texto de lo más ameno."],"require":[{"type":"regex","pattern":"\\bsalta a la vista\\b","flags":"iu","label":"use: salta a la vista"}],"focus":"p:saltar-a-la-vista","next":"t4"},{"id":"t4","npc":"Mariana: Perfecto, esto va a la columna. ¿Una última frase para el titular?","npcEn":"Mariana: Perfect, this goes in the column. One last line for the headline?","intent":"Give her a line for the headline with de lo más + adjective.","accept":["Una noche de lo más divertida en La Esquina de Rosa.","Un ensayo de lo más entrañable, con goteras y todo.","Una función de lo más original."],"require":[{"type":"regex","pattern":"\\bde lo m[aá]s \\S+","flags":"iu","label":"use: de lo más + adjective"}],"focus":"p:de-lo-mas-adj","next":null}],"r":["g:gender-articles","g:present-ar","p:de-lo-mas-adj","p:dejar-mucho-que-desear","p:rozar-el-ridiculo","p:saltar-a-la-vista"],"d":653,"spare":true},
{"id":"sc-u60-g","unit":"u60","band":"C1","title":"En el aire","brief":"You're Tomás, a guest on a local radio show. The host introduces the programme and asks about the café. You play yourself, so use usted if he does, and keep answers open but clear.","turns":[{"id":"t1","npc":"Locutor: Bienvenidos. A lo largo de esta charla hablaremos del barrio. Tomás, ¿qué hace especial a su café?","npcEn":"Host: Welcome. Over the course of this talk we'll talk about the neighbourhood. Tomás, what makes your café special?","intent":"Say that your café is not just any café, because it was your grandmother's.","accept":["No es un café cualquiera: era de mi abuela Rosa.","Mi café no es uno cualquiera, porque fue de mi abuela.","Lo especial es que no es un café cualquiera, es el de mi abuela."],"require":[{"type":"regex","pattern":"\\bcualquiera\\b","flags":"iu","label":"use: cualquiera"}],"focus":"p:un-x-cualquiera","next":"t2"},{"id":"t2","npc":"Locutor: Qué bonito. ¿Y volver a abrir fue un acierto, económicamente hablando?","npcEn":"Host: How lovely. And was reopening a good call, economically speaking?","intent":"Say that reopening was a good call, but money is short (use: fue un acierto + infinitive, and plata no hay).","accept":["Fue un acierto reabrir el café, aunque plata no hay.","Reabrir fue un acierto. Plata no hay, pero hay clientes.","Fue un acierto volver a abrir. Plata no hay, claro."],"require":[{"type":"regex","pattern":"\\bfue un acierto\\b","flags":"iu","label":"use: fue un acierto"},{"type":"regex","pattern":"\\bplata no hay\\b","flags":"iu","label":"use: plata no hay"}],"focus":"p:ser-un-acierto","next":"t3"},{"id":"t3","npc":"Locutor: Los oyentes preguntan por el piso original y la barra. ¿Valió la pena conservarlos?","npcEn":"Host: Listeners are asking about the original floor and the counter. Was it worth keeping them?","intent":"Answer with one of your two favourite details, using 'lo mejor de... es...'.","accept":["Sí. Lo mejor de la barra es que todavía huele a café de los años setenta.","Valió la pena. Lo mejor del piso es que cuenta la historia del barrio.","Claro que sí. Lo mejor de todo es que los vecinos reconocen cada baldosa."],"require":[{"type":"regex","pattern":"\\blo mejor de(l| la| todo)? ?\\S*","flags":"iu","label":"use: lo mejor de... es..."}],"focus":"p:lo-mejor-de","next":"t4"},{"id":"t4","npc":"Locutor: Para ir cerrando, ¿un mensaje para los oyentes?","npcEn":"Host: To start wrapping up, a message for the listeners?","intent":"Invite the listeners to come by, and thank the host.","accept":["Vengan cuando quieran, el tinto es de la casa. Gracias por invitarme.","Los espero en la Candelaria. Muchas gracias por esta charla.","Pasen cualquier día por el café. Gracias por la invitación."],"require":[{"type":"regex","pattern":"\\bgracias\\b","flags":"iu","label":"thank the host"}],"focus":"p:a-lo-largo-de-esta-charla","next":null}],"r":["g:gender-articles","g:gerund-ways","g:questions","p:a-lo-largo-de-esta-charla","p:lo-mejor-de","p:ser-un-acierto","p:un-x-cualquiera"],"d":557,"spare":true},
{"id":"sc-u60-h","unit":"u60","band":"C1","title":"El hombre de Altamira","brief":"You're Tomás. A smooth representative from Altamira visits the café, praising it a little too much. Stay polite but firm, use usted (he is a stranger and older), and show you can read between the lines.","turns":[{"id":"t1","npc":"Representante: Qué lugar encantador. Todo aquí es de calidad superior. Qué lástima que el edificio sea tan viejo.","npcEn":"Representative: What a charming place. Everything here is of superior quality. What a pity the building is so old.","intent":"Say, with an evaluative adverb, that the old building is the point (use: sencillamente, francamente, sinceramente...).","accept":["Francamente, el edificio viejo es lo que nos hace distintos.","Sencillamente, esa edad es lo que nos gusta del lugar.","Sinceramente, no cambiaría ni una pared."],"require":[{"type":"regex","pattern":"\\b(sinceramente|francamente|sencillamente|lamentablemente|honestamente|claramente)\\b","flags":"iu","label":"use an adverb like francamente or sencillamente"}],"focus":"g:evaluative-adverbs","next":"t2"},{"id":"t2","npc":"Representante: Nosotros construimos con materiales modernos. Los de aquí son de calidad dudosa, usted lo sabe.","npcEn":"Representative: We build with modern materials. The ones here are of questionable quality, you know that.","intent":"Disagree politely: the best thing about the building is exactly what he calls old (use: lo mejor de… es…).","accept":["Perdone, pero lo mejor de este edificio son sus vigas.","Con respeto, lo mejor del local es la madera original.","No lo creo. Lo mejor de esta casa es lo que usted llama viejo."],"require":[{"type":"regex","pattern":"\\blo mejor de(l| esta| este| la)? \\S+","flags":"iu","label":"use: lo mejor de... es..."},{"type":"avoidsAny","words":["eres","tienes"],"label":"use usted, not tú"}],"focus":"p:lo-mejor-de","next":"t3"},{"id":"t3","npc":"Representante: Le ofrecemos una cifra muy generosa. Piénselo, no es un negocio cualquiera.","npcEn":"Representative: We offer you a very generous figure. Think it over, it's not just any deal.","intent":"Say that for you, this isn't just any café, so the figure doesn't matter (use: poco importa..., fronted).","accept":["Poco importa la cifra, señor. Este no es un café cualquiera.","Mucho me ofrece, pero este no es un café cualquiera.","Poco me importa el dinero cuando se trata de la casa de mi abuela."],"require":[{"type":"regex","pattern":"^\\W*(mucho|poco|dif[ií]cil|f[aá]cil)\\b","flags":"iu","label":"start with the emphasised word: mucho, poco, difícil or fácil"}],"focus":"g:word-order-style","next":"t4"},{"id":"t4","npc":"Representante: Entiendo. Aquí tiene mi tarjeta, por si cambia de opinión.","npcEn":"Representative: I understand. Here is my card, in case you change your mind.","intent":"Take it politely, but say you doubt you will change your mind (use usted).","accept":["Gracias, pero dudo que cambie de opinión.","Se la agradezco. Lamentablemente para usted, no creo que cambie de opinión.","La guardo, pero sinceramente no creo que cambie de opinión."],"require":[{"type":"avoidsAny","words":["cambies","tu opinión"],"label":"use usted, not tú"}],"focus":"g:evaluative-adverbs","next":null}],"r":["g:adjective-agreement","g:direct-objects","g:evaluative-adverbs","g:gender-articles","g:present-er-ir","g:ser-identity","g:word-order-style","p:lo-mejor-de"],"d":null,"spare":true},
{"id":"sc-u60-i","unit":"u60","band":"C1","title":"Una tarde en la tertulia","brief":"You're Tomás. Florencia, a poet visiting from Cali, comes to the Thursday tertulia. You're about her age, so use tú. Tell her what it's like, give your view of a reading, and invite her back.","turns":[{"id":"t1","npc":"Florencia: Hola, ¿tú eres Tomás? Me dijeron que acá hay tertulia todos los jueves. ¿Qué tal es?","npcEn":"Florencia: Hi, are you Tomás? They told me there's a tertulia here every Thursday. What's it like?","intent":"Say it's very engaging and that you'd say it's not an ordinary tertulia (use: ameno, cualquiera).","accept":["Es muy amena, y no es una tertulia cualquiera.","La tertulia es amenísima, nada que ver con una tertulia cualquiera.","Te va a gustar, es de lo más amena. No es una tertulia cualquiera."],"require":[{"type":"regex","pattern":"\\bamen[oa]s?\\b|\\bamen[ií]sim[oa]s?\\b","flags":"iu","label":"say it's engaging: ameno"},{"type":"regex","pattern":"\\bcualquiera\\b","flags":"iu","label":"use: cualquiera"}],"focus":"p:ameno-pesado","next":"t2"},{"id":"t2","npc":"Florencia: Ojo, que yo leo poesía pesada. Ven a las seis y me cuentas si te gustó.","npcEn":"Florencia: Careful, I read heavy poetry. Come at six and tell me whether you liked it.","intent":"Tell her you'll be there at six, and that you can tell her whether you liked it.","accept":["Aquí estaré a las seis y te cuento si me gustó.","Vengo a las seis, y después te digo si me gustó.","A las seis estaré aquí. Luego te cuento qué me pareció."],"require":[{"type":"regex","pattern":"\\b(seis)\\b","flags":"iu","label":"mention six o'clock"}],"focus":"g:word-order-style","next":"t3"},{"id":"t3","npc":"Florencia: Hoy leyeron una carta de doña Rosa. ¿Qué piensas del texto?","npcEn":"Florencia: Today they read a letter from doña Rosa. What do you think of the text?","intent":"Say Rosa hit the nail on the head, and that you can tell she wrote it with love (use: dar en el clavo, se nota).","accept":["Rosa dio en el clavo: se nota que la escribió con cariño.","Mi abuela dio en el clavo con cada línea. Se nota el cariño.","Dio en el clavo con cada palabra, y se nota que la escribió con cariño."],"require":[{"type":"regex","pattern":"\\bd(io|i|iste|imos|ieron) en el clavo\\b","flags":"iu","label":"use: dio en el clavo"},{"type":"regex","pattern":"\\bse nota\\b","flags":"iu","label":"use: se nota"}],"focus":"p:dar-en-el-clavo","next":"t4"},{"id":"t4","npc":"Florencia: Pues yo vuelvo cualquier jueves. Quien quisiere, que venga, como dice el letrero.","npcEn":"Florencia: Well, I'll come back any Thursday. Whoever wishes to, let them come, as the sign says.","intent":"Say goodbye and invite her to come any day, with coffee on you (use: cualquier día).","accept":["Ven cualquier día, Florencia. El tinto corre por cuenta de la casa.","Cualquier día me parece bien. Hasta pronto, Florencia.","Cualquier día eres bienvenida. Hasta el jueves."],"require":[{"type":"regex","pattern":"\\bcualquier d[ií]a\\b","flags":"iu","label":"use: cualquier día"}],"focus":"x:cualquier-dia-un-dia-cualquiera","next":null}],"r":["g:gender-articles","g:questions","g:stem-boot","g:that-clauses","g:word-order-style","p:ameno-pesado","p:dar-en-el-clavo","x:cualquier-dia-un-dia-cualquiera"],"d":null,"spare":true}
];
